	public class CombatStateWrapper(object combatState)
	{
		private static readonly VariableReference<IRunState> RunStateRef;

		private static readonly VariableReference<IReadOnlyList<Creature>> AlliesRef;

		private static readonly VariableReference<IReadOnlyList<Creature>> EnemiesRef;

		private static readonly VariableReference<IReadOnlyList<ModifierModel>> ModifiersRef;

		private static readonly VariableReference<MultiplayerScalingModel?> MultiplayerScalingModelRef;

		private static readonly VariableReference<int> RoundNumberRef;

		private static readonly VariableReference<CombatSide> CurrentSideRef;

		private static readonly VariableReference<List<Creature>> EscapedCreaturesRef;

		private static readonly VariableReference<IReadOnlyList<Creature>> HittableEnemiesRef;

		public object WrappedState => combatState;

		public IRunState RunState => RunStateRef.Get(combatState);

		public IReadOnlyList<Creature> Allies => AlliesRef.Get(combatState);

		public IReadOnlyList<Creature> Enemies => EnemiesRef.Get(combatState);

		public IReadOnlyList<Creature> Creatures => Allies.Concat(Enemies).ToList();

		public IReadOnlyList<Creature> PlayerCreatures => Creatures.Where((Creature c) => c.IsPlayer).ToList();

		public IReadOnlyList<Player> Players => PlayerCreatures.Select((Creature c) => c.Player).ToList();

		public IReadOnlyList<ModifierModel> Modifiers => ModifiersRef.Get(combatState);

		public MultiplayerScalingModel? MultiplayerScalingModel => MultiplayerScalingModelRef.Get(combatState);

		public int RoundNumber => RoundNumberRef.Get(combatState);

		public CombatSide CurrentSide => CurrentSideRef.Get(combatState);

		public List<Creature> EscapedCreatures => EscapedCreaturesRef.Get(combatState);

		public IReadOnlyList<Creature> HittableEnemies => HittableEnemiesRef.Get(combatState);

		public IReadOnlyList<Creature> CreaturesOnCurrentSide => GetCreaturesOnSide(CurrentSide);

		static CombatStateWrapper()
		{
			Type type = null;
			try
			{
				type = Type.GetType("MegaCrit.Sts2.Core.Combat.ICombatState, sts2");
			}
			catch (Exception)
			{
			}
			if (type == null)
			{
				type = Type.GetType("MegaCrit.Sts2.Core.Combat.CombatState, sts2");
			}
			if (type == null)
			{
				throw new Exception("Failed to get combat state type in CombatStateWrapper for compatibility");
			}
			RunStateRef = new VariableReference<IRunState>(type, "RunState");
			AlliesRef = new VariableReference<IReadOnlyList<Creature>>(type, "Allies");
			EnemiesRef = new VariableReference<IReadOnlyList<Creature>>(type, "Enemies");
			ModifiersRef = new VariableReference<IReadOnlyList<ModifierModel>>(type, "Modifiers");
			MultiplayerScalingModelRef = new VariableReference<MultiplayerScalingModel>(type, "MultiplayerScalingModel");
			RoundNumberRef = new VariableReference<int>(type, "RoundNumber");
			CurrentSideRef = new VariableReference<CombatSide>(type, "CurrentSide");
			EscapedCreaturesRef = new VariableReference<List<Creature>>(type, "EscapedCreatures");
			HittableEnemiesRef = new VariableReference<IReadOnlyList<Creature>>(type, "HittableEnemies");
		}

		public IReadOnlyList<Creature> GetCreaturesOnSide(CombatSide side)
		{
			if (side != CombatSide.Enemy)
			{
				return Allies;
			}
			return Enemies;
		}

		public IReadOnlyList<Creature> GetOpponentsOf(Creature creature)
		{
			return GetCreaturesOnSide(MegaCrit.Sts2.Core.Combat.CombatSideExtensions.GetOppositeSide(creature.Side));
		}

		public IReadOnlyList<Creature> GetTeammatesOf(Creature creature)
		{
			return GetCreaturesOnSide(creature.Side);
		}

		public Player? GetPlayer(ulong playerId)
		{
			return Players.FirstOrDefault((Player p) => p.NetId == playerId);
		}

		public bool HappenedThisTurn(CombatHistoryEntry entry)
		{
			if (RoundNumber == entry.RoundNumber)
			{
				return CurrentSide == entry.CurrentSide;
			}
			return false;
		}
	}
	public static class ChainedEnumerableExtension
	{
		public static ChainedEnumerable<T> Chain<T>(this IEnumerable<T> enumerable, params IEnumerable<T> additional)
		{
			return new ChainedEnumerable<T>(enumerable, additional);
		}
	}
	public class ChainedEnumerable<T> : IEnumerable<T>, IEnumerable
	{
		private readonly IEnumerable<T>[] _inners;

		public ChainedEnumerable(params IEnumerable<T>[] inners)
		{
			_inners = inners;
		}

		public IEnumerator<T> GetEnumerator()
		{
			IEnumerable<T>[] inners = _inners;
			foreach (IEnumerable<T> enumerable in inners)
			{
				foreach (T item in enumerable)
				{
					yield return item;
				}
			}
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
	public static class CommonActions
	{
		[Obsolete("Use an overload that receives a CardPlay parameter. This is required on the beta branch.")]
		public static AttackCommand CardAttack(CardModel card, Creature? target, int hitCount = 1, string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			if (card.DynamicVars.ContainsKey("CalculatedDamage"))
			{
				return CardAttack(card, target, card.DynamicVars.CalculatedDamage, card.DynamicVars.CalculatedDamage.Props, hitCount, vfx, sfx, tmpSfx);
			}
			if (card.DynamicVars.ContainsKey("Damage"))
			{
				return CardAttack(card, target, card.DynamicVars.Damage.BaseValue, card.DynamicVars.Damage.Props, hitCount, vfx, sfx, tmpSfx);
			}
			throw new Exception("Card " + card.Title + " does not have a damage variable supported by CommonActions.CardAttack");
		}

		public static AttackCommand CardAttack(CardModel card, CardPlay? play, int hitCount = 1, string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			if (card.DynamicVars.ContainsKey("CalculatedDamage"))
			{
				return CardAttack(card, play, play?.Target, card.DynamicVars.CalculatedDamage, card.DynamicVars.CalculatedDamage.Props, hitCount, vfx, sfx, tmpSfx);
			}
			if (card.DynamicVars.ContainsKey("Damage"))
			{
				return CardAttack(card, play, play?.Target, card.DynamicVars.Damage.BaseValue, card.DynamicVars.Damage.Props, hitCount, vfx, sfx, tmpSfx);
			}
			throw new Exception("Card " + card.Title + " does not have a damage variable supported by CommonActions.CardAttack");
		}

		[Obsolete("Use the variant that has a CardPlay as the second parameter instead. This will be required for the beta branch.If no CardPlay is available, use null.")]
		public static AttackCommand CardAttack(CardModel card, Creature? target, decimal damage, int hitCount = 1, string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			return CardAttack(card, target, damage, ValueProp.Move, hitCount, vfx, sfx, tmpSfx);
		}

		[Obsolete("Use the variant that has a CardPlay as the second parameter instead. This will be required for the beta branch.If no CardPlay is available, use null.")]
		public static AttackCommand CardAttack(CardModel card, Creature? target, decimal damage, ValueProp valueProp, int hitCount = 1, string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			return CardAttack(card, null, target, damage, valueProp, hitCount, vfx, sfx, tmpSfx);
		}

		public static AttackCommand CardAttack(CardModel card, CardPlay? cardPlay, Creature? target, decimal damage, ValueProp valueProp, int hitCount = 1, string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			AttackCommand attackCommand = DamageCmd.Attack(damage).WithHitCount(hitCount).WithValueProp(valueProp)
				.FromCardCompatibility(card, cardPlay);
			if (CustomTargetType.IsCustomSingleTargetType(card.TargetType))
			{
				if (target == null)
				{
					return attackCommand;
				}
				attackCommand.Targeting(target);
			}
			else if (CustomTargetType.IsCustomMultiTargetType(card.TargetType))
			{
				ICombatState combatState = card.CombatState;
				if (combatState == null)
				{
					return attackCommand;
				}
				IEnumerable<Creature> targets = combatState.Creatures.Where((Creature c) => CustomTargetType.CanMultiTarget(card.TargetType, c, card.Owner));
				attackCommand.TargetingFiltered(targets);
			}
			else
			{
				switch (card.TargetType)
				{
				case TargetType.AnyEnemy:
					if (target == null)
					{
						return attackCommand;
					}
					attackCommand.Targeting(target);
					break;
				case TargetType.AllEnemies:
				{
					ICombatState combatState3 = card.CombatState;
					if (combatState3 == null)
					{
						return attackCommand;
					}
					attackCommand.TargetingAllOpponents(combatState3);
					break;
				}
				case TargetType.RandomEnemy:
				{
					ICombatState combatState2 = card.CombatState;
					if (combatState2 == null)
					{
						return attackCommand;
					}
					attackCommand.TargetingRandomOpponents(combatState2);
					break;
				}
				default:
					throw new Exception($"Unsupported AttackCommand target type {card.TargetType} for card {card.Title}");
				}
			}
			if (vfx != null || sfx != null || tmpSfx != null)
			{
				attackCommand.WithHitFx(vfx, sfx, tmpSfx);
			}
			return attackCommand;
		}

