	[HarmonyPatch(typeof(ModelDb), "Init")]
	internal static class CustomCharacterSortPatch
	{
		[HarmonyPostfix]
		public static void ApplySorting()
		{
			if (CustomCharacterUtils.TypesToSort == null)
			{
				BaseLibMain.Logger.Debug("Sorting was already performed.");
				return;
			}
			BaseLibMain.Logger.Debug($"Sorting {CustomContentDictionary.CustomCharacters.Count} custom characters with {CustomCharacterUtils.TypesToSort.Count} declared sort orders.");
			foreach (List<CustomCharacterModel> item in CustomCharacterUtils.TypesToSort.Select((List<Type> list) => ((IEnumerable<Type>)list).Select((Func<Type, AbstractModel>)ModelDb.Get).OfType<CustomCharacterModel>().ToList()))
			{
				List<CustomCharacterModel> characters = item;
				CustomContentDictionary.CustomCharacters.Sort(Comparison);
				int Comparison(CustomCharacterModel y, CustomCharacterModel x)
				{
					return characters.IndexOf(y) - characters.IndexOf(x);
				}
			}
			CustomCharacterUtils.TypesToSort = null;
		}
	}
	public static class CustomLocTableManager
	{
		private static readonly HashSet<string> LocTables = new HashSet<string>();

		internal static IEnumerable<string> GetCustomLocTables(IEnumerable<string> original)
		{
			List<string> list = new List<string>();
			list.AddRange(original);
			list.AddRange(LocTables);
			return new global::<>z__ReadOnlyList<string>(list);
		}

		public static void Register(string name)
		{
			if (!name.EndsWith(".json"))
			{
				name += ".json";
			}
			LocTables.Add(name);
		}

		public static void RegisterCustomLocTable(this LocManager locManager, string name)
		{
			Register(name);
		}
	}
	public sealed class DynamicVarSource
	{
		public required DynamicVarSet DynamicVars { get; init; }

		public required Creature? Owner { get; init; }

		public CardModel? Card { get; init; }

		public RelicModel? Relic { get; init; }

		public PowerModel? Power { get; init; }

		public static implicit operator DynamicVarSource(CardModel card)
		{
			return new DynamicVarSource
			{
				DynamicVars = card.DynamicVars,
				Owner = ((card != null && card.IsMutable && card.Owner != null) ? card.Owner.Creature : null),
				Card = card
			};
		}

		public static implicit operator DynamicVarSource(RelicModel relic)
		{
			return new DynamicVarSource
			{
				DynamicVars = relic.DynamicVars,
				Owner = ((relic != null && relic.IsMutable && relic.Owner != null) ? relic.Owner.Creature : null),
				Relic = relic
			};
		}

		public static implicit operator DynamicVarSource(PowerModel power)
		{
			return new DynamicVarSource
			{
				DynamicVars = power.DynamicVars,
				Owner = ((power != null && power.IsMutable && power.Owner != null) ? power.Owner : null),
				Power = power
			};
		}

		public static implicit operator DynamicVarSource(PotionModel potion)
		{
			return new DynamicVarSource
			{
				DynamicVars = potion.DynamicVars,
				Owner = ((potion != null && potion.IsMutable && potion.Owner != null) ? potion.Owner.Creature : null)
			};
		}

		public static implicit operator DynamicVarSource(EnchantmentModel enchant)
		{
			DynamicVarSource obj = new DynamicVarSource
			{
				DynamicVars = enchant.DynamicVars
			};
			object owner;
			if (enchant != null && enchant.IsMutable)
			{
				CardModel card = enchant.Card;
				if (card != null && card.IsMutable && card.Owner != null)
				{
					owner = enchant.Card.Owner.Creature;
					goto IL_004a;
				}
			}
			owner = null;
			goto IL_004a;
			IL_004a:
			obj.Owner = (Creature?)owner;
			obj.Card = enchant.Card;
			return obj;
		}

		public static implicit operator DynamicVarSource(CardModifier modifier)
		{
			DynamicVarSource obj = new DynamicVarSource
			{
				DynamicVars = modifier.DynamicVars
			};
			CardModel? owner = modifier.Owner;
			obj.Owner = ((owner == null || !owner.IsMutable) ? null : modifier.Owner?.Owner.Creature);
			obj.Card = modifier.Owner;
			return obj;
		}
	}
