	public class OptionPools
	{
		private WeightedList<AncientOption>[] _pools;

		public IEnumerable<AncientOption> AllOptions => _pools.SelectMany((WeightedList<AncientOption> pool) => pool);

		public OptionPools(WeightedList<AncientOption> pool1, WeightedList<AncientOption> pool2, WeightedList<AncientOption> pool3)
		{
			_pools = new WeightedList<AncientOption>[3] { pool1, pool2, pool3 };
		}

		public OptionPools(WeightedList<AncientOption> pool12, WeightedList<AncientOption> pool3)
		{
			_pools = new WeightedList<AncientOption>[3] { pool12, pool12, pool3 };
		}

		public OptionPools(WeightedList<AncientOption> pool)
		{
			_pools = new WeightedList<AncientOption>[3] { pool, pool, pool };
		}

		public List<AncientOption> Roll(Rng rng, AncientEventModel ancient)
		{
			List<AncientOption> list = new List<AncientOption>();
			WeightedList<AncientOption> weightedList = _pools[0];
			WeightedList<AncientOption> weightedList2 = new WeightedList<AncientOption>();
			foreach (AncientOption item in weightedList.Where((AncientOption option) => option.ModelForOption.RelicCanSpawnAtCustomAncient(ancient)))
			{
				weightedList2.Add(item);
			}
			WeightedList<AncientOption> weightedList3 = weightedList2;
			list.Add(weightedList3.GetRandom(rng, remove: true));
			if (weightedList != _pools[1])
			{
				weightedList = _pools[1];
				weightedList2 = new WeightedList<AncientOption>();
				foreach (AncientOption item2 in weightedList.Where((AncientOption option) => option.ModelForOption.RelicCanSpawnAtCustomAncient(ancient)))
				{
					weightedList2.Add(item2);
				}
				weightedList3 = weightedList2;
			}
			list.Add(weightedList3.GetRandom(rng, remove: true));
			if (weightedList != _pools[2])
			{
				weightedList = _pools[2];
				weightedList2 = new WeightedList<AncientOption>();
				foreach (AncientOption item3 in weightedList.Where((AncientOption option) => option.ModelForOption.RelicCanSpawnAtCustomAncient(ancient)))
				{
					weightedList2.Add(item3);
				}
				weightedList3 = weightedList2;
			}
			list.Add(weightedList3.GetRandom(rng, remove: true));
			return list;
		}
	}
	[AttributeUsage(AttributeTargets.Class, Inherited = true, AllowMultiple = false)]
	public sealed class PoolAttribute : Attribute
	{
		private Type? _poolType;

		private string? _poolClassName;

		public Type? PoolType => _poolType ?? (_poolType = TryGetPoolType());

		public PoolAttribute(Type poolType)
		{
			_poolType = poolType;
		}

		public PoolAttribute(string poolClassName)
		{
			_poolClassName = poolClassName;
		}

		private Type? TryGetPoolType()
		{
			if (_poolClassName == null)
			{
				return null;
			}
			Type type = AccessTools.TypeByName(_poolClassName);
			if (type == null)
			{
				BaseLibMain.Logger.Debug("Failed to find pool type " + _poolClassName + " by name.");
			}
			return type;
		}
	}
	public static class ReflectionUtils
	{
		private const BindingFlags DeclaredOnlyLookup = BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

		public static Action<T?, TValue> GetSetterForProperty<T, TValue>(string propName) where T : class
		{
			return GetPropertySetter(typeof(T).GetProperty(propName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic) ?? throw new InvalidOperationException("Property " + propName + " not found in type " + typeof(T).FullName));
			static Action<T?, TValue> GetPropertySetter(PropertyInfo prop)
			{
				MethodInfo setter = prop.GetSetMethod(nonPublic: true);
				if ((object)setter != null)
				{
					return delegate(T? obj, TValue value)
					{
						setter.Invoke(obj, new object[1] { value });
					};
				}
				FieldInfo backingField = prop.DeclaringType?.GetField("<" + prop.Name + ">k__BackingField", BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
				if ((object)backingField == null)
				{
					throw new InvalidOperationException($"Could not find a way to set {prop.DeclaringType?.FullName}.{prop.Name}. Try adding a private setter.");
				}
				return delegate(T? obj, TValue value)
				{
					backingField.SetValue(obj, value);
				};
			}
		}

		public static Action<object?, TValue> GetSetterForProperty<TValue>(Type type, string propName)
		{
			return GetPropertySetter(type.GetProperty(propName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic) ?? throw new InvalidOperationException("Property " + propName + " not found in type " + type.FullName));
			static Action<object?, TValue> GetPropertySetter(PropertyInfo prop)
			{
