	internal interface IAddedNodes<TParentType> where TParentType : Node
	{
		protected static List<IAddedNodes<TParentType>> _addedNodes = new List<IAddedNodes<TParentType>>();

		private static bool _patched = false;

		Node? GetNode(TParentType obj);

		protected static void PatchNodeReady()
		{
			if (_patched)
			{
				return;
			}
			_patched = true;
			BaseLibMain.Logger.Info("Patching type " + typeof(TParentType).Name + " to add nodes.");
			Harmony mainHarmony = BaseLibMain.MainHarmony;
			MethodInfo methodInfo = AccessTools.DeclaredMethod(typeof(TParentType), "_Ready", Array.Empty<Type>());
			if (methodInfo != null)
			{
				MethodInfo methodInfo2 = typeof(IAddedNodes<TParentType>).DeclaredMethod("UnconditionalAdd");
				BaseLibMain.Logger.Info("Adding postfix " + methodInfo2.FullDescription());
				mainHarmony.Patch(methodInfo, null, methodInfo2);
				return;
			}
			methodInfo = AccessTools.Method(typeof(TParentType), "_Ready", Array.Empty<Type>());
			if (methodInfo == null)
			{
				BaseLibMain.Logger.Error("Failed to patch _Ready method for type " + typeof(TParentType).Name + " to add nodes; _Ready method not found.");
				return;
			}
			MethodInfo methodInfo3 = typeof(IAddedNodes<TParentType>).DeclaredMethod("ConditionalAdd");
			BaseLibMain.Logger.Info("Adding postfix " + methodInfo3.FullDescription());
			mainHarmony.Patch(methodInfo, null, methodInfo3);
		}

		private static void UnconditionalAdd(TParentType __instance)
		{
			foreach (IAddedNodes<TParentType> addedNode in _addedNodes)
			{
				Node node = addedNode.GetNode(__instance);
				if (((Node)__instance).IsAncestorOf(node))
				{
					break;
				}
				((Node)__instance).AddChild(node, false, (InternalMode)0);
			}
		}

		private static void ConditionalAdd(object __instance)
		{
			TParentType val = (TParentType)((__instance is TParentType) ? __instance : null);
			if (val != null)
			{
				UnconditionalAdd(val);
			}
		}
	}
