	public class TooltipSource
	{
		private readonly Func<CardModel, IHoverTip> _makeTip;

		public TooltipSource(Func<CardModel, IHoverTip> tip)
		{
			_makeTip = tip;
		}

		public IHoverTip Tip(CardModel card)
		{
			return _makeTip(card);
		}

		public static implicit operator TooltipSource(Type t)
		{
			if (t.IsAssignableTo(typeof(PowerModel)))
			{
				return new TooltipSource((CardModel card) => HoverTipFactory.FromPower(ModelDb.GetById<PowerModel>(ModelDb.GetId(t))));
			}
			if (t.IsAssignableTo(typeof(CardModel)))
			{
				return new TooltipSource((CardModel card) => HoverTipFactory.FromCard(ModelDb.GetById<CardModel>(ModelDb.GetId(t))));
			}
			if (t.IsAssignableTo(typeof(PotionModel)))
			{
				return new TooltipSource((CardModel card) => HoverTipFactory.FromPotion(ModelDb.GetById<PotionModel>(ModelDb.GetId(t))));
			}
			if (t.IsAssignableTo(typeof(EnchantmentModel)))
			{
				return new TooltipSource((CardModel card) => ModelDb.GetById<EnchantmentModel>(ModelDb.GetId(t)).HoverTip);
			}
			throw new Exception($"Unable to generate hovertip from type {t}");
		}

		public static implicit operator TooltipSource(CardKeyword keyword)
		{
			return new TooltipSource((CardModel card) => HoverTipFactory.FromKeyword(keyword));
		}

		public static implicit operator TooltipSource(StaticHoverTip staticTip)
		{
			return new TooltipSource((CardModel card) => HoverTipFactory.Static(staticTip));
		}
	}
	public interface IWeighted
	{
		int Weight { get; }
	}
	public class WeightedList<T> : IList<T>, ICollection<T>, IEnumerable<T>, IEnumerable
	{
		private class WeightedItem
		{
			public int Weight { get; }

			public T Val { get; set; }

			public WeightedItem(T val, int weight)
			{
				Weight = weight;
				Val = val;
			}
		}

		private readonly List<WeightedItem> _items = new List<WeightedItem>();

		private int _totalWeight;

		public int Count => _items.Count;

		public bool IsReadOnly => false;

		public T this[int index]
		{
			get
			{
				return _items[index].Val;
			}
			set
			{
				_items[index].Val = value;
			}
		}

		public T GetRandom(Rng rng)
		{
			return GetRandom(rng, remove: false);
		}

		public T GetRandom(Rng rng, bool remove)
		{
			if (Count == 0)
			{
				throw new IndexOutOfRangeException("Attempted to roll on empty WeightedList");
			}
			int num = rng.NextInt(_totalWeight);
			int num2 = 0;
			WeightedItem weightedItem = null;
			foreach (WeightedItem item in _items)
			{
				if (num2 + item.Weight > num)
				{
					weightedItem = item;
					break;
				}
				num2 += item.Weight;
			}
			if (weightedItem != null)
			{
				if (remove)
				{
					_items.Remove(weightedItem);
					_totalWeight -= weightedItem.Weight;
				}
				return weightedItem.Val;
			}
			throw new Exception($"Roll {num} failed to get a value in list of total weight {_totalWeight}");
		}

		public IEnumerator<T> GetEnumerator()
		{
			return _items.Select((WeightedItem item) => item.Val).GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public void Add(T item)
		{
			Add(item, (!(item is IWeighted weighted)) ? 1 : weighted.Weight);
		}

		public void Add(T item, int weight)
		{
			_totalWeight += weight;
			_items.Add(new WeightedItem(item, weight));
		}

		public void Clear()
		{
			_items.Clear();
			_totalWeight = 0;
		}

		public bool Contains(T val)
		{
			return _items.Any((WeightedItem item) => object.Equals(item.Val, val));
		}

		public void CopyTo(T[] array, int arrayIndex)
		{
			_items.Select((WeightedItem item) => item.Val).ToList().CopyTo(array, arrayIndex);
		}

		public bool Remove(T val)
		{
			WeightedItem weightedItem = _items.Find((WeightedItem item) => object.Equals(item.Val, val));
			if (weightedItem != null)
			{
				_items.Remove(weightedItem);
				_totalWeight -= weightedItem.Weight;
				return true;
			}
			return false;
		}

		public int IndexOf(T val)
		{
			return _items.FirstIndex((WeightedItem item) => object.Equals(item.Val, val));
		}

		public void Insert(int index, T item)
		{
			Insert(index, item, 1);
		}

		public void Insert(int index, T item, int weight)
		{
			_items.Insert(index, new WeightedItem(item, weight));
			_totalWeight += weight;
		}

		public void RemoveAt(int index)
		{
			WeightedItem weightedItem = _items[index];
			_items.RemoveAt(index);
			_totalWeight -= weightedItem.Weight;
		}
	}
	public static class WhatMod
	{
		private static readonly FieldInfo? AssemblyField = AccessTools.DeclaredField(typeof(Mod), "assembly");

		private static readonly FieldInfo? AssembliesField = AccessTools.DeclaredField(typeof(Mod), "assemblies");

		private static IReadOnlyList<Mod> _loadedMods = Array.Empty<Mod>();

		private static bool _built;

		private static readonly Assembly BasegameAssembly = typeof(Really).Assembly;

		private static readonly Dictionary<Mod, List<Assembly>> AssembliesByMod = new Dictionary<Mod, List<Assembly>>();

		private static readonly Dictionary<Assembly, Mod> ModByAssembly = new Dictionary<Assembly, Mod>();

		private static readonly Dictionary<Type, Mod?> ModByType = new Dictionary<Type, Mod>();

		public static List<Assembly> AssembliesForMod(Mod mod)
		{
			return AssembliesByMod.GetValueOrDefault(mod, new List<Assembly>());
		}

		internal static void BuildAfterInit()
		{
			if (_built)
			{
				return;
			}
			_built = true;
			_loadedMods = ModManager.GetLoadedMods().ToList();
			foreach (Mod loadedMod in _loadedMods)
			{
				CheckAssembly(loadedMod);
			}
		}

		private static void CheckAssembly(Mod mod)
		{
			List<Assembly> list = null;
			if (AssemblyField != null)
			{
				Assembly assembly = (Assembly)AssemblyField.GetValue(mod);
				if (assembly != null)
				{
					int num = 1;
					List<Assembly> list2 = new List<Assembly>(num);
					CollectionsMarshal.SetCount(list2, num);
					Span<Assembly> span = CollectionsMarshal.AsSpan(list2);
					int index = 0;
					span[index] = assembly;
					list = list2;
				}
			}
			else if (AssembliesField != null)
			{
				List<Assembly> list3 = (List<Assembly>)AssembliesField.GetValue(mod);
				if (list3 != null)
				{
					AssembliesByMod[mod] = list3.ToList();
				}
			}
			else
			{
				BaseLibMain.Logger.Warn("Unable to find assemblies tied to mods.");
			}
			if (list == null)
			{
				return;
			}
			AssembliesByMod[mod] = list;
			foreach (Assembly item in list)
			{
				ModByAssembly[item] = mod;
			}
		}

		public static Mod? FindMod(Type type)
		{
			if (!_built)
			{
				return null;
			}
			if (type.Assembly.Equals(BasegameAssembly))
			{
				return null;
			}
			if (ModByType.TryGetValue(type, out Mod value))
			{
				return value;
			}
			if (!ModByAssembly.TryGetValue(type.Assembly, out Mod value2))
			{
				string root = type.GetRootNamespace();
				value2 = _loadedMods.FirstOrDefault((Mod m) => m.manifest?.id != null && m.manifest.id.Equals(root, StringComparison.OrdinalIgnoreCase));
			}
			ModByType[type] = value2;
			return value2;
		}

		public static string? FindModName<T>()
		{
			return FindModName(typeof(T));
		}

		public static string? FindModName(Type type)
		{
			if (type.Assembly.Equals(BasegameAssembly))
			{
				return null;
			}
			Mod? mod = FindMod(type);
			string text = mod?.manifest?.name;
			string text2 = mod?.manifest?.id ?? type.GetRootNamespace();
			if (string.IsNullOrWhiteSpace(text))
			{
				return text2;
			}
			if (string.IsNullOrWhiteSpace(text2) || text2.Equals(text, StringComparison.OrdinalIgnoreCase))
			{
				return text;
			}
			if (!BaseLibConfig.IncludeModId)
			{
				return text;
			}
			return text + " (" + text2 + ")";
		}
	}
