					{
						throw new ArgumentException($"resultName set to return patching method with return type {returnType} but method to call does not return a value; return type {callMethod.ReturnType}");
					}
					if (!callMethod.ReturnType.GenericTypeArguments[0].IsAssignableTo(returnType))
					{
						throw new ArgumentException($"Cannot assign result of type {callMethod.ReturnType.GenericTypeArguments[0]} to return type {returnType}");
					}
				}
				break;
			case ResultType.ReturnIf:
				if (!callMethod.ReturnType.IsGenericType)
				{
					throw new ArgumentException("resultName set to returnIf but method to call does not return a value; requires bool");
				}
				if (!callMethod.ReturnType.GenericTypeArguments[0].IsAssignableTo(typeof(bool)))
				{
					throw new ArgumentException($"Result  {callMethod.ReturnType.GenericTypeArguments[0]} to return type {returnType}");
				}
				break;
			case ResultType.Named:
			{
				if (!callMethod.ReturnType.IsGenericType)
				{
					throw new ArgumentException("resultName set but method to call does not return a value");
				}
				bool flag2 = false;
				foreach (StateParamInfo item in list)
				{
					if (item.Parameter.Name == resultName)
					{
						flag2 = true;
						break;
					}
				}
				if (!flag2)
				{
					if (!AddedNames.TryGetValue(original, out HashSet<string> value))
					{
						value = new HashSet<string>();
						AddedNames[original] = value;
					}
					value.Add(resultName);
				}
				break;
			}
			}
			BaseLibMain.Logger.Info($"Adding new state {context.NextStateIndex} for method {callMethod.DeclaringType?.Name ?? "???"}.{callMethod.Name} {(flag ? "before" : "after")} {methodBase?.Name ?? stateInfo.Index.ToString()} with result type {resultType} ({resultName})");
			stateSections.InsertState(context, flag, stateInfo, callMethod, list, resultType, resultName);
			return stateSections.Code;
		}

		internal static void TryReadAsyncMethod(MethodBase original, IEnumerable<CodeInstruction> code, ILGenerator generator, out AsyncMethodContext context, out MoveNextSection stateSections)
		{
			Type type = original.DeclaringType ?? throw new ArgumentException("Failed to get state machine type from method '" + original.FullDescription() + "'");
			BaseLibMain.Logger.Info("Reading state machine type [" + type.FullName + "]");
			context = new AsyncMethodContext
			{
				Generator = generator,
				BuilderField = type.FindStateMachineField("t__builder"),
				StateField = type.FindStateMachineField("__state"),
				StateMachineType = type
			};
			using IEnumerator<CodeInstruction> enumerator = code.GetEnumerator();
			enumerator.MoveNext();
			stateSections = MoveNextSection.Read(context, enumerator);
			if (!stateSections.AllStates.Any())
			{
				throw new Exception("Failed to find any states for async method " + original.Name);
			}
		}

		private static StateParamInfo MakeStateParameter(MethodBase method, AsyncMethodContext context, int stringDictLocal, ParameterInfo param)
		{
			if (param.Name == null)
			{
				throw new Exception("Unable to determine parameter name for method to call for async method call");
			}
			Action<List<CodeInstruction>> addLoadInstructions;
			Action<List<CodeInstruction>> addStoreInstructions;
			HashSet<string> value;
			if (param.Name == "__instance")
			{
				if (method.IsStatic)
				{
					throw new ArgumentException("Unable to use __instance parameter when patching static method");
				}
				FieldInfo thisField = context.StateMachineType.FindStateMachineField("__this");
				addLoadInstructions = delegate(List<CodeInstruction> list)
				{
					list.Add(CodeInstruction.LoadArgument(0));
					list.Add(thisField.Ldfld());
				};
				addStoreInstructions = delegate(List<CodeInstruction> list)
				{
					list.Add(new CodeInstruction(OpCodes.Pop));
				};
			}
			else if (AddedNames.TryGetValue(method, out value) && value.Contains(param.Name))
			{
				BaseLibMain.Logger.Debug("Using named result " + param.Name + " in method " + method.Name);
				addLoadInstructions = delegate(List<CodeInstruction> list)
				{
					list.Add(CodeInstruction.LoadLocal(stringDictLocal));
					list.Add(new CodeInstruction(OpCodes.Ldstr, param.Name));
					list.Add(GetNamedMethod.Call());
					if (param.ParameterType.IsValueType)
					{
						list.Add(new CodeInstruction(OpCodes.Unbox_Any, param.ParameterType));
					}
				};
				addStoreInstructions = delegate(List<CodeInstruction> list)
				{
					if (param.ParameterType.IsValueType)
					{
						list.Add(new CodeInstruction(OpCodes.Box, param.ParameterType));
					}
					list.Add(CodeInstruction.LoadLocal(stringDictLocal));
					list.Add(new CodeInstruction(OpCodes.Ldstr, param.Name));
					list.Add(StoreNamedMethod.Call());
				};
			}
			else
			{
				FieldInfo field = context.StateMachineType.FindStateMachineField(param.Name);
				if (!field.FieldType.IsAssignableTo(param.ParameterType))
				{
					throw new ArgumentException($"Unable to pass field {field.Name} of type {field.FieldType} to parameter {param.Name} of type {param.ParameterType}");
				}
				addLoadInstructions = delegate(List<CodeInstruction> list)
				{
					list.Add(CodeInstruction.LoadArgument(0));
					list.Add(field.Ldfld());
				};
				addStoreInstructions = delegate(List<CodeInstruction> list)
				{
					list.Insert(list.Count - 2, CodeInstruction.LoadArgument(0));
					list.Add(field.Stfld());
				};
			}
			return new StateParamInfo(param, addLoadInstructions, addStoreInstructions);
		}
	}
	public class CallMatcher(MethodInfo method) : IMatcher
	{
		public bool Match(List<string> log, List<CodeInstruction> code, int startIndex, out int matchStart, out int matchEnd)
		{
			log.Add("Starting CallMatcher for " + method.Name);
			matchStart = startIndex;
			matchEnd = matchStart;
			for (int i = startIndex; i < code.Count; i++)
			{
				if (code[i].Calls(method))
				{
					matchStart = i;
					matchEnd = i + 1;
					return true;
				}
			}
			return false;
		}
	}
	public interface IMatcher
	{
		bool Match(List<string> log, List<CodeInstruction> code, int startIndex, out int matchStart, out int matchEnd);
	}
	public class InstructionMatcher : IMatcher
	{
		private class InstructionMatch
		{
			[CompilerGenerated]
			private object? <Operand>k__BackingField;

			public OpCode[] Opcodes { get; }

			public Func<object?>? OperandFunc { get; set; }

			public Predicate<CodeInstruction>? CustomMatchPredicate { get; set; }

			public Predicate<object?>? OperandMatchPredicate { get; set; }

			public string? StoreOperandKey { get; set; }

			public bool IsLazy { get; set; }

			public object? Operand
			{
				get
				{
					return OperandFunc?.Invoke() ?? <Operand>k__BackingField;
				}
				[CompilerGenerated]
				private init
				{
					<Operand>k__BackingField = value;
				}
			}

			public InstructionMatch(OpCode opcode, object? operand = null)
			{
				Opcodes = new OpCode[1] { opcode };
				Operand = operand;
			}

			public InstructionMatch(OpCode[] opcodes, object? operand = null)
			{
				Opcodes = opcodes;
				Operand = operand;
			}

			public InstructionMatch(Predicate<CodeInstruction> customMatch)
			{
				CustomMatchPredicate = customMatch;
				Opcodes = Array.Empty<OpCode>();
				Operand = null;
			}

			private bool OperandMatch(CodeInstruction matchTest)
			{
				Predicate<object?>? operandMatchPredicate = OperandMatchPredicate;
				if (operandMatchPredicate == null || operandMatchPredicate(matchTest.operand))
				{
					if (Operand != null)
					{
						return OperandsEquivalent(matchTest.operand, Operand);
					}
					return true;
				}
				return false;
			}

			public static bool OperandsEquivalent(object? operandA, object? operandB)
			{
				if (!object.Equals(ComparisonOperand(operandA), ComparisonOperand(operandB)))
				{
					return object.Equals(operandA, operandB);
				}
				return true;
			}

			private static object? ComparisonOperand(object? operand)
			{
				if (operand is LocalBuilder localBuilder)
				{
					return localBuilder.LocalIndex;
				}
				return operand;
			}

			private bool OpcodeMatch(CodeInstruction matchTest)
			{
				if (Opcodes.Length != 0)
				{
					return Opcodes.Contains(matchTest.opcode);
				}
				return true;
			}

			public override string ToString()
			{
				if (CustomMatchPredicate == null)
				{
					return "[" + Opcodes.AsReadable() + "] " + ((OperandMatchPredicate != null) ? "Operand Predicate" : Operand?.ToString());
				}
				return "[Custom Match]";
			}

			public bool Test(CodeInstruction matchTest, List<string> log)
			{
				if (CustomMatchPredicate != null)
				{
					if (!CustomMatchPredicate(matchTest))
					{
						return false;
					}
					log.Add($"Custom match {matchTest}");
					return true;
				}
				if (OpcodeMatch(matchTest))
				{
					if (OperandMatch(matchTest))
					{
						log.Add($"Instruction match {matchTest}");
						return true;
					}
					log.Add($"Opcode match but operand mismatch {matchTest.opcode} | [{matchTest.operand?.GetType() ?? null}]{matchTest.operand} vs {Operand}");
				}
				return false;
			}
		}

		private readonly List<InstructionMatch> _target = new List<InstructionMatch>();

		private readonly Dictionary<string, object?> _operandDict = new Dictionary<string, object>();

		public bool Match(List<string> log, List<CodeInstruction> code, int startIndex, out int matchStart, out int matchEnd)
		{
			log.Add("Starting InstructionMatcher");
			matchStart = startIndex;
			matchEnd = matchStart;
			int num = 0;
			int num2 = 0;
			for (int i = startIndex; i < code.Count; i++)
			{
				InstructionMatch instructionMatch = _target[num];
				CodeInstruction codeInstruction = code[i];
				if (instructionMatch.Test(codeInstruction, log))
				{
					num2++;
					if (instructionMatch.StoreOperandKey != null)
					{
						log.Add($"Stored operand {instructionMatch.StoreOperandKey}:{codeInstruction.operand}");
						_operandDict[instructionMatch.StoreOperandKey] = codeInstruction.operand;
					}
					num++;
					if (num >= _target.Count)
					{
						matchEnd = i + 1;
						matchStart = matchEnd - num2;
						return true;
					}
				}
				else if (num <= 0)
				{
					num2 = 0;
				}
				else if (instructionMatch.IsLazy)
				{
					num2++;
					log.Add("Ignoring mismatch; current match is lazy");
				}
				else
				{
					log.Add($"Match ended, opcodes do not match ({codeInstruction.opcode}, {instructionMatch.Opcodes})");
					num2 = 0;
					num = 0;
					i--;
				}
			}
			return false;
		}

		public override string ToString()
		{
			return "InstructionMatcher:\n" + _target.AsReadable("\n");
		}

		public InstructionMatcher OperandFromStore(string storeKey)
		{
			if (_target.Count == 0)
			{
				throw new InvalidOperationException("Cannot apply stored operand without adding any instructions");
			}
			List<InstructionMatch> target = _target;
			target[target.Count - 1].OperandFunc = () => _operandDict[storeKey];
			return this;
		}

		public InstructionMatcher StoreOperand(string storeKey)
		{
			if (_target.Count == 0)
			{
				throw new InvalidOperationException("Cannot store operand without adding any instructions");
			}
			List<InstructionMatch> target = _target;
			target[target.Count - 1].StoreOperandKey = storeKey;
			return this;
		}

		public InstructionMatcher PredicateMatch(Predicate<object?> operandCondition)
		{
			if (_target.Count == 0)
			{
				throw new InvalidOperationException("Cannot use predicate for operand without adding any instructions");
			}
			List<InstructionMatch> target = _target;
			target[target.Count - 1].OperandMatchPredicate = operandCondition;
			return this;
		}

		public InstructionMatcher LazyMatch()
		{
			if (_target.Count == 0)
			{
				throw new InvalidOperationException("Cannot use predicate for operand without adding any instructions");
			}
			List<InstructionMatch> target = _target;
			target[target.Count - 1].IsLazy = true;
			return this;
		}

		public InstructionMatcher CustomMatch(Predicate<CodeInstruction> customMatch)
		{
			_target.Add(new InstructionMatch(customMatch));
			return this;
		}

