	internal class BranchingStateSection : IAsyncStateSection, IAsyncMethodSection
	{
		public readonly List<IAsyncStateSection> Sections = new List<IAsyncStateSection>();

		public required Dictionary<Label, int> LabelStates { get; init; }

		public List<CodeInstruction> Prep { get; set; } = new List<CodeInstruction>();

		public required List<CodeInstruction> Branching { get; set; }

		public CodeInstruction ResumeInstruction => Branching.First();

		public List<CodeInstruction> Code
		{
			get
			{
				List<CodeInstruction> list = new List<CodeInstruction>();
				list.AddRange(Prep);
				list.AddRange(Branching);
				list.AddRange(Sections.SelectMany((IAsyncStateSection section) => section.Code));
				return list;
			}
		}

		public IEnumerable<StateInfo> AllStates => Sections.SelectMany((IAsyncStateSection section) => section.AllStates);

		public IEnumerable<Label> LeaveLabels => Sections.SelectMany((IAsyncStateSection section) => section.LeaveLabels);

		public static BranchingStateSection Read(AsyncMethodContext context, LoadStateSection loadStateSection, IEnumerator<CodeInstruction> codeEnumerator)
		{
			BaseLibMain.Logger.Debug("Starting branching section");
			List<CodeInstruction> list = new List<CodeInstruction>();
			Dictionary<int, Label> dictionary = new Dictionary<int, Label>();
			int? num = null;
			int num2 = 0;
			bool flag = false;
			do
			{
				CodeInstruction current = codeEnumerator.Current;
				if (list.Count == 0 || current.opcode == OpCodes.Ldloc_0)
				{
					list.Add(current);
					continue;
				}
				if (current.opcode == OpCodes.Switch)
				{
					Label[] array = (Label[])current.operand;
					for (int i = 0; i < array.Length; i++)
					{
						dictionary[i + num2] = array[i];
					}
					list.Add(current);
					codeEnumerator.MoveNext();
					break;
				}
				if (current.TryGetIntValue(out var result))
				{
					num = result;
					list.Add(current);
					continue;
				}
				switch (current.opcode.Value)
				{
				case 0:
					if (current.labels.Count > 0)
					{
						flag = true;
					}
					break;
				case 89:
					if (!num.HasValue)
					{
						BaseLibMain.Logger.Warn("Failed to evaluate sub, checkState null");
						break;
					}
					if (num2 != 0)
					{
						BaseLibMain.Logger.Warn("Failed to process sub, stateOffset already set");
						break;
					}
					num2 = num.Value;
					num = null;
					BaseLibMain.Logger.Debug($"Branching section uses sub offset of {num2}");
					break;
				case 44:
				case 57:
					dictionary[0] = (Label)current.operand;
					break;
				case 45:
				case 58:
					BaseLibMain.Logger.Warn("Unexpected Brtrue in jump section of state machine");
					break;
				case 46:
				case 59:
					if (!num.HasValue)
					{
						BaseLibMain.Logger.Warn("Failed to evaluate beq, checkState null");
					}
					else
					{
						dictionary[num.Value] = (Label)current.operand;
					}
					break;
				case 43:
				case 56:
				{
					Label value = (Label)current.operand;
					foreach (KeyValuePair<int, Label> item in dictionary)
					{
						foreach (Label label in current.labels)
						{
							if (item.Value == label)
							{
								dictionary[item.Key] = value;
								break;
							}
						}
					}
					break;
				}
				default:
					BaseLibMain.Logger.Debug("Found end of branching section");
					flag = true;
					break;
				}
				if (flag)
				{
					break;
				}
				list.Add(current);
			}
			while (codeEnumerator.MoveNext());
			Dictionary<Label, int> dictionary2 = new Dictionary<Label, int>();
			foreach (KeyValuePair<int, Label> item2 in dictionary)
			{
				dictionary2[item2.Value] = item2.Key;
			}
			BranchingStateSection branchingStateSection = new BranchingStateSection
			{
				Branching = list,
				LabelStates = dictionary2
			};
			while (dictionary.Count > 0)
			{
				IAsyncStateSection asyncStateSection = BranchSection.Read(context, loadStateSection, branchingStateSection, codeEnumerator);
				foreach (StateInfo allState in asyncStateSection.AllStates)
				{
					dictionary.Remove(allState.Index);
				}
				branchingStateSection.Sections.Add(asyncStateSection);
			}
			return branchingStateSection;
		}

		public BranchingStateSection BranchTo(AsyncMethodContext context, StateInfo targetState, ILGenerator generator, out Label resumeLabel)
		{
			foreach (IAsyncStateSection section in Sections)
			{
				if (!section.AllStates.Contains(targetState))
				{
					continue;
				}
				resumeLabel = generator.DefineLabel();
				BaseLibMain.Logger.Debug($"Generating branch instruction in branching section using label {resumeLabel.Id}");
				for (int i = 0; i < Branching.Count; i++)
				{
					if (Branching[i].blocks.Count != 0)
					{
						if (i == 0)
						{
							List<CodeInstruction> list = new List<CodeInstruction>();
							list.Add(CodeInstruction.LoadLocal(0).MoveLabelsFrom(Branching[0]).MoveBlocksFrom(Branching[0]));
							list.Add(context.NextStateIndex.LoadConstant());
							list.Add(new CodeInstruction(OpCodes.Beq, resumeLabel));
							list.AddRange(Branching);
							Branching = list;
						}
						else
						{
							List<CodeInstruction> list2 = new List<CodeInstruction>();
							list2.AddRange(Branching.Take(i));
							list2.Add(CodeInstruction.LoadLocal(0).MoveBlocksFrom(Branching[i]));
							list2.Add(context.NextStateIndex.LoadConstant());
							list2.Add(new CodeInstruction(OpCodes.Beq, resumeLabel));
							list2.AddRange(Branching.Skip(i));
							Branching = list2;
						}
						break;
					}
				}
				if (section is BranchingStateSection branchingStateSection)
				{
					branchingStateSection.ResumeInstruction.WithLabels(resumeLabel);
					return branchingStateSection.BranchTo(context, targetState, generator, out resumeLabel);
				}
				return this;
			}
			throw new InvalidOperationException("Failed to find target state in branching state section.");
		}

		public void InsertState(AsyncMethodContext context, LoadStateSection loadSection, EndingSection endingSection, bool before, StateInfo targetState, MethodInfo callMethod, List<StateParamInfo> methodCallParams, Label resumeLabel, AsyncMethodCall.ResultType resultType, string? resultName)
		{
			int num = Sections.FindIndex((IAsyncStateSection section) => section is BranchSection branchSection && branchSection.State == targetState);
			if (num < 0)
			{
				throw new InvalidOperationException("Failed to find target state in branching state section.");
			}
			if (!before)
			{
				num++;
			}
			Sections.Insert(num, BranchSection.Create(context, loadSection, endingSection, callMethod, methodCallParams, resumeLabel, resultType, resultName));
		}
	}
	internal class BranchSection : IAsyncStateSection, IAsyncMethodSection
	{
		public required CodeInstruction ResumeInstruction { get; init; }

		public required StateInfo State { get; init; }

		public required IEnumerable<Label> LeaveLabels { get; init; }

		public List<CodeInstruction> Code => State.Code;

		public IEnumerable<StateInfo> AllStates => new global::<>z__ReadOnlySingleElementList<StateInfo>(State);

		public static IAsyncStateSection Read(AsyncMethodContext context, LoadStateSection loadStateSection, BranchingStateSection branchSource, IEnumerator<CodeInstruction> codeEnumerator)
		{
			List<CodeInstruction> list = new List<CodeInstruction>();
			List<int> list2 = new List<int>();
			CodeInstruction codeInstruction = null;
			do
			{
				CodeInstruction current = codeEnumerator.Current;
				foreach (Label label in current.labels)
				{
					if (branchSource.LabelStates.TryGetValue(label, out var value))
					{
						BaseLibMain.Logger.Debug($"Found state resume point label {label.Id} for state {value}");
						list2.Add(value);
						codeInstruction = current;
					}
				}
				if (codeInstruction != null)
				{
					BaseLibMain.Logger.VeryDebug("End of state prep");
					break;
				}
				list.Add(current);
			}
			while (codeEnumerator.MoveNext());
			if (list2.Count == 0 || codeInstruction == null)
			{
				throw new Exception("Failed to find state branches.");
			}
			if (list2.Count > 1)
			{
				BaseLibMain.Logger.Debug("Section is destination of multiple states; should be additional branching section.");
				BranchingStateSection branchingStateSection = BranchingStateSection.Read(context, loadStateSection, codeEnumerator);
				branchingStateSection.Prep = list;
				return branchingStateSection;
			}
			int num = list2[0];
			List<CodeInstruction> list3 = list.ToList();
			HashSet<Label> hashSet = new HashSet<Label>();
			bool flag = false;
			do
			{
				CodeInstruction current3 = codeEnumerator.Current;
				if ((current3.opcode == OpCodes.Leave || current3.opcode == OpCodes.Leave_S) && current3.operand is Label item)
				{
					hashSet.Add(item);
				}
				if (current3.opcode == OpCodes.Call && current3.operand is MethodInfo { Name: "GetResult" } methodInfo)
				{
					Type? declaringType = methodInfo.DeclaringType;
					if ((object)declaringType != null && declaringType.Name.StartsWith("TaskAwaiter"))
					{
						flag = true;
						list3.Add(current3);
						continue;
					}
				}
				if (flag)
				{
					if (current3.IsStloc() || current3.opcode == OpCodes.Nop || current3.opcode == OpCodes.Pop)
					{
						list3.Add(current3);
						codeEnumerator.MoveNext();
					}
					StateInfo stateInfo = new StateInfo(num, list3, context.StateField);
					BaseLibMain.Logger.Debug($"Generated StateInfo for state {num}");
					if (stateInfo.Index >= context.NextStateIndex)
					{
						context.NextStateIndex = stateInfo.Index + 1;
					}
					BranchSection branchSection = new BranchSection
					{
						State = stateInfo,
						ResumeInstruction = codeInstruction,
						LeaveLabels = hashSet
					};
					if (loadStateSection.AddStateLoading)
					{
						branchSection.State.AddSaveState(context.StateField, loadStateSection.StringDictLocal);
					}
					return branchSection;
				}
				list3.Add(current3);
			}
			while (codeEnumerator.MoveNext());
			throw new Exception($"Failed to find end of state {num}");
		}

		public static BranchSection Create(AsyncMethodContext context, LoadStateSection loadSection, EndingSection endingSection, MethodInfo callMethod, IEnumerable<StateParamInfo> loadFields, Label resumeLabel, AsyncMethodCall.ResultType resultType, string? resultName)
		{
			ILGenerator generator = context.Generator;
			Type type = typeof(TaskAwaiter);
			Type fieldType = context.BuilderField.FieldType;
			bool isValueType = context.StateMachineType.IsValueType;
			Type type2 = typeof(void);
			if (callMethod.ReturnType.IsGenericType)
			{
				type2 = callMethod.ReturnType.GetGenericArguments()[0];
				BaseLibMain.Logger.Debug($"Method to call has return type; making generic awaiter type [{type2}]");
				type = typeof(TaskAwaiter<>).MakeGenericType(type2);
			}
			MethodInfo method = callMethod.ReturnType.GetMethod("GetAwaiter");
			if (method == null)
			{
				throw new Exception($"Failed to get GetAwaiter for type {callMethod.ReturnType}");
			}
			MethodInfo methodInfo = fieldType.GetMethod("AwaitUnsafeOnCompleted");
			if (methodInfo == null)
			{
				throw new Exception($"Failed to get AwaitUnsafeOnCompleted for type {fieldType}");
			}
			if (methodInfo.IsGenericMethodDefinition)
			{
				methodInfo = methodInfo.MakeGenericMethod(type, context.StateMachineType);
			}
			LocalBuilder localBuilder = generator.DeclareLocal(type);
			MethodInfo operand = type.PropertyGetter("IsCompleted");
			Label label = generator.DefineLabel();
			List<Label> list = new List<Label>();
			List<CodeInstruction> list2 = new List<CodeInstruction>();
			StateParamInfo stateParamInfo = null;
			foreach (StateParamInfo loadField in loadFields)
			{
				if (resultType == AsyncMethodCall.ResultType.Named && loadField.Parameter.Name == resultName)
				{
					stateParamInfo = loadField;
				}
				loadField.AddLoadInstructions(list2);
			}
			if (stateParamInfo != null && !type2.IsAssignableTo(stateParamInfo.Parameter.ParameterType))
			{
				throw new ArgumentException($"Cannot store method result of type {type2} to parameter {stateParamInfo.Parameter.Name} of type {stateParamInfo.Parameter.ParameterType}");
			}
			list2.AddRange(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[6]
			{
				new CodeInstruction(OpCodes.Call, callMethod),
				method.CallVirt(),
				CodeInstruction.StoreLocal(localBuilder.LocalIndex),
				CodeInstruction.LoadLocal(localBuilder.LocalIndex, useAddress: true),
				new CodeInstruction(OpCodes.Call, operand),
				new CodeInstruction(OpCodes.Brtrue, label)
			}));
			list2.AddRange(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[13]
			{
				CodeInstruction.LoadArgument(0),
				context.NextStateIndex.LoadConstant(),
				new CodeInstruction(OpCodes.Call, AsyncMethodCall.StoreStateInDictMethod),
				new CodeInstruction(OpCodes.Dup),
				CodeInstruction.LoadLocal(loadSection.StringDictLocal),
				new CodeInstruction(OpCodes.Call, AsyncMethodCall.StoreDictionaryForStateMethod),
				new CodeInstruction(OpCodes.Dup),
				CodeInstruction.StoreLocal(0),
				context.StateField.Stfld(),
				CodeInstruction.LoadLocal(localBuilder.LocalIndex),
				new CodeInstruction(OpCodes.Box, type),
				CodeInstruction.LoadLocal(0),
				AsyncMethodCall.StoreAwaiterMethod.Call()
			}));
			Label label2 = generator.DefineLabel();
			list.Add(label2);
			endingSection.AwaitAsyncInstruction.WithLabels(label2);
			list2.AddRange(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[6]
			{
				CodeInstruction.LoadArgument(0),
				new CodeInstruction(OpCodes.Ldflda, context.BuilderField),
				CodeInstruction.LoadLocal(localBuilder.LocalIndex, useAddress: true),
				CodeInstruction.LoadArgument(0, !isValueType),
				methodInfo.Call(),
				new CodeInstruction(OpCodes.Leave, label2)
			}));
			CodeInstruction codeInstruction = new CodeInstruction(OpCodes.Nop).WithLabels(resumeLabel);
			list2.AddRange(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[5]
			{
				codeInstruction,
				CodeInstruction.LoadLocal(loadSection.StateKeyLocal),
				AsyncMethodCall.GetAwaiterMethod.Call(),
				new CodeInstruction(OpCodes.Unbox_Any, type),
				CodeInstruction.StoreLocal(localBuilder.LocalIndex)
			}));
			list2.AddRange(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[5]
			{
				CodeInstruction.LoadArgument(0),
				(-1).LoadConstant(),
				new CodeInstruction(OpCodes.Dup),
				CodeInstruction.StoreLocal(0),
				context.StateField.Stfld()
			}));
			list2.Add(new CodeInstruction(OpCodes.Nop).WithLabels(label));
			list2.Add(CodeInstruction.LoadLocal(localBuilder.LocalIndex, useAddress: true));
			list2.Add(CodeInstruction.Call(type, "GetResult"));
			switch (resultType)
			{
			case AsyncMethodCall.ResultType.Return:
			{
				Label label5 = generator.DefineLabel();
				endingSection.FinishAsyncInstruction.WithLabels(label5);
				list2.Add((type2 == typeof(void)) ? new CodeInstruction(OpCodes.Nop) : CodeInstruction.StoreLocal(1));
				list2.Add(new CodeInstruction(OpCodes.Leave, label5));
				break;
			}
			case AsyncMethodCall.ResultType.ReturnIf:
			{
				Label label3 = generator.DefineLabel();
				Label label4 = generator.DefineLabel();
				endingSection.FinishAsyncInstruction.WithLabels(label4);
				list2.Add(new CodeInstruction(OpCodes.Brfalse_S, label3));
				list2.Add(new CodeInstruction(OpCodes.Leave, label4));
				list2.Add(new CodeInstruction(OpCodes.Nop).WithLabels(label3));
				break;
			}
			case AsyncMethodCall.ResultType.Named:
				if (stateParamInfo != null)
				{
					stateParamInfo.AddStoreInstructions(list2);
				}
				else if (resultName != null)
				{
					if (type2.IsValueType)
					{
						list2.Add(new CodeInstruction(OpCodes.Box, type2));
					}
					list2.Add(CodeInstruction.LoadLocal(loadSection.StringDictLocal));
					list2.Add(new CodeInstruction(OpCodes.Ldstr, resultName));
					list2.Add(AsyncMethodCall.StoreNamedMethod.Call());
				}
				break;
			default:
				list2.Add(new CodeInstruction((type2 == typeof(void)) ? OpCodes.Nop : OpCodes.Pop));
				break;
			}
			return new BranchSection
			{
				State = new StateInfo(context.NextStateIndex, list2, callMethod),
				ResumeInstruction = codeInstruction,
				LeaveLabels = list
