			}
			_registeredScenes[scenePath] = (nodeType.Item1, nodeType.Item2 as Action<Node>);
			BaseLibMain.Logger.Info("Registered scene '" + scenePath + "' for auto-conversion to " + nodeType.Item1.Name);
		}

