			string text = StringExtensions.SimplifyPath(((Resource)scene).ResourcePath);
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			if (!_registeredScenes.TryGetValue(text, out (Type, Action<Node>) value))
			{
