	[HarmonyPatch(typeof(NCard), "UpdateTypePlaque")]
	internal class AddSubtypesToTypePlaquePatch
	{
		private const string ArgName = "Type";

		[HarmonyTranspiler]
		private static List<CodeInstruction> AddVisualSubtypes(IEnumerable<CodeInstruction> instructions)
		{
			CodeMatcher codeMatcher = new CodeMatcher(instructions);
			codeMatcher.MatchStartForward(CodeMatch.Calls(typeof(CardTypeExtensions).Method("ToLocString")), CodeMatch.Calls(typeof(LocString).Method("GetFormattedText")), CodeMatch.Calls(typeof(MegaLabel).Method("SetTextAutoSize"))).InsertAfterAndAdvance(CodeInstruction.LoadArgument(0), new CodeInstruction(OpCodes.Call, typeof(NCard).PropertyGetter("Model")), CodeInstruction.Call(typeof(AddSubtypesToTypePlaquePatch), "TryModifyPlaqueText"));
			return codeMatcher.Instructions();
		}

		private static LocString TryModifyPlaqueText(LocString originalPlaqueText, CardModel card)
		{
			IRunState? obj = card.RunState ?? NullRunState.Instance;
			ICombatState combatState = card.CombatState;
			IEnumerable<LocString> enumerable = Array.Empty<LocString>();
			if (card is ICustomTypeTextCard customTypeTextCard)
			{
				enumerable = enumerable.Concat(customTypeTextCard.GetTypeModifiers());
			}
			foreach (AbstractModel item in obj.IterateHookListeners(combatState))
			{
				if (item is ICardTypeTextModifier cardTypeTextModifier)
				{
					enumerable = enumerable.Concat(cardTypeTextModifier.GetTypeModifiers(card));
				}
			}
			ILookup<bool, LocString> lookup = enumerable.ToLookup((LocString locString2) => locString2.GetRawText().Contains("{Type}"));
			foreach (LocString item2 in lookup[false])
			{
				originalPlaqueText = item2;
			}
			LocString locString = originalPlaqueText;
			foreach (LocString item3 in lookup[true])
			{
				item3.Add("Type", locString);
				locString = item3;
			}
			return locString;
		}
	}
	[HarmonyPatch(typeof(NAncientNameBanner), "AnimateVfx")]
	public static class AncientSourceLabel
	{
		private const string LabelName = "BaseLibModSourceLabel";

		[HarmonyPostfix]
		private static void Postfix(NAncientNameBanner __instance, ref Task __result)
		{
			__result = AddAfterSettled(__result, __instance);
		}

		private static async Task AddAfterSettled(Task original, NAncientNameBanner banner)
		{
			await original;
			if (!GodotObject.IsInstanceValid((GodotObject)(object)banner) || !BaseLibConfig.ShowAncientModSource)
			{
				return;
			}
			AncientEventModel value = Traverse.Create(banner).Field("_ancient").GetValue<AncientEventModel>();
			if (value == null)
			{
				return;
			}
			string text = WhatMod.FindModName(value.GetType());
			if (text == null)
			{
				return;
			}
			MegaLabel nodeOrNull = ((Node)banner).GetNodeOrNull<MegaLabel>(NodePath.op_Implicit("%Epithet"));
			if (nodeOrNull != null && ((Node)nodeOrNull).GetNodeOrNull(NodePath.op_Implicit("BaseLibModSourceLabel")) == null)
			{
				MegaLabel megaLabel = new MegaLabel();
				((Node)megaLabel).Name = StringName.op_Implicit("BaseLibModSourceLabel");
				((Control)megaLabel).AnchorRight = 1f;
				((Control)megaLabel).AnchorBottom = 1f;
				((Control)megaLabel).GrowHorizontal = (GrowDirection)2;
				((Control)megaLabel).GrowVertical = (GrowDirection)2;
				((Control)megaLabel).OffsetTop = 26f;
				((Control)megaLabel).OffsetBottom = 26f;
				((Label)megaLabel).HorizontalAlignment = (HorizontalAlignment)0;
				((Label)megaLabel).VerticalAlignment = (VerticalAlignment)2;
				megaLabel.MinFontSize = 11;
				megaLabel.MaxFontSize = 14;
				((Control)megaLabel).MouseFilter = (MouseFilterEnum)2;
				MegaLabel megaLabel2 = megaLabel;
				Font themeFont = ((Control)nodeOrNull).GetThemeFont(StringName.op_Implicit("font"), (StringName)null);
				if (themeFont != null)
				{
					((Control)megaLabel2).AddThemeFontOverride(StringName.op_Implicit("font"), themeFont);
				}
				((Control)megaLabel2).AddThemeColorOverride(StringName.op_Implicit("font_color"), StsColors.cream);
				((Control)megaLabel2).AddThemeColorOverride(StringName.op_Implicit("font_outline_color"), Colors.Transparent);
				megaLabel2.SetTextAutoSize(text ?? "");
				((Node)nodeOrNull).AddChild((Node)(object)megaLabel2, false, (InternalMode)0);
			}
		}
	}
