		internal static void ApplyForCharacter(NCharacterSelectScreen screen, CharacterModel character, Control? focusOrigin)
		{
			//IL_016d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0172: Unknown result type (might be due to invalid IL or missing references)
			//IL_0182: Unknown result type (might be due to invalid IL or missing references)
			//IL_0189: Unknown result type (might be due to invalid IL or missing references)
			//IL_0191: Unknown result type (might be due to invalid IL or missing references)
			//IL_0199: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_01ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_01b8: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c0: Unknown result type (might be due to invalid IL or missing references)
			//IL_01ca: Unknown result type (might be due to invalid IL or missing references)
			//IL_01cb: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d2: Unknown result type (might be due to invalid IL or missing references)
			//IL_01de: Expected O, but got Unknown
			Clear(screen, restoreControllerFocus: true);
			if (!(character is ICustomModel))
			{
				return;
			}
			IReadOnlyList<RelicModel> relics = character.StartingRelics;
			if (relics.Count <= 1)
			{
				return;
			}
			Control nodeOrNull = ((Node)screen).GetNodeOrNull<Control>(NodePath.op_Implicit("InfoPanel/VBoxContainer/Relic"));
			Node parent = ((Node)screen._relicTitle).GetParent();
			Control val = (Control)(object)((parent is Control) ? parent : null);
			if (nodeOrNull == null || val == null)
			{
				BaseLibMain.Logger.Warn($"Unable to add starting relics to the character select panel for {character.Id}.");
				return;
			}
			List<NRelicBasicHolder> list = new List<NRelicBasicHolder>(relics.Count);
			try
			{
				foreach (RelicModel item in relics)
				{
					NRelicBasicHolder nRelicBasicHolder = NRelicBasicHolder.Create(item);
					if (nRelicBasicHolder == null)
					{
						foreach (NRelicBasicHolder item2 in list)
						{
							((Node)(object)item2).QueueFreeSafely();
						}
						return;
					}
					list.Add(nRelicBasicHolder);
				}
				float num = 68f * (float)list.Count + (float)(-8 * (list.Count - 1));
				float num2 = Math.Min(0.75f, 220f / num);
				float visualWidth = num * num2;
				HBoxContainer val2 = new HBoxContainer
				{
					Name = StringName.op_Implicit("BaseLibStartingRelics"),
					LayoutMode = 0,
					MouseFilter = (MouseFilterEnum)2,
					CustomMinimumSize = new Vector2(num, 68f),
					Position = new Vector2(0f, 8f),
					Size = new Vector2(num, 68f),
					Scale = Vector2.One * num2
				};
				((Control)val2).AddThemeConstantOverride(StringName.op_Implicit("separation"), -8);
				StartingRelicRowState state = ScreenStates.Get(screen);
				CaptureOriginalLayout(screen, state, val);
				state.Row = val2;
				state.FocusOrigin = (IsValid((GodotObject?)(object)focusOrigin) ? focusOrigin : null);
				if (state.FocusOrigin != null)
				{
					state.OriginalFocusNeighborTop = state.FocusOrigin.FocusNeighborTop;
				}
				state.Holders.AddRange(list);
				foreach (var item3 in list.Zip(relics))
				{
					var (holder, relic) = item3;
					((Control)holder).MouseDefaultCursorShape = (CursorShape)16;
					holder.Released += delegate
					{
						NGame.Instance?.GetInspectRelicScreen().Open(relics, relic);
					};
					holder.Focused += delegate
					{
						SetRelicDetails(screen, relic);
						if (IsValid((GodotObject?)(object)state.FocusOrigin) && IsValid((GodotObject?)(object)holder))
						{
							state.FocusOrigin.FocusNeighborTop = ((Node)holder).GetPath();
						}
					};
					((Node)(object)val2).AddChildSafely((Node?)(object)holder);
				}
				((Node)(object)nodeOrNull).AddChildSafely((Node?)(object)val2);
				ApplyLayout(state, visualWidth);
				RebuildFocusNeighbors(state);
				SetRelicDetails(screen, relics[0]);
			}
			catch (Exception value)
			{
				BaseLibMain.Logger.Error($"Failed to build the character select starting relic row for {character.Id}: {value}");
				Clear(screen, restoreControllerFocus: true);
				foreach (NRelicBasicHolder item4 in list)
				{
					if (IsValid((GodotObject?)(object)item4) && ((Node)item4).GetParent() == null)
					{
						((Node)(object)item4).QueueFreeSafely();
					}
				}
			}
		}

		internal static void Clear(NCharacterSelectScreen screen, bool restoreControllerFocus)
		{
			//IL_00f0: Unknown result type (might be due to invalid IL or missing references)
			//IL_0199: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a3: Expected O, but got Unknown
			StartingRelicRowState startingRelicRowState = ScreenStates.Get(screen);
			if (startingRelicRowState == null)
			{
				return;
			}
			Viewport viewport = ((Node)screen).GetViewport();
			Control focusOwner = ((viewport != null) ? viewport.GuiGetFocusOwner() : null);
			bool flag = focusOwner != null && startingRelicRowState.Holders.Any((NRelicBasicHolder holder) => (object)holder == focusOwner);
			if (startingRelicRowState.LayoutModified)
			{
				if (IsValid((GodotObject?)(object)startingRelicRowState.TitleContainer))
				{
					startingRelicRowState.TitleContainer.OffsetLeft = startingRelicRowState.OriginalTitleOffsetLeft;
				}
				if (IsValid((GodotObject?)(object)startingRelicRowState.Description))
				{
					startingRelicRowState.Description.OffsetLeft = startingRelicRowState.OriginalDescriptionOffsetLeft;
				}
				if (IsValid((GodotObject?)(object)startingRelicRowState.LegacyIcon))
				{
					((CanvasItem)startingRelicRowState.LegacyIcon).Visible = startingRelicRowState.LegacyIconWasVisible;
				}
				startingRelicRowState.LayoutModified = false;
			}
			if (IsValid((GodotObject?)(object)startingRelicRowState.FocusOrigin))
			{
				startingRelicRowState.FocusOrigin.FocusNeighborTop = startingRelicRowState.OriginalFocusNeighborTop;
				if (restoreControllerFocus && flag && ((CanvasItem)startingRelicRowState.FocusOrigin).IsVisibleInTree() && (int)startingRelicRowState.FocusOrigin.FocusMode != 0)
				{
					startingRelicRowState.FocusOrigin.GrabFocus();
				}
			}
			foreach (NRelicBasicHolder holder in startingRelicRowState.Holders)
			{
				if (IsValid((GodotObject?)(object)holder))
				{
					holder.Disable();
					NHoverTipSet.Remove((Control)(object)holder);
				}
			}
			if (IsValid((GodotObject?)(object)startingRelicRowState.Row))
			{
				((Node)startingRelicRowState.Row).GetParent()?.RemoveChildSafely((Node?)(object)startingRelicRowState.Row);
				((Node)(object)startingRelicRowState.Row).QueueFreeSafely();
			}
			startingRelicRowState.Row = null;
			startingRelicRowState.Holders.Clear();
			startingRelicRowState.FocusOrigin = null;
			startingRelicRowState.OriginalFocusNeighborTop = new NodePath();
		}

		internal static void RebindFocusNeighbors(NCharacterSelectScreen screen)
		{
			StartingRelicRowState startingRelicRowState = ScreenStates.Get(screen);
			if (startingRelicRowState != null && startingRelicRowState.Holders.Count != 0)
			{
				RebuildFocusNeighbors(startingRelicRowState);
			}
		}

		private static void SetRelicDetails(NCharacterSelectScreen screen, RelicModel relic)
		{
			screen._relicTitle.Text = relic.Title.GetFormattedText();
			screen._relicDescription.Text = relic.DynamicDescription.GetFormattedText();
		}

		internal static void SetInteractionEnabled(NCharacterSelectScreen screen, bool enabled)
		{
			StartingRelicRowState startingRelicRowState = ScreenStates.Get(screen);
			if (startingRelicRowState == null)
			{
				return;
			}
			if (!enabled && !IsValid((GodotObject?)(object)startingRelicRowState.FocusOrigin))
			{
				Clear(screen, restoreControllerFocus: false);
				return;
			}
			if (!enabled)
			{
				Viewport viewport = ((Node)screen).GetViewport();
				Control focusOwner = ((viewport != null) ? viewport.GuiGetFocusOwner() : null);
				if (focusOwner != null && startingRelicRowState.Holders.Any((NRelicBasicHolder holder) => (object)holder == focusOwner) && IsValid((GodotObject?)(object)startingRelicRowState.FocusOrigin))
				{
					startingRelicRowState.FocusOrigin.GrabFocus();
				}
			}
			foreach (NRelicBasicHolder holder in startingRelicRowState.Holders)
			{
				if (IsValid((GodotObject?)(object)holder))
				{
					((Control)holder).MouseDefaultCursorShape = (CursorShape)(enabled ? 16 : 0);
					holder.SetEnabled(enabled);
				}
			}
		}

		private static void CaptureOriginalLayout(NCharacterSelectScreen screen, StartingRelicRowState state, Control titleContainer)
		{
			state.TitleContainer = titleContainer;
			state.Description = (Control?)(object)screen._relicDescription;
			state.LegacyIcon = (Control?)(object)screen._relicIcon;
			if (!state.OriginalsCaptured)
			{
				state.OriginalTitleOffsetLeft = titleContainer.OffsetLeft;
				state.OriginalDescriptionOffsetLeft = ((Control)screen._relicDescription).OffsetLeft;
				state.LegacyIconWasVisible = ((CanvasItem)screen._relicIcon).Visible;
				state.OriginalsCaptured = true;
			}
		}

		private static void ApplyLayout(StartingRelicRowState state, float visualWidth)
		{
			float num = Math.Max(state.OriginalTitleOffsetLeft, visualWidth + 8f);
			state.TitleContainer.OffsetLeft = num;
			state.Description.OffsetLeft = Math.Max(state.OriginalDescriptionOffsetLeft, num);
			((CanvasItem)state.LegacyIcon).Visible = false;
			state.LayoutModified = true;
		}

		private static void RebuildFocusNeighbors(StartingRelicRowState state)
		{
			if (state.Holders.Count != 0)
			{
				for (int i = 0; i < state.Holders.Count; i++)
				{
					NRelicBasicHolder nRelicBasicHolder = state.Holders[i];
					((Control)nRelicBasicHolder).FocusNeighborLeft = ((Node)state.Holders[(i - 1 + state.Holders.Count) % state.Holders.Count]).GetPath();
					((Control)nRelicBasicHolder).FocusNeighborRight = ((Node)state.Holders[(i + 1) % state.Holders.Count]).GetPath();
					((Control)nRelicBasicHolder).FocusNeighborTop = ((Node)nRelicBasicHolder).GetPath();
					((Control)nRelicBasicHolder).FocusNeighborBottom = (IsValid((GodotObject?)(object)state.FocusOrigin) ? ((Node)state.FocusOrigin).GetPath() : ((Node)nRelicBasicHolder).GetPath());
				}
				if (IsValid((GodotObject?)(object)state.FocusOrigin))
				{
					state.FocusOrigin.FocusNeighborTop = ((Node)state.Holders[0]).GetPath();
				}
			}
		}

		private static bool IsValid(GodotObject? instance)
		{
			if (instance != null)
			{
				return GodotObject.IsInstanceValid(instance);
			}
			return false;
		}
	}
	[HarmonyPatch]
	internal static class CustomAnimationPatch
	{
		[HarmonyPatch(typeof(NCreature), "StartDeathAnim")]
		[HarmonyPostfix]
		private static void AdjustTime(NCreature __instance, ref float __result)
		{
			if (__instance.Entity.Player?.Character is CustomCharacterModel customCharacterModel && CustomAnimation.HasCustomAnimation((Node)(object)__instance))
			{
				__result = Math.Min(customCharacterModel.DeathAnimTime, 5f);
			}
		}

		[HarmonyPatch(typeof(NCreature), "AnimDie", MethodType.Async)]
		[HarmonyTranspiler]
		private static IEnumerable<CodeInstruction> CustomAnimDie(ILGenerator generator, IEnumerable<CodeInstruction> instructions, MethodBase original)
		{
			return AsyncMethodCall.Create(generator, instructions, original, AccessTools.Method(typeof(CustomAnimationPatch), "WaitCustomAnim"), original);
		}

		private static async Task WaitCustomAnim(NCreature __instance, CancellationToken cancelToken)
		{
			if (CustomAnimation.PlayCustomAnimation((Node)(object)__instance, "Dead", "Die", "die") && __instance.Entity.Player?.Character is CustomCharacterModel customCharacterModel)
			{
				await Cmd.Wait(Math.Min(customCharacterModel.DeathAnimTime, 5f), cancelToken, ignoreCombatEnd: true);
			}
		}

		[HarmonyPatch(typeof(NCreature), "AnimTempRevive")]
		[HarmonyPrefix]
		private static bool UseCustomReviveAnim(NCreature __instance)
		{
			if (__instance.HasSpineAnimation)
			{
				return true;
			}
			return !CustomAnimation.PlayCustomAnimation((Node)(object)__instance, "revive", "Revive");
		}

		[HarmonyPatch(typeof(NCreature), "SetAnimationTrigger")]
		[HarmonyPrefix]
		private static bool SendTriggerToOtherAnimators(NCreature __instance, string trigger)
		{
			if (__instance.HasSpineAnimation)
			{
				return true;
			}
			BaseLibMain.Logger.Debug("SetAnimationTrigger called for " + trigger + " on creature without spine animation");
			string[] array = ((trigger == "Hit") ? new string[4]
			{
				trigger,
				"Hurt",
				trigger.ToLowerInvariant(),
				"hurt"
			} : ((!(trigger == "Dead")) ? new string[2]
			{
				trigger,
				trigger.ToLowerInvariant()
			} : new string[4]
			{
				trigger,
				"Die",
				trigger.ToLowerInvariant(),
				"die"
			}));
			string[] tryAnimNames = array;
			return !CustomAnimation.PlayCustomAnimation((Node)(object)__instance, tryAnimNames);
		}
	}
	[HarmonyPatch]
	internal static class CustomCharacterSelectEntryPatch
	{
		private sealed class CustomCharacterSelectScreenState
		{
			public bool Initialized { get; set; }

			public List<NCustomCharacterSelectEntryButton> Buttons { get; } = new List<NCustomCharacterSelectEntryButton>();

			public NCustomCharacterSelectEntryButton? ActiveButton { get; set; }

			public Control? ActiveScene { get; set; }

			public Control? ActiveForegroundScene { get; set; }

			public Control? ForegroundContainer { get; set; }

			public CustomCharacterSelectContext? Context { get; set; }
		}

		private static readonly SpireField<NCharacterSelectScreen, CustomCharacterSelectScreenState> ScreenStates = new SpireField<NCharacterSelectScreen, CustomCharacterSelectScreenState>(() => new CustomCharacterSelectScreenState());

		[HarmonyPatch(typeof(NCharacterSelectScreen), "InitCharacterButtons")]
		[HarmonyPostfix]
		private static void AddCustomEntryButtons(NCharacterSelectScreen __instance)
		{
			if (CustomCharacterSelectEntryRegistry.Entries.Count == 0)
			{
				return;
			}
			CustomCharacterSelectScreenState customCharacterSelectScreenState = ScreenStates.Get(__instance);
			if (customCharacterSelectScreenState.Initialized)
			{
				return;
			}
			customCharacterSelectScreenState.Initialized = true;
			NCharacterSelectButton randomCharacterButton = __instance._randomCharacterButton;
			if ((object)((randomCharacterButton != null) ? ((Node)randomCharacterButton).GetParent() : null) == __instance._charButtonContainer)
			{
				((Node)(object)__instance._charButtonContainer).RemoveChildSafely((Node?)(object)randomCharacterButton);
			}
			foreach (CustomCharacterSelectEntry entry in CustomCharacterSelectEntryRegistry.Entries)
			{
				if (entry.VisibleInCharacterSelect)
				{
					NCustomCharacterSelectEntryButton nCustomCharacterSelectEntryButton = new NCustomCharacterSelectEntryButton(entry, __instance, delegate(NCustomCharacterSelectEntryButton selected)
					{
						SelectCustomEntry(__instance, selected);
					});
					((Node)(object)__instance._charButtonContainer).AddChildSafely((Node?)(object)nCustomCharacterSelectEntryButton.Button);
					customCharacterSelectScreenState.Buttons.Add(nCustomCharacterSelectEntryButton);
				}
			}
			if (randomCharacterButton != null)
			{
				((Node)(object)__instance._charButtonContainer).AddChildSafely((Node?)(object)randomCharacterButton);
			}
			EnsureForegroundContainer(__instance, customCharacterSelectScreenState);
			RebuildFocusNeighbors(__instance);
