	[HarmonyPatch]
	internal class CustomResourceUiPatches
	{
		[HarmonyPatch(typeof(NCard), "UpdateEnergyCostVisuals")]
		[HarmonyPostfix]
		private static void UpdateCustomCostVisuals(NCard __instance, PileType pileType)
		{
			CardModel model = __instance.Model;
			if (model == null)
			{
				return;
			}
			foreach (ResourceHandler registeredResource in CustomResourcePatches.RegisteredResources)
			{
				registeredResource.GetCost(model)?.UpdateCostVisuals(__instance, pileType);
			}
		}

		[HarmonyPatch(typeof(NCombatUi), "Activate")]
		[HarmonyTranspiler]
		private static List<CodeInstruction> AddUIElement(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new CallMatcher(typeof(GodotTreeExtensions).Method("AddChildSafely"))).Insert(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[3]
			{
				CodeInstruction.LoadArgument(0),
