				CodeInstruction.Call(typeof(CustomResourceUiPatches), "AddUIElementInsert")
			}));
		}

		private static void AddUIElementInsert(NCombatUi __instance, CombatState combatState)
		{
			PlayerCombatState playerCombatState = LocalContext.GetMe(combatState)?.PlayerCombatState;
			if (playerCombatState == null)
			{
				BaseLibMain.Logger.Warn("Failed to initialize custom resource UI; local player combat state null");
				return;
			}
			foreach (ResourceHandler registeredResource in CustomResourcePatches.RegisteredResources)
			{
				registeredResource.VisualsHandler?.AddDisplay(__instance, playerCombatState);
			}
		}
	}
