				return character;
			}
			AbstractModel byIdOrNull = ModelDb.GetByIdOrNull<AbstractModel>(customCharacterModel.DefaultCompendiumOpenModelId);
			if (byIdOrNull is CharacterModel characterModel)
			{
				if (__instance._cardPoolFilters.ContainsKey(characterModel))
				{
					return characterModel;
				}
				BaseLibMain.Logger.Info("Character not visible in compendium; defaulting to null");
			}
			else if (!(byIdOrNull is CharacterModel))
			{
				BaseLibMain.Logger.Warn($"Default compendium model ID {customCharacterModel.DefaultCompendiumOpenModelId} for character {customCharacterModel.Id} is a non-character ID.");
			}
			return null;
		}
	}
