			((Node)list[1]).UniqueNameInOwner = false;
			((Node)list[1]).Name = StringName.op_Implicit("Mod_" + tag + "_Names");
			list[1].Text = string.Join("\n", list3);
			((Node)vbox).AddChild((Node)(object)val, false, (InternalMode)0);
			((Node)vbox).MoveChild((Node)(object)val, at++);
		}

		private static void BuildMulti(VBoxContainer vbox, ref int at, string? body, HBoxContainer tpl, string tag)
		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Expected O, but got Unknown
			HBoxContainer val = (HBoxContainer)((Node)tpl).Duplicate(15);
			((Node)val).UniqueNameInOwner = false;
			((Node)val).Name = StringName.op_Implicit("Mod_" + tag + "_C");
			List<MegaRichTextLabel> list = new List<MegaRichTextLabel>();
			foreach (Node child in ((Node)val).GetChildren(false))
			{
				if (child is MegaRichTextLabel item)
				{
					list.Add(item);
				}
			}
			if (list.Count == 0)
			{
				((Node)val).QueueFree();
				return;
			}
			string[] array = (body ?? "").Split('\n');
			List<string>[] array2 = new List<string>[list.Count];
			for (int i = 0; i < list.Count; i++)
			{
				array2[i] = new List<string>();
			}
			for (int j = 0; j < array.Length; j++)
			{
				array2[j % list.Count].Add(array[j]);
			}
			for (int k = 0; k < list.Count; k++)
			{
				((Node)list[k]).UniqueNameInOwner = false;
				((Node)list[k]).Name = StringName.op_Implicit("Mod_" + tag + "_C" + k);
				list[k].Text = string.Join("\n", array2[k]);
			}
			((Node)vbox).AddChild((Node)(object)val, false, (InternalMode)0);
			((Node)vbox).MoveChild((Node)(object)val, at++);
		}
	}
