	[HarmonyPatch]
	internal static class AdjustCustomMessageKeys
	{
		private static MethodBase? _target;

		private static bool Prepare()
		{
			if ((object)_target == null)
			{
				_target = (MethodBase?)(((object)AccessTools.DeclaredMethod(typeof(MessageTypes), "Initialize")) ?? ((object)typeof(MessageTypes).TypeInitializer));
			}
			if ((object)_target == null)
			{
				BaseLibMain.Logger.Warn("MessageTypes.Initialize (and its static constructor) could not be found; custom network message wrappers will not be registered for this game version.");
			}
			return (object)_target != null;
		}

		private static MethodBase TargetMethod()
		{
			return _target;
		}

		[HarmonyPostfix]
		private static void Fuckery()
		{
			BaseLibMain.Logger.Info("Adjusting keys of custom message wrappers.");
			NetTypeCache<INetMessage> cache = MessageTypes._cache;
			cache._idToType.Remove(typeof(CustomMessageWrapper));
			cache._idToType.Remove(typeof(CustomTargetedMessageWrapper));
			for (int i = 0; i < cache._idToType.Count; i++)
			{
				Type key = cache._idToType[i];
				cache._typeToId[key] = i;
			}
			byte b = 128;
			Type type;
			while (b < byte.MaxValue && cache.TryGetTypeFromId(b, out type))
			{
				b++;
			}
			CustomMessageWrapper.WrapperMessageId = b;
			cache._typeToId[typeof(CustomMessageWrapper)] = b;
			b++;
			while (b < byte.MaxValue && cache.TryGetTypeFromId(b, out type))
			{
				b++;
			}
			CustomTargetedMessageWrapper.WrapperMessageId = b;
			cache._typeToId[typeof(CustomTargetedMessageWrapper)] = b;
			BaseLibMain.Logger.Info($"Using IDs {CustomMessageWrapper.WrapperMessageId} and {CustomTargetedMessageWrapper.WrapperMessageId} for custom message wrappers.");
		}
	}
	[HarmonyPatch(typeof(MessageTypes), "TryGetMessageType")]
	internal static class GetCustomTypes
	{
		[HarmonyPrefix]
		private static bool CustomWrapperTypes(int id, ref Type? type, ref bool __result)
		{
			if (id == CustomMessageWrapper.WrapperMessageId)
			{
				type = typeof(CustomMessageWrapper);
				__result = true;
				return false;
			}
			if (id == CustomTargetedMessageWrapper.WrapperMessageId)
			{
				type = typeof(CustomTargetedMessageWrapper);
				__result = true;
				return false;
			}
			return true;
		}
	}
