			{
				return;
			}
			string[] array = StringExtensions.SimplifyPath(path).Split('/');
			int i;
			for (i = 0; i < array.Length && !(array[i] == "localization"); i++)
			{
			}
			if (i >= array.Length || i == 0)
			{
				return;
			}
