	[HarmonyPatch(typeof(Hook), "AfterCardPlayed", MethodType.Async)]
	internal class AfterCardPlayedPatch
	{
		[HarmonyTranspiler]
		private static IEnumerable<CodeInstruction> AfterPlay(ILGenerator generator, IEnumerable<CodeInstruction> instructions, MethodBase original)
		{
			return AsyncMethodCall.Create(generator, instructions, original, AccessTools.Method(typeof(AfterCardPlayedPatch), "BeforeAfterPlayHooks"), original);
		}

		private static async Task BeforeAfterPlayHooks(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (!PostModInitPatch.CanModifyGameplay)
			{
				return;
			}
			foreach (CardModifier item in CardModifier.Modifiers(cardPlay.Card))
			{
				await item.OnPlay(choiceContext, cardPlay);
			}
			DynamicVar value;
			int num = (cardPlay.Card.DynamicVars.TryGetValue("Refund", out value) ? value.IntValue : 0);
			if (num > 0 && cardPlay.Resources.EnergySpent > 0)
			{
				await PlayerCmd.GainEnergy(Math.Min(num, cardPlay.Resources.EnergySpent), cardPlay.Card.Owner);
			}
			if (PurgePatch.ShouldPurge(cardPlay.Card))
			{
				CardModel deckVersion = cardPlay.Card.DeckVersion;
				if (deckVersion != null && deckVersion.Pile?.Type == PileType.Deck)
				{
					await CardPileCmd.RemoveFromDeck(deckVersion, showPreview: false);
				}
			}
		}
	}
	public static class MaxHandSizePatch
	{
		private static MethodInfo? MaxCardsInHandProperty = AccessTools.PropertyGetter(typeof(CardPile), "MaxCardsInHand");

		public const int DefaultMaxHandSize = 10;

		internal static readonly MethodInfo GetMaxHandSizeFromBaseMethod = AccessTools.Method(typeof(MaxHandSizePatch), "GetMaxHandSize", new Type[2]
		{
			typeof(Player),
			typeof(int)
		});

		internal static bool IsDefaultMaxHandSizeConst(CodeInstruction ins)
		{
			if (!(ins.opcode == OpCodes.Ldc_I4_S) || !(ins.operand is sbyte b) || b != 10)
			{
				if (ins.opcode == OpCodes.Ldc_I4 && ins.operand is int num)
				{
					return num == 10;
				}
				return false;
			}
			return true;
		}

		internal static bool IsBetaMaxHandSize(CodeInstruction ins)
		{
			if (MaxCardsInHandProperty != null)
			{
				return ins.Calls(MaxCardsInHandProperty);
			}
			return false;
		}

		[Obsolete("Prefer to use GetMaxHandSize(player, CardPile.MaxCardsInHand) instead")]
		public static int GetMaxHandSize(Player player)
		{
			return GetMaxHandSize(player, 10);
		}

		public static int GetMaxHandSize(Player player, int baseLimit)
		{
			IRunState obj = player.RunState ?? NullRunState.Instance;
			ICombatState combatState = player.Creature.CombatState;
			int num = baseLimit;
			List<IMaxHandSizeModifier> list = new List<IMaxHandSizeModifier>();
			foreach (AbstractModel item in obj.IterateHookListeners(combatState))
			{
				if (item is IMaxHandSizeModifier maxHandSizeModifier)
				{
					list.Add(maxHandSizeModifier);
					num = maxHandSizeModifier.ModifyMaxHandSize(player, num);
				}
			}
			foreach (IMaxHandSizeModifier item2 in list)
			{
				num = item2.ModifyMaxHandSizeLate(player, num);
			}
			return Math.Max(0, num);
		}

		internal static int GetMaxHandSizeFromCard(CardModel? card, int baseAmount)
		{
			Player player = card?.Owner;
			if (player == null)
			{
				return 10;
			}
			return GetMaxHandSize(player, baseAmount);
		}
	}
