		private static decimal AdjustBaseUnenchanted(bool runGlobalHooks, decimal num, DynamicVar dynVar, CardModel? card)
		{
			if (card == null || card.Enchantment != null)
			{
				return num;
			}
			decimal damage = ((dynVar is CalculatedVar) ? dynVar.BaseValue : num);
			ValueProp props = ValuePropForVar(dynVar);
			damage = ModifyBaseDamageAdditiveInternal(damage, props, card);
			damage = ModifyBaseDamageMultiplicativeInternal(damage, props, card);
			if (!card.IsEnchantmentPreview)
			{
				dynVar.EnchantedValue = damage;
			}
			decimal num2 = damage;
			if (dynVar is CalculatedVar)
			{
				num2 = num;
				num2 = ModifyBaseDamageAdditiveInternal(num2, props, card);
				num2 = ModifyBaseDamageMultiplicativeInternal(num2, props, card);
			}
			if (card.IsEnchantmentPreview)
			{
				dynVar.PreviewValue = num2;
			}
			if (!runGlobalHooks)
			{
				return num2;
			}
			return num;
		}

		private static decimal AdjustExtraUnenchanted(decimal num, DynamicVar dynVar, ValueProp props, CardModel? card)
		{
			if (card == null || card.Enchantment != null)
			{
				return num;
			}
			decimal num2 = ModifyBaseDamageMultiplicativeInternal(num, props, card);
			if (!card.IsEnchantmentPreview)
			{
				dynVar.EnchantedValue = num2;
			}
			else
			{
				dynVar.PreviewValue = num2;
			}
			return num2;
		}

		public static decimal ModifyBaseDamageAdditive(decimal damage, ValueProp props, CardModel? cardSource, ModifyDamageHookType modifyDamageHookType)
		{
			if (!modifyDamageHookType.HasFlag(ModifyDamageHookType.Additive))
			{
				return damage;
			}
			return ModifyBaseDamageAdditiveInternal(damage, props, cardSource);
		}

		private static decimal ModifyBaseDamageAdditiveInternal(decimal damage, ValueProp props, CardModel? cardSource)
		{
			if (cardSource != null)
			{
				foreach (CardModifier modifier in cardSource.GetModifiers())
				{
					damage += modifier.ModifyBaseDamageAdditive(damage, props);
				}
			}
			return damage;
		}

		public static decimal ModifyBaseDamageMultiplicative(decimal damage, ValueProp props, CardModel? cardSource, ModifyDamageHookType modifyDamageHookType)
		{
			if (!modifyDamageHookType.HasFlag(ModifyDamageHookType.Multiplicative))
			{
				return damage;
			}
			return ModifyBaseDamageMultiplicativeInternal(damage, props, cardSource);
		}

		private static decimal ModifyBaseDamageMultiplicativeInternal(decimal damage, ValueProp props, CardModel? cardSource)
		{
			if (cardSource != null)
			{
				foreach (CardModifier modifier in cardSource.GetModifiers())
				{
					damage *= modifier.ModifyBaseDamageMultiplicative(damage, props);
				}
			}
			return damage;
		}

		private static ValueProp ValuePropForVar(DynamicVar dynVar)
		{
			if (!(dynVar is DamageVar { Props: var props }))
			{
				if (!(dynVar is OstyDamageVar { Props: var props2 }))
				{
					if (!(dynVar is CalculatedDamageVar { Props: var props3 }))
					{
						return ValueProp.Move;
					}
					return props3;
				}
				return props2;
			}
			return props;
		}

		private static CardModel? CardOwnerForVar(DynamicVar dynVar)
		{
			AbstractModel owner = dynVar._owner;
			if (!(owner is CardModel result))
			{
				if (!(owner is EnchantmentModel enchantmentModel))
				{
					if (owner is CardModifier cardModifier)
					{
						return cardModifier.Owner;
					}
					return null;
				}
				return enchantmentModel._card;
			}
			return result;
		}
	}
	[HarmonyPatch(typeof(CreatureCmd), "Heal", MethodType.Async)]
	public static class ModifyHealAmountPatches
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> Patch(IEnumerable<CodeInstruction> code)
		{
			List<CodeInstruction> match;
			object operand;
			return new InstructionPatcher(code).Match(new InstructionMatcher().ldarg_0().ldfld().ldfld()
				.PredicateMatch((object? op) => op is FieldInfo fieldInfo && fieldInfo.Name.Contains("creature"))).CopyMatch(out match).Match(new InstructionMatcher().ldfld().PredicateMatch((object? op) => op is FieldInfo fieldInfo && fieldInfo.Name.Equals("amount")))
				.Step(-1)
				.GetOperand(out operand)
				.Insert(CodeInstruction.LoadArgument(0))
				.Step()
				.Insert(match)
				.Insert(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[4]
				{
					CodeInstruction.Call(typeof(ModifyHealAmountPatches), "ModifyHeal"),
					new CodeInstruction(OpCodes.Stfld, operand),
					CodeInstruction.LoadArgument(0),
					new CodeInstruction(OpCodes.Ldfld, operand)
				}));
		}

		public static decimal ModifyHeal(decimal amount, Creature creature)
		{
			object obj = BetaMainCompatibility.Creature_.CombatState.Get(creature);
			object obj2 = creature.Player?.RunState;
			if (obj2 == null)
			{
				if (obj != null)
				{
					obj2 = new CombatStateWrapper(obj).RunState;
				}
				else
				{
					IRunState instance = NullRunState.Instance;
					obj2 = instance;
				}
			}
			ModifyAdditive((IRunState)obj2, obj, creature, ref amount);
			ModifyMultiplicative((IRunState)obj2, obj, creature, ref amount);
			return amount;
		}

		private static void ModifyAdditive(IRunState runState, object? combatState, Creature creature, ref decimal amount)
		{
			decimal num = amount;
			foreach (AbstractModel item in BetaMainCompatibility.RunState.IterateHookListeners.Invoke<IEnumerable<AbstractModel>>(runState, new object[1] { combatState }) ?? Array.Empty<AbstractModel>())
			{
				if (item is IHealAmountModifier healAmountModifier)
				{
					num += healAmountModifier.ModifyHealAdditive(creature, amount);
				}
			}
			amount = num;
		}

		private static void ModifyMultiplicative(IRunState runState, object? combatState, Creature creature, ref decimal __result)
		{
			decimal val = __result;
			foreach (AbstractModel item in BetaMainCompatibility.RunState.IterateHookListeners.Invoke<IEnumerable<AbstractModel>>(runState, new object[1] { combatState }) ?? Array.Empty<AbstractModel>())
			{
				if (item is IHealAmountModifier healAmountModifier)
				{
					val *= healAmountModifier.ModifyHealMultiplicative(creature, __result);
				}
			}
			__result = Math.Max(0m, val);
		}
	}
