	[HarmonyPatch(typeof(NControllerCardPlay), "SingleCreatureTargeting")]
	internal static class NControllerCardPlaySingleTargetingAnyPlayerPatch
	{
		[HarmonyPrefix]
		private static bool ControllerTargeting(NControllerCardPlay __instance, TargetType targetType, ref Task __result)
		{
			if (targetType != TargetType.AnyPlayer)
			{
				return true;
			}
			__result = AnyPlayerControllerTargeting(__instance);
			return false;
		}

		private static async Task AnyPlayerControllerTargeting(NControllerCardPlay instance)
		{
			CardModel card = ((NCardPlay)instance).Card;
			if (card == null)
			{
				instance.CancelPlayCard();
				return;
			}
			ICombatState combatState = card.CombatState ?? card.Owner.Creature.CombatState;
			if (combatState == null)
			{
				instance.CancelPlayCard();
				return;
			}
			NCard cardNode = ((NCardPlay)instance).CardNode;
			if (cardNode == null)
			{
				instance.CancelPlayCard();
				return;
			}
			NTargetManager targetManager = NTargetManager.Instance;
			List<Creature> list = combatState.PlayerCreatures.Where((Creature c) => c != null && c.IsAlive && c.IsPlayer).ToList();
			if (list.Count == 0)
			{
				instance.CancelPlayCard();
				return;
			}
			List<NCreature> list2 = list.Select((Creature c) => NCombatRoom.Instance.GetCreatureNode(c)).OfType<NCreature>().ToList();
			if (list2.Count == 0)
			{
				instance.CancelPlayCard();
				return;
			}
			Callable hoverCallable = Callable.From<NCreature>((Action<NCreature>)delegate(NCreature c)
			{
				((NCardPlay)instance).OnCreatureHover(c);
			});
			Callable unhoverCallable = Callable.From<NCreature>((Action<NCreature>)delegate(NCreature c)
			{
				((NCardPlay)instance).OnCreatureUnhover(c);
			});
			try
			{
				((GodotObject)targetManager).Connect(NTargetManager.SignalName.CreatureHovered, hoverCallable, 0u);
				((GodotObject)targetManager).Connect(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable, 0u);
				targetManager.StartTargeting(TargetType.AnyPlayer, (Control)(object)cardNode, TargetMode.Controller, () => !GodotObject.IsInstanceValid((GodotObject)(object)instance) || !NControllerManager.Instance.IsUsingButtonInputsCompatibility(), null);
				NCombatRoom.Instance.RestrictControllerNavigation(list2.Select((NCreature n) => n.Hitbox));
				list2.First().Hitbox.TryGrabFocus();
				NCreature nCreature = (NCreature)(object)(await targetManager.SelectionFinished());
				if (GodotObject.IsInstanceValid((GodotObject)(object)instance))
				{
					if (nCreature != null)
					{
						((NCardPlay)instance).TryPlayCard(nCreature.Entity);
					}
					else
					{
						instance.CancelPlayCard();
					}
				}
			}
			finally
			{
				if (((GodotObject)targetManager).IsConnected(NTargetManager.SignalName.CreatureHovered, hoverCallable))
				{
					((GodotObject)targetManager).Disconnect(NTargetManager.SignalName.CreatureHovered, hoverCallable);
				}
				if (((GodotObject)targetManager).IsConnected(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable))
				{
					((GodotObject)targetManager).Disconnect(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable);
				}
			}
		}
	}
