	[HarmonyPatch(typeof(SentryService), "Shutdown")]
	internal static class SkipSentryShutdownPatch
	{
		private static readonly SemanticVersion MinVersion = new SemanticVersion(0, 107, 0);

		[HarmonyTranspiler]
		private static List<CodeInstruction> ReplaceShutdown(IEnumerable<CodeInstruction> code)
		{
			if (BetaMainCompatibility.Version.LessThan(MinVersion))
			{
				BaseLibMain.Logger.Info($"Skipping SentryService shutdown patch; version [{BetaMainCompatibility.Version}] less than minimum version [{MinVersion}].");
			}
			InstructionPatcher instructionPatcher = new InstructionPatcher(code);
			InstructionPatcher instructionPatcher2 = instructionPatcher.TryMatch(new CallMatcher(typeof(GodotObject).Method("Call", new Type[2]
			{
				typeof(StringName),
				typeof(Variant[])
			})));
			if (instructionPatcher2 == null)
			{
				BaseLibMain.Logger.Info("Skipping SentryService shutdown patch; no match found.");
				return instructionPatcher;
			}
			return instructionPatcher2.ReplaceLastMatch(new global::<>z__ReadOnlySingleElementList<CodeInstruction>(CodeInstruction.Call(typeof(SkipSentryShutdownPatch), "SkipShutdown")));
		}

		private static Variant SkipShutdown(GodotObject objInstance, StringName methodName, params Variant[] ignoreArgs)
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			BaseLibMain.Logger.Info("Skipping SentryService shutdown.");
			return default(Variant);
		}
	}
