	[HarmonyPatch(typeof(CardCmd), "AutoPlay")]
	internal static class AutoPlayCustomTargetPatch
	{
		[HarmonyPrefix]
		private static void PickRandomCustomTarget(CardModel card, ref Creature? target)
		{
			try
			{
				if (target != null || card == null || !CustomTargetType.SingleTargeting.TryGetValue(card.TargetType, out Func<Creature, Player, bool> canTarget) || canTarget == null)
				{
					return;
				}
				Player player = card.Owner;
				if (player?.RunState?.Rng == null)
				{
					return;
				}
				ICombatState combatState = card.CombatState;
				if (combatState != null)
				{
					List<Creature> list = combatState.Creatures.Where((Creature creature) => creature.IsAlive && canTarget(creature, player)).ToList();
					if (list.Count != 0)
					{
						target = player.RunState.Rng.CombatTargets.NextItem(list);
					}
				}
			}
			catch (Exception value)
			{
				BaseLibMain.Logger.Warn($"AutoPlay custom-target fallback failed; using vanilla behavior. {value}");
			}
		}
	}
	[HarmonyPatch(typeof(AbstractConsoleCmd), "CompleteArgument")]
	public static class BetterConsoleAutocompletePatch
	{
		[HarmonyPrefix]
		public static void UseContainsMatching(ref Func<string, string, bool>? matchPredicate)
		{
			if (matchPredicate == null)
			{
				matchPredicate = (string candidate, string partial) => candidate.Contains(partial, StringComparison.OrdinalIgnoreCase);
			}
		}

		[HarmonyPostfix]
		public static void SortByRelevance(ref CompletionResult __result, string partialArg)
		{
			if (string.IsNullOrWhiteSpace(partialArg))
			{
				return;
			}
			__result.Candidates = __result.Candidates.OrderBy(delegate(string e)
			{
				if (e.StartsWith(partialArg, StringComparison.OrdinalIgnoreCase))
				{
					return 0;
				}
				return (e.Contains('-') ? e.Split('-', 2)[1] : e).StartsWith(partialArg, StringComparison.OrdinalIgnoreCase) ? 1 : 2;
			}).ThenBy((string e) => e).ToList();
		}
	}
	[HarmonyPatch(typeof(NDevConsole), "UpdateGhostText")]
	public static class UpdateGhostTextPatch
	{
		[HarmonyTranspiler]
		public static IEnumerable<CodeInstruction> RemovePushError(IEnumerable<CodeInstruction> instructions)
		{
			MethodInfo method = AccessTools.Method(typeof(GD), "PushError", new Type[1] { typeof(string) });
			List<CodeInstruction> list = instructions.ToList();
			for (int i = 0; i < list.Count; i++)
			{
				if (!list[i].Calls(method))
				{
					continue;
				}
				for (int num = i; num >= 0; num--)
				{
					if (!(list[num].opcode != OpCodes.Brtrue_S) || !(list[num].opcode != OpCodes.Brtrue))
					{
						for (int j = num + 1; j <= i; j++)
						{
							list[j].opcode = OpCodes.Nop;
							list[j].operand = null;
						}
						break;
					}
				}
				break;
			}
			return list;
		}
	}
	public static class CustomTargetType
	{
		[CustomEnum(null)]
		public static TargetType Everyone;

		[CustomEnum(null)]
		public static TargetType Anyone;

		[CustomEnum(null)]
		public static TargetType AllAttackingEnemies;

		[CustomEnum(null)]
		public static TargetType AnyAttackingEnemy;

		[CustomEnum(null)]
		public static TargetType AllBlockingEnemies;

		[CustomEnum(null)]
		public static TargetType AnyBlockingEnemy;

		[CustomEnum(null)]
		public static TargetType AllNonBlockingEnemies;

		[CustomEnum(null)]
		public static TargetType AnyNonBlockingEnemy;

		[CustomEnum(null)]
		public static TargetType AllHighestHpEnemies;

		[CustomEnum(null)]
		public static TargetType AllLowestHpEnemies;

		[CustomEnum(null)]
		public static TargetType AnyFullLifeEnemy;

		[CustomEnum(null)]
		public static TargetType AllFullLifeEnemies;

		[CustomEnum(null)]
		public static TargetType PetOrSelf;

		[CustomEnum(null)]
		public static TargetType Pet;

		internal static readonly Dictionary<TargetType, Func<Creature, Player, bool>> SingleTargeting = new Dictionary<TargetType, Func<Creature, Player, bool>>();

		internal static readonly Dictionary<TargetType, Func<Creature, Player, bool>> MultiTargeting = new Dictionary<TargetType, Func<Creature, Player, bool>>();

		public static bool CanMultiTarget(TargetType targetType, Creature creature, Player player)
		{
			MultiTargeting.TryGetValue(targetType, out Func<Creature, Player, bool> value);
			return value?.Invoke(creature, player) ?? false;
		}

		public static bool IsCustomSingleTargetType(TargetType targetType)
		{
			return SingleTargeting.ContainsKey(targetType);
		}

		public static bool IsCustomMultiTargetType(TargetType targetType)
		{
			return MultiTargeting.ContainsKey(targetType);
		}

		public static void RegisterSingleTargetType(TargetType customType, Func<Creature, bool> canTarget)
		{
			RegisterSingleTargetType(customType, (Creature creature, Player _) => canTarget(creature));
		}

		public static void RegisterSingleTargetType(TargetType customType, Func<Creature, Player, bool> canTarget)
		{
			BaseLibMain.Logger.VeryDebug($"Registered single target type {customType}");
			SingleTargeting.Add(customType, canTarget);
		}

		public static void RegisterMultiTargetType(TargetType customType, Func<Creature, bool>? showReticleFor = null)
		{
			RegisterMultiTargetType(customType, (showReticleFor != null) ? ((Func<Creature, Player, bool>)((Creature creature, Player _) => showReticleFor(creature))) : null);
		}

		public static void RegisterMultiTargetType(TargetType customType, Func<Creature, Player, bool>? showReticleFor = null)
		{
			BaseLibMain.Logger.VeryDebug($"Registered multi target type {customType}");
			MultiTargeting.Add(customType, showReticleFor ?? ((Func<Creature, Player, bool>)((Creature _, Player _) => true)));
		}
	}
	[HarmonyPatch(typeof(ModelDb), "Init")]
	internal static class ModelDbTargetTypeInitPatch
	{
		[HarmonyPostfix]
		private static void RegisterTargetTypes()
		{
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.Anyone, (Creature target) => target != null && target.IsAlive && !target.IsPet);
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.Everyone, (Creature target) => target != null && target.IsAlive && !target.IsPet);
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.AnyAttackingEnemy, delegate(Creature target)
			{
				if (target != null && target.IsAlive && target.IsEnemy)
				{
					MonsterModel monster = target.Monster;
					if (monster != null)
					{
						return monster.IntendsToAttack;
					}
				}
				return false;
			});
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllAttackingEnemies, delegate(Creature target)
			{
				if (target != null && target.IsAlive && target.IsEnemy)
				{
					MonsterModel monster = target.Monster;
					if (monster != null)
					{
						return monster.IntendsToAttack;
					}
				}
				return false;
			});
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.AnyBlockingEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block > 0);
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllBlockingEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block > 0);
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.AnyNonBlockingEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block == 0);
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllNonBlockingEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block == 0);
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllLowestHpEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.CombatState.Enemies.Where((Creature e) => e.IsAlive).Min((Creature e) => e.CurrentHp));
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllHighestHpEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.CombatState.Enemies.Where((Creature e) => e.IsAlive).Max((Creature e) => e.CurrentHp));
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.AnyFullLifeEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.MaxHp);
			CustomTargetType.RegisterMultiTargetType(CustomTargetType.AllFullLifeEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.MaxHp);
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.PetOrSelf, (Creature target, Player player) => (target.IsAlive && target.IsPet && target.PetOwner == player) || target == player.Creature);
			CustomTargetType.RegisterSingleTargetType(CustomTargetType.Pet, (Creature target, Player player) => target.IsAlive && target.IsPet && target.PetOwner == player);
		}
	}
