	[HarmonyPatch(typeof(NControllerCardPlay), "Start")]
	internal class ControllerStartPatch
	{
		[HarmonyPrefix]
		private static bool CustomControllerPlayStart(NControllerCardPlay __instance)
		{
			CardModel card = ((NCardPlay)__instance).Card;
			NCard cardNode = ((NCardPlay)__instance).CardNode;
			if (card == null || cardNode == null || !CustomTargetType.SingleTargeting.ContainsKey(card.TargetType))
			{
				return true;
			}
			NDebugAudioManager.Instance?.Play("card_select.mp3");
			NHoverTipSet.Remove((Control)(object)__instance.Holder);
			if (!card.CanPlay(out UnplayableReason reason, out AbstractModel preventer))
			{
				((NCardPlay)__instance).CannotPlayThisCardFtueCheck(card);
				__instance.CancelPlayCard();
				LocString playerDialogueLine = MegaCrit.Sts2.Core.Entities.Cards.UnplayableReasonExtensions.GetPlayerDialogueLine(reason, preventer);
				if (playerDialogueLine != null)
				{
					((Node)(object)NCombatRoom.Instance?.CombatVfxContainer).AddChildSafely((Node?)(object)NThoughtBubbleVfx.Create(playerDialogueLine.GetFormattedText(), card.Owner.Creature, 1.0));
				}
				return false;
			}
			((NCardPlay)__instance).TryShowEvokingOrbs();
			cardNode.CardHighlight.AnimFlash();
			((NCardPlay)__instance).CenterCard();
			TaskHelper.RunSafely(__instance.SingleCreatureTargeting(card.TargetType));
			return false;
		}
	}
	[HarmonyPatch(typeof(NControllerCardPlay), "SingleCreatureTargeting", new Type[] { typeof(TargetType) })]
	internal class ControllerSingleCreatureTargetingPatch
	{
		[HarmonyPrefix]
		private static bool CustomControllerTargeting(NControllerCardPlay __instance, TargetType targetType, ref Task __result)
		{
			if (!CustomTargetType.SingleTargeting.TryGetValue(targetType, out Func<Creature, Player, bool> value))
			{
				return true;
			}
			__result = FilteredControllerTargeting(__instance, targetType, value);
			return false;
		}

		private static async Task FilteredControllerTargeting(NControllerCardPlay instance, TargetType targetType, Func<Creature, Player, bool> filter)
		{
			CardModel card = ((NCardPlay)instance).Card;
			NCard cardNode = ((NCardPlay)instance).CardNode;
			if (card?.CombatState == null || cardNode == null)
			{
				instance.CancelPlayCard();
				return;
			}
			NCombatRoom instance2 = NCombatRoom.Instance;
			if (instance2 == null)
			{
				instance.CancelPlayCard();
				return;
			}
			List<NCreature> list = instance2.CreatureNodes.Where((NCreature n) => filter(n.Entity, card.Owner)).ToList();
			if (list.Count == 0)
			{
				instance.CancelPlayCard();
				return;
			}
			NTargetManager targetManager = NTargetManager.Instance;
			Callable hoverCallable = Callable.From<NCreature>((Action<NCreature>)delegate(NCreature c)
			{
				((NCardPlay)instance).OnCreatureHover(c);
			});
			Callable unhoverCallable = Callable.From<NCreature>((Action<NCreature>)delegate(NCreature c)
			{
				((NCardPlay)instance).OnCreatureUnhover(c);
			});
			try
			{
				((GodotObject)targetManager).Connect(NTargetManager.SignalName.CreatureHovered, hoverCallable, 0u);
				((GodotObject)targetManager).Connect(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable, 0u);
				targetManager.StartTargeting(targetType, (Control)(object)cardNode, TargetMode.Controller, () => !GodotObject.IsInstanceValid((GodotObject)(object)instance) || !NControllerManager.Instance.IsUsingButtonInputsCompatibility(), null);
				instance2.RestrictControllerNavigation(list.Select((NCreature n) => n.Hitbox));
				list.First().Hitbox.TryGrabFocus();
				NCreature nCreature = (NCreature)(object)(await targetManager.SelectionFinished());
				if (GodotObject.IsInstanceValid((GodotObject)(object)instance))
				{
					if (nCreature != null)
					{
						((NCardPlay)instance).TryPlayCard(nCreature.Entity);
					}
					else
					{
						instance.CancelPlayCard();
					}
				}
			}
			finally
			{
				if (((GodotObject)targetManager).IsConnected(NTargetManager.SignalName.CreatureHovered, hoverCallable))
				{
					((GodotObject)targetManager).Disconnect(NTargetManager.SignalName.CreatureHovered, hoverCallable);
				}
				if (((GodotObject)targetManager).IsConnected(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable))
				{
					((GodotObject)targetManager).Disconnect(NTargetManager.SignalName.CreatureUnhovered, unhoverCallable);
				}
			}
		}
	}
