						}
						if (flag)
						{
							int num = 2;
							List<CodeInstruction> list = new List<CodeInstruction>(num);
							CollectionsMarshal.SetCount(list, num);
							Span<CodeInstruction> span = CollectionsMarshal.AsSpan(list);
							int num2 = 0;
							span[num2] = new CodeInstruction(OpCodes.Ldarg_0);
							num2++;
							span[num2] = new CodeInstruction(OpCodes.Call, propertyInfo.SetMethod);
							QuickTranspiler.Insert = list;
						}
						else
						{
							int num2 = 4;
							List<CodeInstruction> list2 = new List<CodeInstruction>(num2);
							CollectionsMarshal.SetCount(list2, num2);
							Span<CodeInstruction> span2 = CollectionsMarshal.AsSpan(list2);
							int num = 0;
							span2[num] = new CodeInstruction(OpCodes.Ldarg_0);
							num++;
							span2[num] = new CodeInstruction(OpCodes.Ldfld, WrappedValueField);
							num++;
							span2[num] = new CodeInstruction(OpCodes.Ldarg_1);
							num++;
							span2[num] = new CodeInstruction(OpCodes.Call, propertyInfo.SetMethod);
							QuickTranspiler.Insert = list2;
						}
						harmony.Patch(property.SetMethod, null, null, new HarmonyMethod(new Func<IEnumerable<CodeInstruction>, List<CodeInstruction>>(QuickTranspiler.Transpile)));
					}
					if (propertyInfo.GetMethod != null)
					{
						if (property.GetMethod == null)
						{
							throw new Exception($"Property {property} should have a getter to match target property");
						}
						if (flag)
						{
							int num = 2;
							List<CodeInstruction> list3 = new List<CodeInstruction>(num);
							CollectionsMarshal.SetCount(list3, num);
							Span<CodeInstruction> span3 = CollectionsMarshal.AsSpan(list3);
							int num2 = 0;
							span3[num2] = new CodeInstruction(OpCodes.Pop);
							num2++;
							span3[num2] = new CodeInstruction(OpCodes.Call, propertyInfo.GetMethod);
							QuickTranspiler.Insert = list3;
						}
						else
						{
							int num2 = 4;
							List<CodeInstruction> list4 = new List<CodeInstruction>(num2);
							CollectionsMarshal.SetCount(list4, num2);
							Span<CodeInstruction> span4 = CollectionsMarshal.AsSpan(list4);
							int num = 0;
							span4[num] = new CodeInstruction(OpCodes.Pop);
							num++;
							span4[num] = new CodeInstruction(OpCodes.Ldarg_0);
							num++;
							span4[num] = new CodeInstruction(OpCodes.Ldfld, WrappedValueField);
							num++;
							span4[num] = new CodeInstruction(OpCodes.Call, propertyInfo.GetMethod);
							QuickTranspiler.Insert = list4;
						}
						harmony.Patch(property.GetMethod, null, null, new HarmonyMethod(new Func<IEnumerable<CodeInstruction>, List<CodeInstruction>>(QuickTranspiler.Transpile)));
					}
					BaseLibMain.Logger.Info("Generated interop property " + property.Name);
					return true;
				}
				FieldInfo fieldInfo = type.DeclaredField(text2);
				if (fieldInfo != null && fieldInfo.FieldType == property.PropertyType)
				{
					if (property.SetMethod == null)
					{
						throw new Exception($"Interop property {property} should have a setter for field {fieldInfo}");
					}
					if (property.GetMethod == null)
					{
						throw new Exception($"Interop property {property} should have a getter for field {fieldInfo}");
					}
					MethodInfo? setMethod3 = property.SetMethod;
					bool flag3 = ((object)setMethod3 != null && setMethod3.IsStatic) || (property.GetMethod?.IsStatic ?? false);
					if (fieldInfo.IsStatic && !flag3)
					{
						throw new Exception($"Target field {fieldInfo} is static; interop property must also be static");
					}
					if (flag3 && !fieldInfo.IsStatic)
					{
						throw new Exception($"Target field {fieldInfo} is not static; interop property should not be static");
					}
					if (fieldInfo.IsStatic)
					{
						int num = 2;
						List<CodeInstruction> list5 = new List<CodeInstruction>(num);
						CollectionsMarshal.SetCount(list5, num);
						Span<CodeInstruction> span5 = CollectionsMarshal.AsSpan(list5);
						int num2 = 0;
						span5[num2] = new CodeInstruction(OpCodes.Ldarg_0);
						num2++;
						span5[num2] = new CodeInstruction(OpCodes.Stfld, fieldInfo);
						QuickTranspiler.Insert = list5;
					}
					else
					{
						int num2 = 4;
						List<CodeInstruction> list6 = new List<CodeInstruction>(num2);
						CollectionsMarshal.SetCount(list6, num2);
						Span<CodeInstruction> span6 = CollectionsMarshal.AsSpan(list6);
						int num = 0;
						span6[num] = new CodeInstruction(OpCodes.Ldarg_0);
						num++;
						span6[num] = new CodeInstruction(OpCodes.Ldfld, WrappedValueField);
						num++;
						span6[num] = new CodeInstruction(OpCodes.Ldarg_1);
						num++;
						span6[num] = new CodeInstruction(OpCodes.Stfld, fieldInfo);
						QuickTranspiler.Insert = list6;
					}
					harmony.Patch(property.SetMethod, null, null, new HarmonyMethod(new Func<IEnumerable<CodeInstruction>, List<CodeInstruction>>(QuickTranspiler.Transpile)));
					if (fieldInfo.IsStatic)
					{
						int num = 2;
						List<CodeInstruction> list7 = new List<CodeInstruction>(num);
						CollectionsMarshal.SetCount(list7, num);
						Span<CodeInstruction> span7 = CollectionsMarshal.AsSpan(list7);
						int num2 = 0;
						span7[num2] = new CodeInstruction(OpCodes.Pop);
						num2++;
						span7[num2] = new CodeInstruction(OpCodes.Ldfld, fieldInfo);
						QuickTranspiler.Insert = list7;
					}
					else
					{
						int num2 = 4;
						List<CodeInstruction> list8 = new List<CodeInstruction>(num2);
						CollectionsMarshal.SetCount(list8, num2);
						Span<CodeInstruction> span8 = CollectionsMarshal.AsSpan(list8);
						int num = 0;
						span8[num] = new CodeInstruction(OpCodes.Pop);
						num++;
						span8[num] = new CodeInstruction(OpCodes.Ldarg_0);
						num++;
						span8[num] = new CodeInstruction(OpCodes.Ldfld, WrappedValueField);
						num++;
						span8[num] = new CodeInstruction(OpCodes.Ldfld, fieldInfo);
						QuickTranspiler.Insert = list8;
					}
					harmony.Patch(property.GetMethod, null, null, new HarmonyMethod(new Func<IEnumerable<CodeInstruction>, List<CodeInstruction>>(QuickTranspiler.Transpile)));
					BaseLibMain.Logger.Info("Generated interop field property " + property.Name);
					return true;
				}
				throw new Exception("Could not find property or field for name " + text2 + " in type " + text);
			}
			catch (Exception ex)
			{
				BaseLibMain.Logger.Info(ex.ToString());
				return false;
			}
		}

		private static bool CheckParamMatch(ParameterInfo[] targetParams, Type[] checkParams)
		{
			if (targetParams.Length != checkParams.Length)
			{
				return false;
			}
			return !checkParams.Where((Type t, int i) => t != typeof(object) && !t.IsAssignableTo(targetParams[i].ParameterType)).Any();
		}
	}
	[HarmonyPatch(typeof(CardModel))]
	public static class PersistPatch
	{
		private static MethodInfo? TargetMethod = AccessTools.DeclaredMethod(typeof(CardModel), "GetResultPileTypeForCardPlay") ?? AccessTools.DeclaredMethod(typeof(CardModel), "GetResultPileType") ?? AccessTools.DeclaredMethod(typeof(CardModel), "GetResultPileTypeAndPositionForCardPlay") ?? AccessTools.DeclaredMethod(typeof(CardModel), "GetResultLocationForCardPlay");

