			{
				CodeInstruction.LoadArgument(0),
				CodeInstruction.Call(typeof(PersistPatch), "NormalOrPersist")
			}));
		}

		private static PileType NormalOrPersist(PileType dest, CardModel model)
		{
			if (dest == PileType.Discard && model.IsPersist())
			{
