	[HarmonyPatch(typeof(ActModel), "GenerateRooms")]
	internal class AddCustomAncientsToPool
	{
		private static readonly FieldInfo RoomSet = AccessTools.Field(typeof(ActModel), "_rooms");

		[HarmonyPrefix]
		private static void AddToModelPool(ActModel __instance, List<AncientEventModel>? ____sharedAncientSubset)
		{
			if (____sharedAncientSubset == null)
			{
				return;
			}
			____sharedAncientSubset.RemoveAll(((IEnumerable<AncientEventModel>)CustomContentDictionary.CustomAncients).Contains<AncientEventModel>);
			List<CustomAncientModel> list = CustomContentDictionary.CustomAncients.ToList();
			list.Sort((CustomAncientModel a, CustomAncientModel b) => string.Compare(a.Id.Entry, b.Id.Entry, StringComparison.Ordinal));
			list.RemoveAll((CustomAncientModel ancient) => !ancient.IsValidForAct(__instance) || ____sharedAncientSubset.Contains(ancient));
			foreach (ActModel item2 in CurrentGeneratingRunState.State?.Acts ?? Array.Empty<ActModel>())
			{
				if (RoomSet.GetValue(item2) is RoomSet { HasAncient: not false } && item2 != __instance && item2.Ancient is CustomAncientModel item)
				{
					list.Remove(item);
				}
			}
			____sharedAncientSubset.AddRange(list);
		}
	}
