	[HarmonyPatch(typeof(ModelDb), "AllSharedEvents", MethodType.Getter)]
	internal class CustomSharedEvents
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> AddCustomShared(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new InstructionMatcher().dup().stsfld(null)).Step(-2).Insert(CodeInstruction.Call(typeof(CustomSharedEvents), "ConcatCustom"));
		}

		private static IEnumerable<EventModel> ConcatCustom(IEnumerable<EventModel> events)
		{
			List<EventModel> list = new List<EventModel>(events);
			list.AddRange(CustomContentDictionary.SharedCustomEvents);
			return list;
		}
	}
	[HarmonyPatch(typeof(ModelDb), "Acts", MethodType.Getter)]
	internal class ModelDbCustomActsPatch
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> AddCustomActs(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new InstructionMatcher().stsfld(typeof(ModelDb).DeclaredField("_acts"))).InsertBeforeMatch(new global::<>z__ReadOnlySingleElementList<CodeInstruction>(CodeInstruction.Call(typeof(ModelDbCustomActsPatch), "AddCustomActsSorted")));
		}

		private static List<ActModel> AddCustomActsSorted(List<ActModel> original)
		{
			BaseLibMain.Logger.Info($"Adding {CustomContentDictionary.CustomActs.Count} custom acts to act list.");
			original.AddRange(CustomContentDictionary.CustomActs);
			List<ActModel> list = (from act in original
				orderby act.Index, act.IsDefault descending, act.Id
				select act).ToList();
			BaseLibMain.Logger.Info("Result: " + list.AsReadable());
			return list;
		}
	}
	public static class AddActContent
	{
		public static void Patch(Harmony harmony)
		{
			StringBuilder stringBuilder = new StringBuilder("Patching act types for custom encounters and events");
			foreach (Type item in ReflectionHelper.GetSubtypes<ActModel>().Chain(ReflectionHelper.GetSubtypesInMods<ActModel>()))
			{
				bool flag = false;
				MethodInfo methodInfo = AccessTools.DeclaredMethod(item, "GenerateAllEncounters");
				if (methodInfo != null)
				{
					flag = true;
					harmony.Patch(methodInfo, null, AccessTools.Method(typeof(AddActContent), "AddCustomEncounters"));
				}
				methodInfo = AccessTools.DeclaredPropertyGetter(item, "AllEvents");
				if (methodInfo != null)
				{
					flag = true;
					harmony.Patch(methodInfo, null, AccessTools.Method(typeof(AddActContent), "AddCustomEvents"));
				}
				if (flag)
				{
					stringBuilder.Append(" | ").Append(item.Name);
				}
			}
			BaseLibMain.Logger.Info(stringBuilder.ToString());
		}

		private static IEnumerable<EncounterModel> AddCustomEncounters(IEnumerable<EncounterModel> result, ActModel __instance)
		{
			List<EncounterModel> origResult = result.ToList();
			foreach (EncounterModel item in origResult)
			{
				yield return item;
			}
			foreach (CustomEncounterModel encounter in CustomContentDictionary.CustomEncounters)
			{
				if (!origResult.Any((EncounterModel existingEncounter) => existingEncounter.Id.Equals(encounter.Id)) && encounter.IsValidForAct(__instance))
				{
					yield return encounter;
				}
			}
		}

		private static IEnumerable<EventModel> AddCustomEvents(IEnumerable<EventModel> result, ActModel __instance)
		{
			List<EventModel> origResult = result.ToList();
			foreach (EventModel item in origResult)
			{
				yield return item;
			}
			foreach (CustomEventModel eventModel in CustomContentDictionary.ActCustomEvents)
			{
				if (!origResult.Any((EventModel existingEvent) => existingEvent.Id.Equals(eventModel.Id)) && eventModel.Acts.Any((ActModel act) => act.Id.Equals(__instance.Id)))
				{
					yield return eventModel;
				}
			}
		}
	}
	[AttributeUsage(AttributeTargets.Field, Inherited = false, AllowMultiple = false)]
