		public static bool IsPileCustomPileWhereCardShouldBeVisible(CardPile? pile, CardModel card)
		{
			if (pile is CustomPile customPile)
			{
				return customPile.CardShouldBeVisible(card);
			}
			return false;
		}

		public static bool IsPileCustomPileWithCardNotVisible(CardPile? pile, CardModel card)
		{
			if (pile is CustomPile customPile)
			{
				return NCard.FindOnTable(card, customPile.Type) == null;
			}
			return false;
		}

		public static bool CustomPileWithoutCustomTransition(CardPile? pile, CardModel card)
		{
			if (pile is CustomPile customPile && !customPile.CardShouldBeVisible(card))
			{
				return !customPile.NeedsCustomTransitionVisual;
			}
			return false;
		}

		public static bool CustomPileUseGenericTweenForOtherPlayers(CardModel card)
		{
			if (card.Pile is CustomPile customPile)
			{
				if (!customPile.CardShouldBeVisible(card))
				{
					return !customPile.NeedsCustomTransitionVisual;
				}
				return true;
			}
			return false;
		}

		public static bool CustomPileUseCustomTween(CardModel card, NCard cardNode, CardPile? oldPile, Tween tween)
		{
			if (!(card.Pile is CustomPile customPile))
			{
				return false;
			}
			return customPile.CustomTween(tween, card, cardNode, oldPile);
		}

		private static bool CustomPileUseCustomTweenPileType(CardModel card, NCard cardNode, PileType? oldPileType, Tween tween)
		{
			if (!(card.Pile is CustomPile customPile))
			{
				return false;
			}
			CardPile oldPile = oldPileType?.GetPile(card.Owner);
			return customPile.CustomTween(tween, card, cardNode, oldPile);
		}
	}
	[HarmonyPatch(typeof(DustyTome), "SetupForPlayer")]
	internal class DustyTomePatch
	{
		private static bool _initialized = false;

		private static readonly Dictionary<ModelId, List<ModelId>> _customTome = new Dictionary<ModelId, List<ModelId>>();

		private static Dictionary<ModelId, List<ModelId>> CustomTome
		{
			get
			{
				if (_initialized)
				{
					return _customTome;
				}
				_initialized = true;
				int num = 0;
				foreach (CardModel allCard in ModelDb.AllCards)
				{
					if (allCard is ITomeCard tomeCard)
					{
						if (!_customTome.TryGetValue(tomeCard.TomeCharacter.Id, out List<ModelId> value))
						{
							value = new List<ModelId>();
							_customTome[tomeCard.TomeCharacter.Id] = value;
						}
						value.Add(allCard.Id);
						num++;
					}
				}
				BaseLibMain.Logger.Info($"Initialized DustyTome dictionary; found {num} ITomeCard implementations");
				return _customTome;
			}
		}

		[HarmonyPrefix]
		private static bool DustyTomeCardOverride(DustyTome __instance, Player player)
		{
			if (CustomTome.TryGetValue(player.Character.Id, out List<ModelId> value))
			{
				__instance.AncientCard = player.PlayerRng.Rewards.NextItem(value);
				return false;
			}
			return true;
		}
	}
	[HarmonyPatch(typeof(ModelDb), "GetEntry")]
	public class PrefixIdPatch
	{
		private static readonly ConcurrentDictionary<Type, string> IdCache = new ConcurrentDictionary<Type, string>();

		[HarmonyPostfix]
		private static void AdjustID(ref string __result, Type type)
		{
			if (IdCache.TryGetValue(type, out string value))
			{
				__result = value;
				return;
			}
			CustomIDAttribute customAttribute = type.GetCustomAttribute<CustomIDAttribute>();
			if (customAttribute != null)
			{
				IdCache[type] = customAttribute.ID;
				__result = customAttribute.ID;
			}
			else if (type.IsAssignableTo(typeof(ICustomModel)))
			{
				IdCache[type] = type.GetPrefix() + __result;
				__result = IdCache[type];
			}
			else
			{
				IdCache[type] = __result;
			}
		}
	}
	[HarmonyPatch(typeof(RewardSynchronizer))]
	public static class RewardSynchronizerPatches
	{
		extension(RewardSynchronizer rewardSynchronizer)
		{
			public INetGameService GameService()
			{
				return rewardSynchronizer._gameService;
			}

			public void BufferCustomRewardMessage(CustomTargetedMessageWrapper message, ulong senderId)
			{
				BufferedCustomRewardMessage item = new BufferedCustomRewardMessage
				{
					SenderId = senderId,
					Message = message
				};
				BufferedCustomRewardMessages[rewardSynchronizer]?.Add(item);
			}
		}

		public struct BufferedCustomRewardMessage
		{
			public ulong SenderId;

			public CustomTargetedMessageWrapper Message;
		}

		internal static readonly SpireField<RewardSynchronizer, List<BufferedCustomRewardMessage>> BufferedCustomRewardMessages = new SpireField<RewardSynchronizer, List<BufferedCustomRewardMessage>>(() => new List<BufferedCustomRewardMessage>());

		[HarmonyPatch("OnCombatEnded")]
		[HarmonyPrefix]
		private static void OnCombatEndHandleCustomBufferedMessages(RewardSynchronizer __instance)
		{
			foreach (BufferedCustomRewardMessage item in BufferedCustomRewardMessages[__instance])
			{
				__instance._messageBuffer.CallHandlersOfType(item.Message.GetType(), (INetMessage)item.Message, item.SenderId);
			}
			BufferedCustomRewardMessages[__instance]?.Clear();
		}
	}
