	public class UnknownCharacterPatches
	{
		[HarmonyPatch(typeof(SaveManager), "HasRunSave", MethodType.Getter)]
		private static class IgnoreUnknownRun
		{
			[HarmonyPostfix]
			private static void SkipUnknownCharacter(SaveManager __instance, ref bool __result)
			{
				if (!__result)
				{
					return;
				}
				ReadSaveResult<SerializableRun> readSaveResult = __instance.LoadRunSave();
				if (!readSaveResult.Success || readSaveResult.SaveData == null)
				{
					return;
				}
				foreach (SerializablePlayer player in readSaveResult.SaveData.Players)
				{
					if (player.CharacterId == null || ModelDb.GetByIdOrNull<CharacterModel>(player.CharacterId) == null)
					{
						BaseLibMain.Logger.Info($"Ignoring run with unknown character {player.CharacterId}");
						__result = false;
						break;
					}
				}
			}
		}

