	[HarmonyPatch(typeof(SavedProperties))]
	internal static class SavedSpireFieldPatch
	{
		private static readonly List<ISavedSpireField> RegisteredFields = new List<ISavedSpireField>();

		private static Type? _targetType;

		private static bool _beta = false;

		public static void Register<TKey, TVal>(SavedSpireField<TKey, TVal> field) where TKey : class
		{
			RegisteredFields.Add(field);
		}

		private static IEnumerable<ISavedSpireField> GetFieldsForModel(object model)
		{
			return RegisteredFields.Where((ISavedSpireField f) => f.TargetType.IsInstanceOfType(model));
		}

		[HarmonyPatch("FromInternal")]
		[HarmonyPostfix]
		private static void PostfixFromInternal(ref SavedProperties? __result, object model)
		{
			SavedProperties savedProperties = __result ?? new SavedProperties();
			bool flag = false;
			foreach (ISavedSpireField item in GetFieldsForModel(model))
			{
				item.Export(model, savedProperties);
				flag = true;
			}
			if (__result == null && flag)
			{
				__result = savedProperties;
			}
		}

		[HarmonyPatch("FillInternal")]
		[HarmonyPostfix]
		private static void PostfixFillInternal(SavedProperties __instance, object model)
		{
			foreach (ISavedSpireField item in GetFieldsForModel(model))
			{
				item.Import(model, __instance);
			}
		}

		internal static void AddFieldsSorted()
		{
			BaseLibMain.Logger.Info($"Found {RegisteredFields.Count} SavedSpireFields.");
			RegisteredFields.Sort((ISavedSpireField a, ISavedSpireField b) => string.Compare(a.Name, b.Name, StringComparison.Ordinal));
			foreach (ISavedSpireField registeredField in RegisteredFields)
			{
				if (registeredField.IsBasegameSupported)
				{
					InjectNameIntoBaseGameCache(registeredField.Name);
				}
				else if (!registeredField.RegisterCustomSave())
				{
					BaseLibMain.Logger.Error("SavedSpireField " + registeredField.Name + " will not be saved as it is of an unsupported type.");
				}
			}
		}

		private static void InjectNameIntoBaseGameCache(string name)
		{
			if (_targetType == null)
			{
				_targetType = AccessTools.TypeByName("MegaCrit.Sts2.Core.Saves.Runs.SavedPropertiesTypeCache");
				if (_targetType == null)
				{
					_targetType = typeof(ModelIdSerializationCache);
					_beta = true;
				}
			}
			Dictionary<string, int> dictionary = AccessTools.StaticFieldRefAccess<Dictionary<string, int>>(_targetType, "_propertyNameToNetIdMap");
			List<string> list = AccessTools.StaticFieldRefAccess<List<string>>(_targetType, "_netIdToPropertyNameMap");
			MethodInfo methodInfo = AccessTools.PropertySetter(_targetType, _beta ? "PropertyIdBitSize" : "NetIdBitSize");
			if (!dictionary.ContainsKey(name))
			{
				dictionary[name] = list.Count;
				list.Add(name);
				BaseLibMain.Logger.Debug($"Added saved property name to basegame cache: {name} => {dictionary[name]}");
				int num = Mathf.CeilToInt(Math.Log2(list.Count));
				methodInfo.Invoke(null, new object[1] { num });
			}
			else
			{
				BaseLibMain.Logger.Error("SavedSpireField name is not unique: " + name);
			}
		}
	}
	[HarmonyPatch]
	public static class SelfApplyDebuffPatch
	{
		private static MethodBase TargetMethod()
		{
			MethodInfo methodInfo = AccessTools.DeclaredMethod(typeof(PowerCmd), "Apply", new Type[7]
			{
				typeof(PlayerChoiceContext),
				typeof(PowerModel),
				typeof(Creature),
				typeof(decimal),
				typeof(Creature),
				typeof(CardModel),
				typeof(bool)
			});
			if (methodInfo == null)
			{
				methodInfo = AccessTools.DeclaredMethod(typeof(PowerCmd), "Apply", new Type[6]
				{
					typeof(PowerModel),
					typeof(Creature),
					typeof(decimal),
					typeof(Creature),
					typeof(CardModel),
					typeof(bool)
				});
			}
			return methodInfo;
		}

		[HarmonyPostfix]
		private static void Postfix(ref Task __result, PowerModel power, Creature target, Creature? applier, CardModel? cardSource)
		{
			__result = WrappedApplyTask(__result, power, target, applier, cardSource);
		}

		private static async Task WrappedApplyTask(Task originalTask, PowerModel power, Creature target, Creature? applier, CardModel? cardSource)
		{
			await originalTask;
			ICombatState? combatState = target.CombatState;
			if (combatState != null && combatState.CurrentSide == CombatSide.Player && target.Side == CombatSide.Player && power != null && power.Type == PowerType.Debuff)
			{
				Creature applier2 = power.Applier;
				if (applier2 != null && applier2.Side == CombatSide.Player && (power is ICustomModel || power.Applier?.Monster is ICustomModel || power.Applier?.Player?.Character is ICustomModel || cardSource is ICustomModel))
				{
					power.SkipNextDurationTick = false;
				}
			}
		}
	}
	[HarmonyPatch(typeof(CardModel), "UpgradeInternal")]
	internal class UpgradeInternalPatch
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> InsertVarUpgrade(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new CallMatcher(AccessTools.Method(typeof(CardModel), "OnUpgrade"))).Insert(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[2]
			{
				CodeInstruction.LoadArgument(0),
				CodeInstruction.Call(typeof(UpgradeInternalPatch), "UpgradeVars")
			}));
		}

		private static void UpgradeVars(CardModel card)
		{
			foreach (KeyValuePair<string, DynamicVar> dynamicVar in card.DynamicVars)
			{
				decimal? num = DynamicVarExtensions.DynamicVarUpgrades[dynamicVar.Value];
				if (num.HasValue)
				{
					dynamicVar.Value.UpgradeValueBy(num.Value);
				}
			}
			if (card is ConstructedCardModel constructedCardModel)
			{
				constructedCardModel.ConstructedUpgrade();
			}
		}
	}
