namespace BaseLib.Monsters
{
	public class MoveBuilder
	{
		public enum PowerIntent
		{
			None,
			Buff,
			Debuff,
			StrongDebuff
		}

		private class ActionExecutor(List<Func<IReadOnlyList<Creature>, Task>> actions)
		{
			private List<Func<IReadOnlyList<Creature>, Task>> Actions { get; } = actions;

			public static implicit operator Func<IReadOnlyList<Creature>, Task>(ActionExecutor executor)
			{
				return async delegate(IReadOnlyList<Creature> creatures)
				{
					foreach (Func<IReadOnlyList<Creature>, Task> action in executor.Actions)
					{
						await action(creatures);
					}
				};
			}
		}

		public readonly MonsterModel Monster;

		public readonly string Id;

		public readonly List<Func<IReadOnlyList<Creature>, Task>> Actions = new List<Func<IReadOnlyList<Creature>, Task>>();

		public readonly List<AbstractIntent> Intents = new List<AbstractIntent>();

		public string? FollowUpStateId { get; set; }

		private void AddNewIntent<T>() where T : AbstractIntent, new()
		{
			if (!Intents.Any((AbstractIntent intent) => intent is T))
			{
				Intents.Add(new T());
			}
		}

		private void AddDebuffIntent(bool strong)
		{
			int num = Intents.FindIndex(delegate(AbstractIntent intent)
			{
				IntentType intentType = intent.IntentType;
				return (uint)(intentType - 2) <= 1u;
			});
			if (num >= 0)
			{
				if (Intents[num].IntentType != IntentType.DebuffStrong && strong)
				{
					Intents[num] = new DebuffIntent(strong);
				}
			}
			else
			{
				Intents.Add(new DebuffIntent(strong));
			}
		}

		public MoveBuilder(MonsterModel monster, string id)
		{
			Monster = monster;
			Id = id;
		}

		public MoveBuilder Attack(int damage, int hitCount = 1, (string, float, bool)? attackerAnim = null, string? attackerVfx = null, string? attackerSfx = null, string? attackerTmpSfx = null, string? hitVfx = null, string? hitSfx = null, string? hitTmpSfx = null)
		{
			Actions.Add(async delegate
			{
				AttackCommand attackCommand = MonsterActions.Attack(Monster, damage, hitCount).WithAttackerFx(attackerVfx, attackerSfx, attackerTmpSfx).WithHitFx(hitVfx, hitSfx, hitTmpSfx);
				if (attackerAnim.HasValue)
				{
					attackCommand.WithAttackerAnim(attackerAnim.Value.Item1, attackerAnim.Value.Item2);
					if (!attackerAnim.Value.Item3)
					{
						attackCommand.OnlyPlayAnimOnce();
					}
				}
				await attackCommand.Execute(null);
			});
			if (hitCount != 1)
			{
				Intents.Add(new MultiAttackIntent(damage, hitCount));
			}
			else
			{
				Intents.Add(new SingleAttackIntent(damage));
			}
			return this;
		}

		public MoveBuilder Block(int amount, ValueProp props = ValueProp.Move)
		{
			Actions.Add(async delegate
			{
				await CreatureCmd.GainBlock(Monster.Creature, amount, props, null);
			});
			AddNewIntent<DefendIntent>();
			return this;
		}

		public MoveBuilder ApplyToPlayers<T>(int amount, bool isStrongDebuff, bool silent = false) where T : PowerModel
		{
			Actions.Add(async delegate(IReadOnlyList<Creature> creatures)
			{
				await MonsterActions.Apply<T>(Monster, amount, creatures, null, silent);
			});
			AddDebuffIntent(isStrongDebuff);
			return this;
		}

		public MoveBuilder ApplyToSelf<T>(int amount, bool silent = false) where T : PowerModel
		{
			Actions.Add(async delegate
			{
				await MonsterActions.ApplySelf<T>(Monster, amount, null, silent);
			});
			AddNewIntent<BuffIntent>();
			return this;
		}

		public MoveBuilder ApplyToSomeone<T>(int amount, Func<IEnumerable<Creature>> targets, PowerIntent intent = PowerIntent.None, bool silent = false) where T : PowerModel
		{
			Actions.Add(async delegate
			{
				await MonsterActions.Apply<T>(Monster, amount, targets(), null, silent);
			});
			switch (intent)
			{
			case PowerIntent.Buff:
				AddNewIntent<BuffIntent>();
				break;
			case PowerIntent.Debuff:
				AddDebuffIntent(strong: false);
				break;
			case PowerIntent.StrongDebuff:
				AddDebuffIntent(strong: true);
				break;
			}
			return this;
		}

		public MoveBuilder HealSelf(int amount, bool autoScaleWithPlayers = true)
		{
			return HealSelf(() => amount * ((!autoScaleWithPlayers) ? 1 : Monster.Creature.CombatState.Players.Count));
		}

		public MoveBuilder HealSelf(Func<int> amount)
		{
			Actions.Add(async delegate
			{
				await CreatureCmd.Heal(Monster.Creature, amount());
			});
			AddNewIntent<HealIntent>();
			return this;
		}

		public MoveBuilder PlaySfx(string key)
		{
			Actions.Add(delegate
			{
				SfxCmd.Play(key);
				return Task.CompletedTask;
			});
			return this;
		}

		public MoveBuilder PlaySfx(ModSound sound, float volumeAdd = 0f, float volumeMult = 1f, float pitchVariation = 0f, float basePitch = 1f)
		{
			Actions.Add(delegate
			{
				sound.Play(volumeAdd, volumeMult, pitchVariation, basePitch);
				return Task.CompletedTask;
			});
			return this;
		}

		public MoveBuilder PlayAnim(string animKey, float waitTime)
		{
			Actions.Add(async delegate
			{
				await CreatureCmd.TriggerAnim(Monster.Creature, animKey, waitTime);
			});
			return this;
		}

		public MoveBuilder CustomAction(Func<IReadOnlyList<Creature>, Task> action)
		{
			Actions.Add(action);
			return this;
		}

		public MoveBuilder AddIntent(AbstractIntent intent)
		{
			Intents.Add(intent);
			return this;
		}

		public MoveBuilder FollowingState(string stateId)
		{
			FollowUpStateId = stateId;
			return this;
		}

		public MoveState Build()
		{
			return new MoveState(Id, new ActionExecutor(Actions), Intents.ToArray())
			{
				FollowUpStateId = FollowUpStateId
			};
		}

		public static implicit operator MoveState(MoveBuilder builder)
		{
			return builder.Build();
		}
	}
}
namespace BaseLib.Hooks
{
	public static class BaseLibHooks
	{
		public static Task AfterScryed(PlayerChoiceContext ctx, Player player, int scryAmount, int discardedAmount, List<CardModel> seen, List<CardModel> discarded)
		{
			return HookUtils.Dispatch(player.Creature.CombatState, ctx, (IAfterScryed m) => m.AfterScryed(ctx, player, scryAmount, discardedAmount, seen, discarded));
		}

		public static int ModifyScryAmount(Player player, int amount, out IEnumerable<IModifyScryAmount> modifiers)
		{
			return HookUtils.Modify(player.Creature.CombatState, amount, (IModifyScryAmount m, int a) => m.ModifyScryAmount(player, a), out modifiers);
		}

		public static Task AfterModifyingScryAmount(PlayerChoiceContext ctx, Player player, IEnumerable<IModifyScryAmount> modifiers, int originalAmount, int modifiedAmount)
		{
			return HookUtils.AfterModifying(player.Creature.CombatState, modifiers, (IModifyScryAmount a) => a.AfterModifyingScryAmount(ctx, player, originalAmount, modifiedAmount));
		}

		public static async Task AfterSpendCustomResource<T>(ICombatState combatState, T resource, AbstractModel? spender, int amount) where T : CustomResource
		{
			await HookUtils.Dispatch(combatState, (IAfterSpendResource<T> m) => m.AfterSpendResource(combatState, resource, spender, amount));
		}

		public static decimal ModifyResourceCostInCombat<T>(ICombatState combatState, T resource, CardModel card, decimal originalCost) where T : CustomResource
		{
			if (originalCost < 0m)
			{
				return originalCost;
			}
			IEnumerable<IModifyResourceCostInCombat<T>> modifiers;
			return HookUtils.Modify(combatState, originalCost, (IModifyResourceCostInCombat<T> modifier, decimal amt) => modifier.ModifyResourceCostInCombat(card, resource, amt), out modifiers);
		}
	}
	public interface IModifyResourceCostInCombat<T> where T : CustomResource
	{
		decimal ModifyResourceCostInCombat(CardModel card, T resource, decimal originalCost);
	}
	public interface IAfterSpendResource<T> where T : CustomResource
	{
		Task AfterSpendResource(ICombatState combatState, T resource, AbstractModel? spender, int amount);
	}
	public static class HealthBarForecastRegistry
	{
		internal readonly record struct RegisteredHealthBarForecastSegment(HealthBarForecastSegment Segment, long SequenceOrder);

		private readonly record struct ProviderEntry(string ModId, string SourceId, IHealthBarForecastSource? Source, Func<Creature, IEnumerable<object>>? ForeignProvider, long RegistrationOrder);

		private readonly record struct ForeignSegmentAccessors(Func<object, int> ReadAmount, Func<object, Color> ReadColor, Func<object, object?> ReadDirection, Func<object, int> ReadOrder, Func<object, Material?> ReadOverlayMaterial, Func<object, Color?> ReadOverlaySelfModulate, Func<object, object?> ReadLeftOriginLayout, Func<object, int> ReadLeftExclusiveZGroup, Func<object, bool> ReadAffectsHpLabel);

