	public static class AttackCommandExtensions
	{
		public static AttackCommand WithValueProp(this AttackCommand attackCommand, ValueProp valueProp)
		{
			attackCommand.DamageProps = valueProp;
			return attackCommand;
		}

		public static async Task<List<Creature>> ExecuteAndCheckFatal(this AttackCommand attackCommand, PlayerChoiceContext choiceContext)
		{
			List<Creature> fatalKills = new List<Creature>();
			HashSet<Creature> canBeFatal = (from e in attackCommand.GetPossibleTargets()
				where e.Powers.All((PowerModel p) => p.ShouldOwnerDeathTriggerFatal())
				select e).ToHashSet();
			await attackCommand.Execute(choiceContext);
			foreach (DamageResult item in attackCommand.Results.SelectMany((List<DamageResult> r) => r))
			{
				if (item.WasTargetKilled && canBeFatal.Contains(item.Receiver) && !fatalKills.Contains(item.Receiver))
				{
					fatalKills.Add(item.Receiver);
				}
			}
			return fatalKills;
		}
	}
	public static class AudioStreamPlayerExtensions
	{
		private static readonly NodePath VolumeDb = NodePath.op_Implicit("volume_db");

		public static readonly SpireField<AudioStreamPlayer, Tween> CurrentTween = new SpireField<AudioStreamPlayer, Tween>(() => (Tween?)null);

		public static void FadeIn(this AudioStreamPlayer player, float duration)
		{
			//IL_0037: Unknown result type (might be due to invalid IL or missing references)
			Tween? obj = CurrentTween[player];
			if (obj != null)
			{
				obj.Kill();
			}
			float volumeDb = player.VolumeDb;
			player.VolumeDb = -80f;
			Tween val = ((Node)player).CreateTween();
			val.TweenProperty((GodotObject)(object)player, VolumeDb, Variant.op_Implicit(volumeDb), (double)duration).SetTrans((TransitionType)1).SetEase((EaseType)1);
			CurrentTween[player] = val;
		}

		public static void FadeOut(this AudioStreamPlayer player, float duration)
		{
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			Tween? obj = CurrentTween[player];
			if (obj != null)
			{
				obj.Kill();
			}
			Tween obj2 = ((Node)player).CreateTween();
			obj2.TweenProperty((GodotObject)(object)player, VolumeDb, Variant.op_Implicit(-80), (double)duration).SetTrans((TransitionType)1).SetEase((EaseType)0);
			obj2.TweenCallback(Callable.From((Action)delegate
			{
				Node parent = ((Node)player).GetParent();
				if (parent != null)
				{
					parent.RemoveChild((Node)(object)player);
				}
			}));
			CurrentTween[player] = null;
		}
	}
	public static class CardExtensions
	{
		public static List<Creature> GetTargets(this CardModel card)
		{
			switch (card.TargetType)
			{
			case TargetType.AllAllies:
				return card.CombatState?.PlayerCreatures.Where((Creature c) => c?.IsAlive ?? false).ToList() ?? new List<Creature>();
			case TargetType.AllEnemies:
				return card.CombatState?.HittableEnemies.ToList() ?? new List<Creature>();
			case TargetType.RandomEnemy:
			{
				IReadOnlyList<Creature> readOnlyList = card.CombatState?.HittableEnemies;
				if (readOnlyList == null || readOnlyList.Count == 0)
				{
					return new List<Creature>();
				}
				Creature creature = card.Owner.RunState.Rng.CombatTargets.NextItem(readOnlyList);
				if (creature == null)
				{
					return new List<Creature>();
				}
				int num = 1;
				List<Creature> list = new List<Creature>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<Creature> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = creature;
				return list;
			}
			case TargetType.None:
				return new List<Creature>();
			case TargetType.Self:
			{
				int index = 1;
				List<Creature> list2 = new List<Creature>(index);
				CollectionsMarshal.SetCount(list2, index);
				Span<Creature> span2 = CollectionsMarshal.AsSpan(list2);
				int num = 0;
				span2[num] = card.Owner.Creature;
				return list2;
			}
			default:
			{
				if (CustomTargetType.IsCustomMultiTargetType(card.TargetType))
				{
					return card.CombatState?.Creatures.Where((Creature c) => CustomTargetType.CanMultiTarget(card.TargetType, c, card.Owner)).ToList() ?? new List<Creature>();
				}
				string text = CustomEnums.EnumName<TargetType>((int)card.TargetType) ?? ((card.TargetType <= TargetType.Osty) ? card.TargetType.ToString() : ((int)card.TargetType).ToString());
				BaseLibMain.Logger.Error("Target type " + text + " is not supported by GetTargets, either because it requiressingle targeting or is an unknown type of targeting.");
				return new List<Creature>();
			}
			}
		}

