	public static class DynamicVarExtensions
	{
		[HarmonyPatch(typeof(DynamicVar), "Clone")]
		private class CloneTooltips
		{
			[HarmonyPostfix]
			private static DynamicVar Copy(DynamicVar __result, DynamicVar __instance)
			{
				DynamicVarTips[__result] = DynamicVarTips[__instance];
				DynamicVarUpgrades[__result] = DynamicVarUpgrades[__instance];
				return __result;
			}
		}

		public static readonly SpireField<DynamicVar, Func<DynamicVar, IHoverTip>> DynamicVarTips = new SpireField<DynamicVar, Func<DynamicVar, IHoverTip>>(() => (Func<DynamicVar, IHoverTip>?)null);

		public static readonly SpireField<DynamicVar, decimal?> DynamicVarUpgrades = new SpireField<DynamicVar, decimal?>(() => (decimal?)null);

		public static TDynamicVar WithUpgrade<TDynamicVar>(this TDynamicVar dynamicVar, decimal upgradeValue) where TDynamicVar : DynamicVar
		{
			if (upgradeValue != 0m)
			{
				DynamicVarUpgrades[dynamicVar] = upgradeValue;
			}
			return dynamicVar;
		}

		public static decimal CalculateBlock(this DynamicVar var, Creature creature, ValueProp props, CardPlay? cardPlay = null, CardModel? cardSource = null)
		{
			decimal baseValue = var.BaseValue;
			if (!CombatManager.Instance.IsInProgress)
			{
				return baseValue;
			}
			if (CombatManager.Instance.IsEnding)
			{
				return baseValue;
			}
			ICombatState combatState = creature.CombatState;
			if (combatState == null)
			{
				return baseValue;
			}
			EnchantmentModel enchantmentModel = cardSource?.Enchantment;
			if (enchantmentModel != null)
			{
				baseValue += enchantmentModel.EnchantBlockAdditive(baseValue);
				baseValue *= enchantmentModel.EnchantBlockMultiplicative(baseValue);
			}
			baseValue = Hook.ModifyBlock(combatState, creature, baseValue, props, cardSource, cardPlay, out IEnumerable<AbstractModel> _);
			return Math.Max(baseValue, 0m);
		}

		public static TDynamicVar WithTooltip<TDynamicVar>(this TDynamicVar var, string? locKey = null, string locTable = "static_hover_tips") where TDynamicVar : DynamicVar
		{
			string key = locKey ?? (var.GetType().GetPrefix() + StringHelper.Slugify(var.Name));
			DynamicVarTips[var] = delegate(DynamicVar locVar)
			{
				LocString locString = new LocString(locTable, key + ".title");
				LocString locString2 = new LocString(locEntryKey: LocString.Exists(locTable, key + ".smartDescription") ? (key + ".smartDescription") : (key + ".description"), locTable: locTable);
				locString.Add(locVar);
				locString2.Add(locVar);
				return new HoverTip(locString, locString2);
			};
			return var;
		}
	}
	public static class DynamicVarSetExtensions
	{
		extension(DynamicVarSet vars)
		{
			public DynamicVar Power<T>() where T : PowerModel
			{
				return vars[typeof(T).Name];
			}

			public T Var<T>(string? name = null) where T : DynamicVar
			{
				if (name != null)
				{
					if (vars.TryGetValue(name, out DynamicVar value))
					{
						if (value is T result)
						{
							return result;
						}
						throw new ArgumentException($"Found dynamic variable of type {value.GetType().Name} instead of type {typeof(T).Name} with name {name}");
					}
					throw new ArgumentException("Failed to find dynamic variable of type " + typeof(T).Name + " with name " + name);
				}
				return vars.Select<KeyValuePair<string, DynamicVar>, DynamicVar>((KeyValuePair<string, DynamicVar> entry) => entry.Value).OfType<T>().FirstOrDefault() ?? throw new ArgumentException("No dynamic variables of type " + typeof(T).Name + " found.");
			}
		}

		public static ScryVar Scry(this DynamicVarSet vard)
		{
			return (ScryVar)vard._vars["Scry"];
		}
