	public static class HarmonyExtensions
	{
		public static bool TryPatchAll(this Harmony harmony, Assembly assembly, string? category = null)
		{
			BaseLibMain.Logger.Info($"Starting PatchAll for assembly {assembly}");
			try
			{
				IEnumerable<(Type, PatchClassProcessor)> sequence = from type in AccessTools.GetTypesFromAssembly(assembly)
					where type.HasHarmonyAttribute()
					select (type, harmony.CreateClassProcessor(type));
				int successCount = 0;
				int failCount = 0;
				sequence.DoIf<(Type, PatchClassProcessor)>(((Type, PatchClassProcessor) processor) => category?.Equals(processor.Item2.Category) ?? string.IsNullOrEmpty(processor.Item2.Category), delegate((Type, PatchClassProcessor) processor)
				{
					try
					{
						processor.Item2.Patch();
						BaseLibMain.Logger.Debug("Patch " + processor.Item1.FullName + " successful.");
						int num = successCount + 1;
						successCount = num;
					}
					catch (Exception value2)
					{
						BaseLibMain.Logger.Error($"Patch {processor.Item1.FullName} failed;\n{value2}");
						int num = failCount + 1;
						failCount = num;
					}
				});
				BaseLibMain.Logger.Info($"Applied {successCount} patches successfully, {failCount} failed");
				return failCount == 0;
			}
			catch (Exception value)
			{
				BaseLibMain.Logger.Error($"Error occurred during TryPatchAll for assembly {assembly}: {value}");
				return false;
			}
		}

