		internal static T LogCode<T>(this T code) where T : IEnumerable<CodeInstruction>
		{
			BaseLibMain.Logger.Info("CODE:\n" + code.Join((CodeInstruction instruction) => instruction.ToString(), "\n"));
			return code;
		}

		public static void CheckCode(this IEnumerable<CodeInstruction> code)
		{
			List<CodeInstruction> list = code.ToList();
			HashSet<Label> hashSet = new HashSet<Label>();
			HashSet<Label> hashSet2 = new HashSet<Label>();
			for (int i = 0; i < list.Count; i++)
			{
				CodeInstruction codeInstruction = list[i];
				foreach (Label label2 in codeInstruction.labels)
				{
					if (!hashSet.Add(label2))
					{
						BaseLibMain.Logger.Warn($"DUPLICATE LABEL: {label2.Id}");
					}
				}
				if (codeInstruction.Branches(out var label))
				{
					if (!label.HasValue)
					{
						BaseLibMain.Logger.Warn($"Branch operation missing operand at index {i}");
					}
					else if (!hashSet2.Add(label.Value))
					{
						BaseLibMain.Logger.Warn($"Minor: Label {label.Value.Id} is reused");
					}
				}
				else if (codeInstruction.opcode == OpCodes.Switch)
				{
					if (!(codeInstruction.operand is Label[] array))
					{
						continue;
					}
					Label[] array2 = array;
					for (int j = 0; j < array2.Length; j++)
					{
						Label item = array2[j];
						if (!hashSet2.Add(item))
						{
							BaseLibMain.Logger.Warn($"Minor: Label {item.Id} is reused");
						}
					}
				}
				else
				{
					if (!(codeInstruction.opcode == OpCodes.Leave) && !(codeInstruction.opcode == OpCodes.Leave_S))
					{
						continue;
					}
					if (codeInstruction.operand is Label item2)
					{
						if (!hashSet2.Add(item2))
						{
							BaseLibMain.Logger.Warn($"Minor: Label {item2.Id} is reused");
						}
					}
					else
					{
						BaseLibMain.Logger.Warn($"Leave operation missing label operand at index {i}");
					}
				}
			}
			if (hashSet2.Count > hashSet.Count)
			{
				hashSet2.RemoveWhere(hashSet.Contains);
				BaseLibMain.Logger.Warn("Jump destinations not found: " + hashSet2.Join((Label label2) => label2.Id.ToString()));
			}
			else if (hashSet.Count > hashSet2.Count)
			{
				hashSet.RemoveWhere(hashSet2.Contains);
				BaseLibMain.Logger.Warn("Unused labels: " + hashSet.Join((Label label2) => label2.Id.ToString()));
			}
		}
	}
