		public static void ShowAndClearPendingErrors()
		{
			List<string> pendingUserMessages = ModConfigLogger.PendingUserMessages;
			if (pendingUserMessages.Count <= 0)
			{
				return;
			}
			NErrorPopup nErrorPopup = NErrorPopup.Create("Mod configuration error", string.Join('\n', pendingUserMessages), showReportBugButton: false);
			if (nErrorPopup != null && NModalContainer.Instance != null)
			{
				NModalContainer.Instance.Add((Node)(object)nErrorPopup);
				NVerticalPopup nodeOrNull = ((Node)nErrorPopup).GetNodeOrNull<NVerticalPopup>(NodePath.op_Implicit("VerticalPopup"));
				if (nodeOrNull != null)
				{
					((Control)(object)nodeOrNull.BodyLabel).AddThemeFontSizeOverrideAll(22);
					pendingUserMessages.Clear();
				}
			}
		}

