				}
				BaseLibMain.Logger.Error($"[ConfigVisibleIf] on '{annotatedMember.Name}': property '{visibleIf.TargetName}' is not a bool; at least one value to compare against is required.");
				return null;
			}
			MethodInfo method = GetType().GetMethod(visibleIf.TargetName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method != null && method.ReturnType == typeof(bool))
			{
				return BuildMethodCondition(method, visibleIf, annotatedMember);
			}
			BaseLibMain.Logger.Error($"[ConfigVisibleIf] on '{annotatedMember.Name}': no valid property or boolean method named '{visibleIf.TargetName}' found on {GetType().Name}.");
			return null;
		}

		private static Func<bool>? BuildPropertyCondition(PropertyInfo prop, ConfigVisibleIfAttribute visibleIf, MemberInfo annotatedMember)
