namespace BaseLib.Common.Rewards.LinkedRewardSet
{
	public class CustomLinkedRewardChoiceMessage : ICustomMessage, IPacketSerializable
	{
		public int setId;

		public int containerIndex;

		public int nestedIndex;

		public bool ShouldBroadcast => true;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(setId);
			writer.WriteInt(containerIndex, 8);
			writer.WriteInt(nestedIndex, 8);
		}

		public void Deserialize(PacketReader reader)
		{
			setId = reader.ReadInt();
			containerIndex = reader.ReadInt(8);
			nestedIndex = reader.ReadInt(8);
		}

		public void HandleMessage(ulong senderId)
		{
			if (RunManager.Instance.State == null)
			{
				BaseLibMain.Logger.Error("RunManager.State is null in a context where it shouldn't be");
				return;
			}
			RewardsSetSynchronizer rewardsSetSynchronizer = RunManager.Instance.RewardsSetSynchronizer;
			Player player = RunManager.Instance.State.GetPlayer(senderId);
			if (player != null)
			{
				RewardsSetSynchronizer.RewardsSetState rewardsSetState = rewardsSetSynchronizer.GetRewardStateForPlayer(player).rewardsStack.Last();
				RewardsSet set = rewardsSetState.set;
				if (containerIndex >= 0 && containerIndex < set.Rewards.Count && set.Rewards[containerIndex] is CustomLinkedRewardSet customLinkedRewardSet && nestedIndex >= 0 && nestedIndex < customLinkedRewardSet.Rewards.Count)
				{
					customLinkedRewardSet.SetPendingSelection(customLinkedRewardSet.Rewards[nestedIndex]);
					TaskHelper.RunSafely(rewardsSetSynchronizer.SelectRewardForPlayer(rewardsSetState, (Reward)customLinkedRewardSet));
				}
			}
		}
	}
	public class CustomLinkedRewardSet : CustomReward
	{
		[CustomEnum(null)]
		public static RewardType CustomLinkedRewardType;

		private const string SaveId = "baselib_customlinkedrewardset_children";

		private static readonly SpireField<Reward, CustomLinkedRewardSet?> ParentCustomLinkedRewardSet = new SpireField<Reward, CustomLinkedRewardSet>(() => (CustomLinkedRewardSet?)null);

		private List<Reward> _rewards;

		private LinkedRewardType _linkedRewardType;

		private bool _selectionStarted;

		private Reward? _pendingSelection;

		private LocString HoverTipTitle => new LocString("static_hover_tips", (LinkedRewardType == LinkedRewardType.Bundled) ? "BASELIB-BUNDLED_REWARDS.title" : "BASELIB-EXCLUSIVE_REWARDS.title");

		private LocString HoverTipDesc => new LocString("static_hover_tips", (LinkedRewardType == LinkedRewardType.Bundled) ? "BASELIB-BUNDLED_REWARDS.description" : "BASELIB-EXCLUSIVE_REWARDS.description");

		public HoverTip HoverTip => new HoverTip(HoverTipTitle, HoverTipDesc);

		public override LocString Description => new LocString("gameplay_ui", "COMBAT_REWARD_LINKED");

		public IReadOnlyList<Reward> Rewards => _rewards.ToList();

		protected override RewardType RewardType => CustomLinkedRewardType;

		public LinkedRewardType LinkedRewardType => _linkedRewardType;

		public override int RewardsSetIndex => Rewards.Max((Reward r) => r.RewardsSetIndex);

		public override bool IsPopulated => _rewards.All((Reward r) => r.IsPopulated);

		public override CreateRewardFromSave<CustomReward> DeserializeMethod => CreateFromSerializable;

		public static bool TryGetCustomLinkedRewardSet(Reward reward, [NotNullWhen(true)] out CustomLinkedRewardSet? customLinkedRewardSet)
		{
			customLinkedRewardSet = ParentCustomLinkedRewardSet.Get(reward);
			return customLinkedRewardSet != null;
		}

		private CustomLinkedRewardSet()
			: base(null)
		{
			_rewards = new List<Reward>();
		}

		public CustomLinkedRewardSet(List<Reward> rewards, Player player, LinkedRewardType linkedRewardType = LinkedRewardType.Exclusive)
			: base(player)
		{
			_rewards = rewards;
			_linkedRewardType = linkedRewardType;
			foreach (Reward reward in _rewards)
			{
				ParentCustomLinkedRewardSet.Set(reward, this);
			}
		}

		public override void Populate()
		{
			foreach (Reward reward in _rewards)
			{
				reward.Populate();
			}
		}

		public override void MarkContentAsSeen()
		{
			foreach (Reward reward in _rewards)
			{
				reward.MarkContentAsSeen();
			}
		}

		public override void OnSkipped()
		{
			foreach (Reward reward in _rewards)
			{
				reward.OnSkipped();
			}
		}

		protected override async Task<bool> OnSelect()
		{
			if (_selectionStarted)
			{
				return base.SuccessfullySelected;
			}
			_selectionStarted = true;
			return LinkedRewardType switch
			{
				LinkedRewardType.Exclusive => await OnSelectExclusive(), 
				LinkedRewardType.Bundled => await OnSelectBundled(), 
				_ => true, 
			};
		}

		private async Task<bool> OnSelectExclusive()
		{
			Reward chosen = _pendingSelection;
			_pendingSelection = null;
			if (chosen == null)
			{
				BaseLibMain.Logger.Error("No Reward selected. Should not happen!");
				_selectionStarted = false;
				return false;
			}
			bool flag = chosen.SuccessfullySelected;
			if (!flag)
			{
				flag = await chosen.SelectUnsynchronized();
			}
			if (!flag)
			{
				_selectionStarted = false;
				return false;
			}
			foreach (Reward item in from reward in _rewards.ToList()
				where reward != chosen && !reward.SuccessfullySelected
				select reward)
			{
				item.OnSkipped();
			}
			return true;
		}

		private async Task<bool> OnSelectBundled()
		{
			List<Reward> list = _rewards.ToList();
			Reward pendingSelection = _pendingSelection;
			_pendingSelection = null;
			if (pendingSelection != null && list.Remove(pendingSelection))
			{
				list.Insert(0, pendingSelection);
			}
			foreach (Reward reward in list)
			{
				if (!reward.SuccessfullySelected && !(await reward.SelectUnsynchronized()))
				{
					if (!_rewards.Any((Reward r) => r.SuccessfullySelected))
					{
						_selectionStarted = false;
						return false;
					}
					reward.OnSkipped();
				}
			}
			return true;
		}

		public void RemoveReward(Reward reward)
		{
			_rewards.Remove(reward);
		}

		public void SetPendingSelection(Reward chosen)
		{
			_pendingSelection = chosen;
		}

		public static CustomReward CreateFromSerializable(SerializableReward save, Player player)
		{
			return new CustomLinkedRewardSet(new List<Reward>(), player);
		}

		private void RestoreRewards(List<Reward> rewards, LinkedRewardType linkedRewardType)
		{
			_rewards = rewards;
			_linkedRewardType = linkedRewardType;
			foreach (Reward reward in _rewards)
			{
				ParentCustomLinkedRewardSet.Set(reward, this);
			}
		}

		public override void Initialize()
		{
			base.Initialize();
			ExtendedSaveTypes.RegisterObjectSaveType<SerializableCustomLinkedRewardSet>(new Func<JsonSerializerOptions, JsonPropertyInfo>[2]
			{
				ExtendedSaveTypes.PropertyFunc<SerializableCustomLinkedRewardSet, List<SerializableReward>>("Rewards"),
				ExtendedSaveTypes.PropertyFunc<SerializableCustomLinkedRewardSet, int>("LinkedRewardTypeValue")
			});
			ExtendedSaveHandlers<Reward, SerializableReward>.RegisterSave("baselib_customlinkedrewardset_children", (Reward reward) => (!(reward is CustomLinkedRewardSet customLinkedRewardSet)) ? null : new SerializableCustomLinkedRewardSet
			{
				Rewards = customLinkedRewardSet.Rewards.Select((Reward r) => r.ToSerializable()).ToList(),
				LinkedRewardTypeValue = (int)customLinkedRewardSet.LinkedRewardType
			}, delegate(Reward reward, SerializableCustomLinkedRewardSet? value)
			{
				if (reward is CustomLinkedRewardSet customLinkedRewardSet && value != null)
				{
					List<Reward> rewards = value.Rewards.Select((SerializableReward sr) => Reward.FromSerializable(sr, reward.Player)).ToList();
					customLinkedRewardSet.RestoreRewards(rewards, (LinkedRewardType)value.LinkedRewardTypeValue);
				}
			});
		}
	}
	public class SerializableCustomLinkedRewardSet : IPacketSerializable
	{
		public List<SerializableReward> Rewards { get; set; } = new List<SerializableReward>();

		public int LinkedRewardTypeValue { get; set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteList(Rewards);
			writer.WriteInt(LinkedRewardTypeValue);
		}

		public void Deserialize(PacketReader reader)
		{
			Rewards = reader.ReadList<SerializableReward>();
			LinkedRewardTypeValue = reader.ReadInt();
		}
	}
	[HarmonyPatch]
	public static class CustomLinkedRewardSet_Patches
	{
		[HarmonyPatch(typeof(NRewardButton), "SetReward")]
		[HarmonyPrefix]
		private static void ThrowIfMisuseOfCustomRewardSet(Reward reward)
		{
			if (reward is CustomLinkedRewardSet)
			{
				throw new ArgumentException("You aren't allowed to apply a CustomLinkedRewardSet to an NRewardButton");
			}
		}

		[HarmonyPatch(typeof(Reward), "HoverTips", MethodType.Getter)]
		[HarmonyPostfix]
		private static void AddHoverTip(Reward __instance, ref IEnumerable<IHoverTip> __result)
		{
			if (CustomLinkedRewardSet.TryGetCustomLinkedRewardSet(__instance, out CustomLinkedRewardSet customLinkedRewardSet))
			{
				List<IHoverTip> list = __result.ToList();
				list.Add(customLinkedRewardSet.HoverTip);
				__result = list;
			}
		}
	}
	[HarmonyPatch]
	public static class CustomLinkedRewardSet_MultiplayerPatches
	{
		[HarmonyPatch(typeof(RewardsSetSynchronizer), "SelectLocalReward")]
		private static class RedirectNestedRewardSelection
		{
			[HarmonyPrefix]
			private static bool Prefix(RewardsSetSynchronizer __instance, ref Task<bool> __result, ref Reward reward)
			{
				if (!CustomLinkedRewardSet.TryGetCustomLinkedRewardSet(reward, out CustomLinkedRewardSet customLinkedRewardSet))
				{
					return true;
				}
				if (customLinkedRewardSet.SuccessfullySelected)
				{
					__result = Task.FromResult(result: true);
					return false;
				}
				RewardsSetSynchronizer.RewardsSetState rewardsSetState = __instance.GetRewardStateForPlayer(__instance.LocalPlayer).rewardsStack.Last();
				int containerIndex = rewardsSetState.set.Rewards.IndexOf(customLinkedRewardSet);
				int nestedIndex = customLinkedRewardSet.Rewards.ToList().IndexOf(reward);
				customLinkedRewardSet.SetPendingSelection(reward);
				__result = __instance.SelectRewardForPlayer(rewardsSetState, (Reward)customLinkedRewardSet);
				CustomMessageWrapper.Send(new CustomLinkedRewardChoiceMessage
				{
					setId = rewardsSetState.set.Id,
					containerIndex = containerIndex,
					nestedIndex = nestedIndex
				});
				return false;
			}
		}
	}
	public enum LinkedRewardType
	{
		None,
		Exclusive,
		Bundled
	}
}
