	public class CustomCalculatedVar : CalculatedVar
	{
		private Func<RelicModel, Creature?, decimal>? _relicCalc;

		private Func<PowerModel, Creature?, decimal>? _powerCalc;

		private Func<DynamicVarSource, Creature?, decimal>? _generalCalc;

		public static IEnumerable<DynamicVar> Create(string name, int baseVal, Func<DynamicVarSource, Creature?, decimal> bonus, int mult = 1)
		{
			CustomCalculatedVar calculatedVar = new CustomCalculatedVar(name);
			calculatedVar.GeneralMultiplier(bonus);
			yield return new DynamicVar(calculatedVar.Name + "Base", baseVal);
			yield return new DynamicVar(calculatedVar.Name + "Extra", mult);
			yield return calculatedVar;
		}

		public CustomCalculatedVar(string name)
			: base(name)
		{
		}

		public virtual decimal CalculateCustom(Creature? target)
		{
			return CalculateCustomVar(this, GetBaseVar(), GetExtraVar(), target, base.Calculate, _relicCalc, _powerCalc, _generalCalc);
		}

		public static decimal CalculateCustomVar(DynamicVar dynVar, DynamicVar baseVar, DynamicVar extraVar, Creature? target, Func<Creature?, decimal> cardCalc, Func<RelicModel, Creature?, decimal>? relicCalc, Func<PowerModel, Creature?, decimal>? powerCalc, Func<DynamicVarSource, Creature?, decimal>? generalCalc)
		{
			AbstractModel owner = dynVar._owner;
			if (!(owner is CardModel))
			{
				decimal num;
				if (!(owner is PowerModel arg))
				{
					if (!(owner is RelicModel arg2))
					{
						if (!(owner is PotionModel potionModel))
						{
							if (!(owner is EnchantmentModel enchantmentModel))
							{
								if (owner is CardModifier cardModifier)
								{
									decimal obj;
									if (CombatManager.Instance.IsInProgress && cardModifier.Owner.Owner.Creature.CombatState != null)
									{
										if (generalCalc == null)
										{
											throw new InvalidOperationException($"{dynVar.GetType().Name} {dynVar.Name} does not have multiplier calc defined for card modifiers in {owner.Id}");
										}
										obj = generalCalc(cardModifier, target);
									}
									else
									{
										obj = 0m;
									}
									num = obj;
									return baseVar.BaseValue + extraVar.BaseValue * num;
								}
								return dynVar.BaseValue;
							}
							decimal obj2;
							if (CombatManager.Instance.IsInProgress && enchantmentModel.Card.Owner.Creature.CombatState != null)
							{
								if (generalCalc == null)
								{
									throw new InvalidOperationException($"{dynVar.GetType().Name} {dynVar.Name} does not have multiplier calc defined for enchantments in {owner.Id}");
								}
								obj2 = generalCalc(enchantmentModel, target);
							}
							else
							{
								obj2 = 0m;
							}
							num = obj2;
							return baseVar.BaseValue + extraVar.BaseValue * num;
						}
						if (generalCalc == null)
						{
							throw new InvalidOperationException($"{dynVar.GetType().Name} {dynVar.Name} does not have multiplier calc defined for potions in {owner.Id}");
						}
						num = generalCalc(potionModel, target);
						return baseVar.BaseValue + extraVar.BaseValue * num;
					}
					if (relicCalc == null)
					{
						throw new InvalidOperationException($"{dynVar.GetType().Name} {dynVar.Name} does not have multiplier calc defined for relics in {owner.Id}");
					}
					num = relicCalc(arg2, target);
					return baseVar.BaseValue + extraVar.BaseValue * num;
				}
				if (powerCalc == null)
				{
					throw new InvalidOperationException($"{dynVar.GetType().Name} {dynVar.Name} does not have multiplier calc defined for powers in {owner.Id}");
				}
				num = powerCalc(arg, target);
				return baseVar.BaseValue + extraVar.BaseValue * num;
			}
			return cardCalc(target);
		}

