		public CalculatedVar WithMultiplier(Func<PowerModel, Creature?, decimal> multiplierCalc)
		{
			if (_powerCalc != null)
			{
				throw new InvalidOperationException("Tried to set multiplier calc for power on CustomCalculatedVar " + base.Name + " twice!");
			}
			if (multiplierCalc.Target is AbstractModel)
			{
				throw new InvalidOperationException("Multiplier calc must be static!");
			}
			_powerCalc = multiplierCalc;
			return this;
		}

		public CalculatedVar GeneralMultiplier(Func<DynamicVarSource, Creature?, decimal> multiplierCalc)
		{
			if (_generalCalc != null)
			{
				throw new InvalidOperationException("Tried to set multiplier calc for CustomCalculatedVar " + base.Name + " twice!");
			}
			if (multiplierCalc.Target is AbstractModel)
			{
				throw new InvalidOperationException("Multiplier calc must be static!");
			}
			WithMultiplier((CardModel card, Creature? c) => multiplierCalc(card, c));
			_powerCalc = (PowerModel pow, Creature? target) => multiplierCalc(pow, target);
			_relicCalc = (RelicModel pow, Creature? target) => multiplierCalc(pow, target);
			_generalCalc = multiplierCalc;
			return this;
		}

		protected override DynamicVar GetBaseVar()
		{
			return _owner.GetDynamicVar(base.Name + "Base");
		}

		protected override DynamicVar GetExtraVar()
		{
			return _owner.GetDynamicVar(base.Name + "Extra");
		}

		protected override decimal GetBaseValueForIConvertible()
		{
			return CalculateCustom(null);
		}

		public override string ToString()
		{
			return CalculateCustom(null).ToString();
		}
	}
	public class CustomExtraDamageVar : DynamicVar
	{
		public CustomExtraDamageVar(string baseName, decimal damage)
			: base(baseName + "Extra", damage)
		{
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			decimal baseValue = base.BaseValue;
			baseValue = (base.EnchantedValue = ModifyBaseDamagePatches.ModifyBaseDamageMultiplicative(baseValue, ValueProp.Move, card, ModifyDamageHookType.All));
			EnchantmentModel enchantment = card.Enchantment;
			if (enchantment != null)
			{
				baseValue *= enchantment.EnchantDamageMultiplicative(baseValue, ValueProp.Move);
				if (!card.IsEnchantmentPreview)
				{
					base.EnchantedValue = baseValue;
				}
			}
			base.PreviewValue = baseValue;
		}
	}
	public class DisplayVar<T> : DynamicVar where T : class
	{
		private T? _tOwner;

		private readonly Func<T, string> _displayText;

		public DisplayVar(string name, Func<T, string> displayText)
			: base(name, 0m)
		{
			_displayText = displayText;
		}

		public override void SetOwner(AbstractModel owner)
		{
			base.SetOwner(owner);
			_tOwner = owner as T;
		}

		public override string ToString()
		{
			if (_tOwner != null)
			{
				return _displayText(_tOwner);
			}
			return $"Owner of DisplayVar '' is wrong type [{_owner?.GetType()}]";
		}
	}
	public class ExhaustiveVar : DynamicVar
	{
		public const string Key = "Exhaustive";

		public ExhaustiveVar(decimal exhaustiveCount)
			: base("Exhaustive", exhaustiveCount)
		{
			this.WithTooltip();
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			base.PreviewValue = ExhaustiveCount(card, base.IntValue);
		}

		public static int ExhaustiveCount(CardModel card, int baseExhaustive)
		{
			if (baseExhaustive <= 0)
			{
				return 0;
			}
			int num = CombatManager.Instance.History.CardPlaysFinished.Count((CardPlayFinishedEntry entry) => entry.CardPlay.Card == card);
			return Math.Max(1, baseExhaustive - num);
		}
	}
	public class PersistVar : DynamicVar
	{
		public const string Key = "Persist";

		public PersistVar(decimal persistCount)
			: base("Persist", persistCount)
		{
			this.WithTooltip();
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			base.PreviewValue = PersistCount(card, base.IntValue);
		}

		public static int PersistCount(CardModel card, int basePersist)
		{
			int num = CombatManager.Instance.History.CardPlaysFinished.Count((CardPlayFinishedEntry entry) => entry.HappenedThisTurn(card.CombatState) && entry.CardPlay.Card == card);
			return Math.Max(0, basePersist - num);
		}
	}
	public class RefundVar : DynamicVar
	{
		public const string Key = "Refund";

		public RefundVar(decimal refundAmount)
			: base("Refund", refundAmount)
		{
			this.WithTooltip();
		}
	}
	public class ScryVar : DynamicVar
	{
		public ScryVar(decimal baseValue)
			: base("Scry", baseValue)
		{
			this.WithTooltip();
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			int num = base.IntValue;
			if (runGlobalHooks)
			{
				num = BaseLibHooks.ModifyScryAmount(card.Owner, num, out IEnumerable<IModifyScryAmount> _);
			}
			base.PreviewValue = num;
		}
	}
