	[HarmonyPatch(typeof(CardModel), "UpgradeInternal")]
	internal static class UpgradeModifiers
	{
		[HarmonyPostfix]
		private static void UpgradeModifiersOnCard(CardModel __instance)
		{
			foreach (CardModifier item in CardModifier.Modifiers(__instance))
			{
				item.OnUpgrade();
				item.DynamicVars.RecalculateForUpgradeOrEnchant();
			}
		}
	}
	[HarmonyPatch(typeof(CardModel), "DowngradeInternal")]
	internal static class DowngradeModifiers
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> DowngradeModifiersOnCard(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new CallMatcher(typeof(CardModel).DeclaredMethod("AfterDowngraded"))).InsertBeforeMatch(new global::<>z__ReadOnlySingleElementList<CodeInstruction>(CodeInstruction.Call(typeof(DowngradeModifiers), "OnDowngrade")));
		}

		private static CardModel OnDowngrade(CardModel card)
		{
			foreach (CardModifier item in CardModifier.Modifiers(card))
			{
				item.OnDowngrade();
				item.DynamicVars.RecalculateForUpgradeOrEnchant();
			}
			return card;
		}
	}
	[HarmonyPatch(typeof(CardModel), "FinalizeUpgradeInternal")]
	internal static class FinalizeModifierUpgrade
	{
		[HarmonyPostfix]
		private static void FinalizeModifiersOnCard(CardModel __instance)
		{
			foreach (CardModifier item in CardModifier.Modifiers(__instance))
			{
				item.DynamicVars.FinalizeUpgrade();
			}
		}
	}
	[HarmonyPatch(typeof(CardModel), "UpdateDynamicVarPreview")]
	internal static class UpdateModifierPreview
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> UpdateModifierVars(IEnumerable<CodeInstruction> code)
		{
			List<CodeInstruction> match;
			InstructionPatcher instructionPatcher = new InstructionPatcher(code).Match(new InstructionMatcher().ldarg_0().ldarg_1().ldarg_2()
				.ldloc_any()
				.callvirt(typeof(DynamicVar), "UpdateCardPreview")).CopyMatch(out match).MatchEnd()
				.Step(-1);
			List<CodeInstruction> list = new List<CodeInstruction>();
			list.AddRange(match.SkipLast(1));
			list.Add(CodeInstruction.Call(typeof(UpdateModifierPreview), "UpdateModifierVarPreview"));
			return instructionPatcher.Insert(new global::<>z__ReadOnlyList<CodeInstruction>(list));
		}

		private static void UpdateModifierVarPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			foreach (CardModifier item in CardModifier.Modifiers(card))
			{
				item.UpdateDynamicVarPreview(previewMode, target, runGlobalHooks);
			}
		}
	}
	public abstract class ConstructedCardModel(int baseCost, CardType type, CardRarity rarity, TargetType target, bool showInCardLibrary = true, bool autoAdd = true) : CustomCardModel(baseCost, type, rarity, target, showInCardLibrary, autoAdd)
	{
		protected enum UpgradeType
		{
			None,
			Add,
			Remove
		}

		private readonly List<CardKeyword> _cardKeywords = new List<CardKeyword>();

		protected readonly List<(CardKeyword, UpgradeType)> UpgradeKeywords = new List<(CardKeyword, UpgradeType)>();

		private readonly List<DynamicVar> _constructedDynamicVars = new List<DynamicVar>();

		private readonly List<TooltipSource> _hoverTips = new List<TooltipSource>();

		private readonly List<Func<CardModel, IEnumerable<IHoverTip>>> _multiHoverTips = new List<Func<CardModel, IEnumerable<IHoverTip>>>();

		private readonly HashSet<CardTag> _constructedTags = new HashSet<CardTag>();

		private bool _hasBasegameCalculatedVar;

		internal int? CostUpgrade;

		protected sealed override IEnumerable<DynamicVar> CanonicalVars => _constructedDynamicVars;

		public sealed override IEnumerable<CardKeyword> CanonicalKeywords => _cardKeywords;

		protected sealed override IEnumerable<IHoverTip> ExtraHoverTips => _hoverTips.Select((TooltipSource t) => t.Tip(this)).Concat(_multiHoverTips.SelectMany((Func<CardModel, IEnumerable<IHoverTip>> mt) => mt(this)));

		protected sealed override HashSet<CardTag> CanonicalTags => _constructedTags;

		protected ConstructedCardModel WithVars(params DynamicVar[] vars)
		{
			foreach (DynamicVar dynamicVar in vars)
			{
				_constructedDynamicVars.Add(dynamicVar);
				Type type = dynamicVar.GetType();
				if (!type.IsGenericType)
				{
					continue;
				}
				Type[] genericArguments = type.GetGenericArguments();
				foreach (Type type2 in genericArguments)
				{
					if (type2.IsAssignableTo(typeof(PowerModel)))
					{
						WithTip(type2);
					}
				}
			}
			return this;
		}

		protected ConstructedCardModel WithVar(string name, int baseVal, int upgrade = 0)
		{
			_constructedDynamicVars.Add(new DynamicVar(name, baseVal).WithUpgrade(upgrade));
			return this;
		}

		protected ConstructedCardModel WithVar(DynamicVar var)
		{
			return WithVars(var);
		}

		protected ConstructedCardModel WithBlock(int baseVal, int upgrade = 0)
		{
			_constructedDynamicVars.Add(new BlockVar(baseVal, ValueProp.Move).WithUpgrade(upgrade));
			return this;
		}

		protected ConstructedCardModel WithDamage(int baseVal, int upgrade = 0)
		{
			_constructedDynamicVars.Add(new DamageVar(baseVal, ValueProp.Move).WithUpgrade(upgrade));
			return this;
		}

		protected ConstructedCardModel WithCards(int baseVal, int upgrade = 0)
		{
			CardsVar item = new CardsVar(baseVal).WithUpgrade(upgrade);
			_constructedDynamicVars.Add(item);
			return this;
		}

		protected ConstructedCardModel WithEnergy(int baseVal, int upgrade = 0)
		{
			EnergyVar item = new EnergyVar(baseVal).WithUpgrade(upgrade);
			_constructedDynamicVars.Add(item);
			WithEnergyTip();
			return this;
		}

		protected ConstructedCardModel WithHeal(int baseVal, int upgrade = 0)
		{
