		protected ConstructedCardModel WithCalculatedBlock(int baseVal, Func<CardModel, Creature?, decimal> bonus, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			if (_hasBasegameCalculatedVar)
			{
				throw new Exception("CardModel only supports a single normal calculated var; use WithCalculatedBlock while providing a custom name to useCustomCalculatedBlockVar instead");
			}
			_hasBasegameCalculatedVar = true;
			SetupCalculatedVar(new CalculatedBlockVar(props), baseVal, 1, bonus, upgrade, bonusUpgrade);
			return this;
		}

		protected ConstructedCardModel WithCalculatedBlock(int baseVal, int multVal, Func<CardModel, Creature?, decimal> mult, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
