			}
			_hasBasegameCalculatedVar = true;
			SetupCalculatedVar(new CalculatedBlockVar(props), baseVal, multVal, mult, upgrade, bonusUpgrade);
			return this;
		}

		protected ConstructedCardModel WithCalculatedBlock(string name, int baseVal, Func<CardModel, Creature?, decimal> bonus, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
