			return this;
		}

		protected ConstructedCardModel WithCalculatedBlock(string name, int baseVal, int multVal, Func<CardModel, Creature?, decimal> mult, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			SetupCalculatedVar(new CustomCalculatedBlockVar(name, props), baseVal, multVal, mult, upgrade, bonusUpgrade);
