		}

		protected ConstructedCardModel WithCalculatedDamage(int baseVal, Func<CardModel, Creature?, decimal> bonus, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			if (_hasBasegameCalculatedVar)
			{
				throw new Exception("CardModel only supports a single normal calculated var; use WithCalculatedDamage while providing a custom name to useCustomCalculatedBlockVar instead");
			}
			_hasBasegameCalculatedVar = true;
			SetupCalculatedVar(new CalculatedDamageVar(props), baseVal, 1, bonus, upgrade, bonusUpgrade);
			return this;
		}

		protected ConstructedCardModel WithCalculatedDamage(int baseVal, int multVal, Func<CardModel, Creature?, decimal> mult, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			if (_hasBasegameCalculatedVar)
			{
				throw new Exception("CardModel only supports a single normal calculated var; use WithCalculatedDamage while providing a custom name to useCustomCalculatedDamageVar instead");
			}
			_hasBasegameCalculatedVar = true;
			SetupCalculatedVar(new CalculatedDamageVar(props), baseVal, multVal, mult, upgrade, bonusUpgrade);
			return this;
		}

		protected ConstructedCardModel WithCalculatedDamage(string name, int baseVal, Func<CardModel, Creature?, decimal> bonus, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			SetupCalculatedVar(new CustomCalculatedDamageVar(name, props), baseVal, 1, bonus, upgrade, bonusUpgrade);
			return this;
		}

		protected ConstructedCardModel WithCalculatedDamage(string name, int baseVal, int multVal, Func<CardModel, Creature?, decimal> mult, ValueProp props = ValueProp.Move, int upgrade = 0, int bonusUpgrade = 0)
		{
			if (_hasBasegameCalculatedVar)
			{
				throw new Exception("CardModel only supports a single normal calculated var; use WithCalculatedDamage while providing a custom name to useCustomCalculatedDamageVar instead");
			}
			_hasBasegameCalculatedVar = true;
			SetupCalculatedVar(new CustomCalculatedDamageVar(name, props), baseVal, multVal, mult, upgrade, bonusUpgrade);
			return this;
		}

		private void SetupCalculatedVar(CalculatedVar var, int baseVal, int multVal, Func<CardModel, Creature?, decimal> mult, int upgrade, int bonusUpgrade)
		{
			if (!(var is CustomCalculatedVar) && !(var is CustomCalculatedBlockVar))
			{
				if (!(var is CustomCalculatedDamageVar))
				{
					if (var is CalculatedDamageVar)
					{
						_constructedDynamicVars.Add(new CalculationBaseVar(baseVal).WithUpgrade(upgrade));
						_constructedDynamicVars.Add(new ExtraDamageVar(multVal).WithUpgrade(bonusUpgrade));
					}
					else
					{
						_constructedDynamicVars.Add(new CalculationBaseVar(baseVal).WithUpgrade(upgrade));
						_constructedDynamicVars.Add(new CalculationExtraVar(multVal).WithUpgrade(bonusUpgrade));
					}
				}
				else
				{
					_constructedDynamicVars.Add(new DynamicVar(var.Name + "Base", baseVal).WithUpgrade(upgrade));
					_constructedDynamicVars.Add(new CustomExtraDamageVar(var.Name, multVal).WithUpgrade(bonusUpgrade));
				}
			}
			else
			{
				_constructedDynamicVars.Add(new DynamicVar(var.Name + "Base", baseVal).WithUpgrade(upgrade));
				_constructedDynamicVars.Add(new DynamicVar(var.Name + "Extra", multVal).WithUpgrade(bonusUpgrade));
			}
			_constructedDynamicVars.Add(var.WithMultiplier(mult));
		}

		protected ConstructedCardModel WithKeywords(params CardKeyword[] keywords)
		{
			_cardKeywords.AddRange(keywords);
			return this;
		}

		protected ConstructedCardModel WithKeyword(CardKeyword keyword, UpgradeType upgradeType = UpgradeType.None)
		{
			if (upgradeType != UpgradeType.Add)
			{
				_cardKeywords.Add(keyword);
			}
			if (upgradeType != UpgradeType.None)
			{
				UpgradeKeywords.Add((keyword, upgradeType));
			}
			return this;
		}

		protected ConstructedCardModel WithCostUpgradeBy(int amount)
		{
			CostUpgrade = amount;
			return this;
		}

		protected ConstructedCardModel WithTip(TooltipSource tipSource)
		{
			_hoverTips.Add(tipSource);
			return this;
		}

		protected ConstructedCardModel WithTips(Func<CardModel, IEnumerable<IHoverTip>> multiTipSource)
		{
			_multiHoverTips.Add(multiTipSource);
			return this;
		}

		protected ConstructedCardModel WithEnergyTip()
		{
			_hoverTips.Add(new TooltipSource(HoverTipFactory.ForEnergy));
			return this;
		}

		protected ConstructedCardModel WithUpgradingCardTip<T>(Action<T, CardModel>? modifyTipCard = null) where T : CardModel
		{
			return WithTip(new TooltipSource(delegate(CardModel card)
			{
				CardModel cardModel = ModelDb.Card<T>().ToMutable();
				if (card.IsUpgraded)
				{
					cardModel.UpgradeInternal();
				}
				if (cardModel is T arg)
				{
					modifyTipCard?.Invoke(arg, card);
				}
				return HoverTipFactory.FromCard(cardModel);
			}));
		}

		public void ConstructedUpgrade()
		{
			foreach (var upgradeKeyword in UpgradeKeywords)
			{
				switch (upgradeKeyword.Item2)
				{
				case UpgradeType.Add:
					AddKeyword(upgradeKeyword.Item1);
					break;
				case UpgradeType.Remove:
					RemoveKeyword(upgradeKeyword.Item1);
					break;
				}
			}
			if (CostUpgrade.HasValue)
			{
				base.EnergyCost.UpgradeBy(CostUpgrade.Value);
			}
		}
	}
