		public Badge ToRealBadge(SerializableRun run, bool won, ulong playerId)
		{
			Badge badge = ((!(MainBranchBadgeConstructor == null)) ? GeneratedOldBadge(this, run, playerId) : GeneratedNewBadge(this, run, won, playerId));
			BaseLibMain.Logger.Info($"Setting custom badge path {CustomBadgeIconPath} for badge {badge}");
			CustomBadgeIconPathDict[badge] = CustomBadgeIconPath;
			return badge;
		}

		private static Badge GeneratedOldBadge(CustomBadge baseBadge, SerializableRun run, ulong playerId)
		{
			if (!GeneratedBadges.TryGetValue(baseBadge.GetType(), out Type value))
			{
