	internal class CustomBadgesPatch
	{
		public static void Patch(Harmony harmony)
		{
			MethodInfo methodInfo = typeof(BadgePool).Method("CreateAll");
			if (methodInfo.GetParameters().Length == 3)
			{
				harmony.Patch(methodInfo, null, typeof(CustomBadgesPatch).Method("AddCustomBadgesNew"));
			}
			else
			{
				harmony.Patch(methodInfo, null, typeof(CustomBadgesPatch).Method("AddCustomBadgesOld"));
			}
		}

		private static IReadOnlyCollection<Badge> AddCustomBadgesNew(IReadOnlyCollection<Badge> __result, SerializableRun run, bool won, ulong playerId)
		{
			List<Badge> list = __result.ToList();
			foreach (Type customBadgeType in CustomContentDictionary.CustomBadgeTypes)
			{
				CustomBadge customBadge = (CustomBadge)Activator.CreateInstance(customBadgeType);
				list.Add(customBadge.ToRealBadge(run, won, playerId));
			}
			return list;
		}

		private static IReadOnlyCollection<Badge> AddCustomBadgesOld(IReadOnlyCollection<Badge> __result, SerializableRun run, ulong playerId)
		{
			List<Badge> list = __result.ToList();
			foreach (Type customBadgeType in CustomContentDictionary.CustomBadgeTypes)
			{
				CustomBadge customBadge = (CustomBadge)Activator.CreateInstance(customBadgeType);
				list.Add(customBadge.ToRealBadge(run, won: true, playerId));
			}
			return list;
		}
	}
	[HarmonyPatch(typeof(NBadge), "Create", new Type[]
	{
		typeof(string),
		typeof(BadgeRarity)
	})]
	internal class NBadgeCreateStringPatch
	{
		[HarmonyTranspiler]
		private static List<CodeInstruction> CreateCustomBadge(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new InstructionMatcher().ldstr("ui/game_over_screen/badge_"), new CallMatcher(typeof(ImageHelper).Method("GetImagePath"))).Step(-1).Insert(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[2]
			{
				CodeInstruction.LoadArgument(0),
				CodeInstruction.Call(typeof(NBadgeCreateStringPatch), "UseCustomBadgeIconPath")
			}));
		}

		private static string UseCustomBadgeIconPath(string origPath, string id)
		{
			Type type = CustomContentDictionary.CustomBadgeTypes.FirstOrDefault((Type t) => (t.GetPrefix() + StringExtensions.ToSnakeCase(t.Name).ToUpperInvariant()).Equals(id, StringComparison.OrdinalIgnoreCase));
			if (type == null)
			{
				return origPath;
			}
			CustomBadge customBadge = (CustomBadge)RuntimeHelpers.GetUninitializedObject(type);
			if (string.IsNullOrEmpty(customBadge.CustomBadgeIconPath))
			{
				return origPath;
			}
			return customBadge.CustomBadgeIconPath;
		}
	}
