	public abstract class CustomEventModel : EventModel, ICustomModel, ILocalizationProvider
	{
		public virtual ActModel[] Acts => Array.Empty<ActModel>();

		public virtual string? CustomInitialPortraitPath => null;

		public virtual string? CustomBackgroundScenePath => null;

		public virtual string? CustomVfxPath => null;

		public virtual List<(string, string)>? Localization => null;

		public CustomEventModel(bool autoAdd = true)
		{
			if (autoAdd)
			{
				CustomContentDictionary.AddEvent(this);
			}
		}

		protected EventOption Option(Func<Task>? onChosen, LocString title, LocString description, params IHoverTip[] tips)
		{
			return new EventOption(this, onChosen, title, description, base.Id.Entry, tips);
		}

		protected EventOption Option(Func<Task>? onChosen, string pageKey = "INITIAL", params IHoverTip[] tips)
		{
			MethodInfo methodInfo = onChosen?.Method;
			string txt = "UNKNOWN";
			if (methodInfo == null)
			{
				BaseLibMain.Logger.Error("Unable to get delegate method for CustomEventModel.Option; provide an explicit title and description LocString if not passing a method directly.");
			}
			else
			{
				if (methodInfo.IsSpecialName)
				{
					BaseLibMain.Logger.Warn("Method passed as delegate to CustomEventModel.Option has special name; recommended to directly pass declared method or provide an explicit title and description LocString.");
				}
				txt = methodInfo.Name;
			}
			return new EventOption(this, onChosen, $"{base.Id.Entry}.pages.{pageKey}.options.{StringHelper.Slugify(txt)}", tips);
		}

		protected EventOption Option(Func<Task>? onChosen, IEnumerable<IHoverTip> tips, string pageKey = "INITIAL")
		{
			MethodInfo methodInfo = onChosen?.Method;
			string txt = "UNKNOWN";
			if (onChosen == null)
			{
				BaseLibMain.Logger.Warn("Defining event option with no effect in event " + base.Id.Entry + ", use LockedOption rather than Option");
			}
			else if (methodInfo == null)
			{
				BaseLibMain.Logger.Error("Unable to get delegate method for CustomEventModel.Option; provide an explicit title and description LocString if not passing a method directly.");
			}
			else
			{
				if (methodInfo.IsSpecialName)
				{
					BaseLibMain.Logger.Warn("Method passed as delegate to CustomEventModel.Option has special name; recommended to directly pass declared method or provide an explicit title and description LocString.");
				}
				txt = methodInfo.Name;
			}
			string text = $"{base.Id.Entry}.pages.{pageKey}.options.{StringHelper.Slugify(txt)}";
			if (!LocString.Exists("events", text + ".title"))
			{
				BaseLibMain.Logger.Warn("Missing localization key " + text + ".title for event " + GetType().Name);
			}
			if (!LocString.Exists("events", text + ".description"))
			{
				BaseLibMain.Logger.Warn("Missing localization key " + text + ".description for event " + GetType().Name);
			}
			return new EventOption(this, onChosen, text, tips);
		}

		protected EventOption LockedOption(string locKey, string pageKey = "INITIAL", params IHoverTip[] tips)
		{
			string text = $"{base.Id.Entry}.pages.{pageKey}.options.{locKey}";
			if (!LocString.Exists("events", text + ".title"))
			{
				BaseLibMain.Logger.Warn("Missing localization key " + text + ".title for event " + GetType().Name);
			}
			if (!LocString.Exists("events", text + ".description"))
			{
				BaseLibMain.Logger.Warn("Missing localization key " + text + ".description for event " + GetType().Name);
			}
			return new EventOption(this, null, text, tips);
		}

		protected LocString PageDescription(string pageKey)
		{
			return L10NLookup(base.Id.Entry + ".pages." + pageKey + ".description");
		}
	}
