	public sealed class CustomMessageWrapper : INetMessage, IPacketSerializable
	{
		public required ICustomMessage Message;

		private static List<Type>? _customMessages;

		private static readonly Dictionary<Type, int> CustomMessageToId = new Dictionary<Type, int>();

		private static readonly Dictionary<int, Type> IdToCustomMessage = new Dictionary<int, Type>();

		public static byte WrapperMessageId { get; set; }

		public static List<Type> CustomMessages
		{
			get
			{
				if (_customMessages == null)
				{
					_customMessages = ReflectionHelper.GetSubtypesInMods<ICustomMessage>().ToList();
					_customMessages.Sort((Type a, Type b) => string.Compare(a.FullName, b.FullName, StringComparison.Ordinal));
				}
				return _customMessages;
			}
		}

		public int MessageType => CustomMessageToId[Message.GetType()];

		public bool ShouldBroadcast => Message.ShouldBroadcast;

		public bool ShouldBuffer => Message.ShouldBuffer;

		public NetTransferMode Mode => Message.Mode;

		public LogLevel LogLevel => Message.LogLevel;

		public static void Initialize()
		{
			foreach (Type customMessage in CustomMessages)
			{
				int i;
				Type value;
				for (i = (customMessage.FullName ?? customMessage.Name).ComputeBasicHash(); IdToCustomMessage.TryGetValue(i, out value); i++)
				{
					BaseLibMain.Logger.Warn($"Message key hash collision: {value} and {customMessage} with key {i}");
				}
				IdToCustomMessage[i] = customMessage;
				CustomMessageToId[customMessage] = i;
			}
		}

		internal static void Register(INetGameService messageBuffer)
		{
			messageBuffer.RegisterMessageHandler<CustomMessageWrapper>(HandleCustomMessage);
		}

		internal static void Unregister(INetGameService messageBuffer)
		{
			messageBuffer.UnregisterMessageHandler<CustomMessageWrapper>(HandleCustomMessage);
		}

		private static void HandleCustomMessage(CustomMessageWrapper message, ulong senderId)
		{
			message.Message.HandleMessage(senderId);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(MessageType);
			Message.Serialize(writer);
		}

		public void Deserialize(PacketReader reader)
		{
			int key = reader.ReadInt();
			Type type = IdToCustomMessage[key];
			Message = (ICustomMessage)Activator.CreateInstance(type);
			Message.Deserialize(reader);
		}

		public static void Send(ICustomMessage msg, INetGameService? netService = null)
		{
			(netService ?? RunManager.Instance.NetService).SendMessage(new CustomMessageWrapper
			{
				Message = msg
			});
		}
	}
	public interface ICustomMessage : IPacketSerializable
	{
		bool ShouldBroadcast { get; }

		bool ShouldBuffer => true;

		NetTransferMode Mode => NetTransferMode.Reliable;

		LogLevel LogLevel => LogLevel.VeryDebug;

		void HandleMessage(ulong senderId);
	}
	public abstract class CustomModifierModel : ModifierModel, ICustomModel
	{
		public abstract ModifierAlignment Alignment { get; }

		public virtual IEnumerable<ModifierModel> MutuallyExclusiveGroup => Array.Empty<ModifierModel>();

		public virtual int SortOrder => 0;
	}
	public enum ModifierAlignment
	{
		None,
		Good,
		Bad
	}
	[HarmonyPatch(typeof(ModelDb))]
	internal static class ModelDbPatches
	{
		private static IEnumerable<CustomModifierModel>? _allCustomModifier;

		private static IReadOnlyList<IReadOnlySet<ModifierModel>>? _customMutuallyExclusive;

		private static IEnumerable<CustomModifierModel> AllCustomModifier => _allCustomModifier ?? (_allCustomModifier = (from t in ModelDb.AllAbstractModelSubtypes
			where t.IsSubclassOf(typeof(ModifierModel))
			select (ModifierModel)ModelDb.Get(t)).OfType<CustomModifierModel>().ToList());

		private static IReadOnlyList<IReadOnlySet<ModifierModel>> CustomMutuallyExclusive => _customMutuallyExclusive ?? (_customMutuallyExclusive = ((IEnumerable<HashSet<ModifierModel>>)AllCustomModifier.Where((CustomModifierModel m) => m.MutuallyExclusiveGroup.Any()).Aggregate(new List<HashSet<ModifierModel>>(), delegate(List<HashSet<ModifierModel>> groups, CustomModifierModel modifier)
		{
			HashSet<ModifierModel> members = modifier.MutuallyExclusiveGroup.Prepend(modifier).ToHashSet();
			groups.Where((HashSet<ModifierModel> g) => g.Overlaps(members)).ToList().ForEach(delegate(HashSet<ModifierModel> g)
			{
				groups.Remove(g);
				members.UnionWith(g);
			});
			groups.Add(members);
			return groups;
		})).Select((Func<HashSet<ModifierModel>, IReadOnlySet<ModifierModel>>)((HashSet<ModifierModel> g) => g)).ToList());

		[HarmonyPatch("GoodModifiers", MethodType.Getter)]
		[HarmonyPostfix]
		private static IReadOnlyList<ModifierModel> GoodModifiers(IReadOnlyList<ModifierModel> __result)
		{
			IOrderedEnumerable<CustomModifierModel> collection = from e in AllCustomModifier
				where e != null && e.Alignment == ModifierAlignment.Good && e.SortOrder < 0
				orderby e.SortOrder
				select e;
			IOrderedEnumerable<CustomModifierModel> collection2 = from e in AllCustomModifier
				where e != null && e.Alignment == ModifierAlignment.Good && e.SortOrder >= 0
				orderby e.SortOrder
				select e;
			List<ModifierModel> list = new List<ModifierModel>();
			list.AddRange(collection);
			list.AddRange(__result);
			list.AddRange(collection2);
			return new global::<>z__ReadOnlyList<ModifierModel>(list);
		}

		[HarmonyPatch("BadModifiers", MethodType.Getter)]
		[HarmonyPostfix]
		private static IReadOnlyList<ModifierModel> BadModifiers(IReadOnlyList<ModifierModel> __result)
		{
			IOrderedEnumerable<CustomModifierModel> collection = from e in AllCustomModifier
				where e != null && e.Alignment == ModifierAlignment.Bad && e.SortOrder < 0
				orderby e.SortOrder
				select e;
			IOrderedEnumerable<CustomModifierModel> collection2 = from e in AllCustomModifier
				where e != null && e.Alignment == ModifierAlignment.Bad && e.SortOrder >= 0
				orderby e.SortOrder
				select e;
			List<ModifierModel> list = new List<ModifierModel>();
			list.AddRange(collection);
			list.AddRange(__result);
			list.AddRange(collection2);
			return new global::<>z__ReadOnlyList<ModifierModel>(list);
		}

		[HarmonyPatch("MutuallyExclusiveModifiers", MethodType.Getter)]
		[HarmonyPostfix]
		private static IReadOnlyList<IReadOnlySet<ModifierModel>> MutuallyExclusiveModifiers(IReadOnlyList<IReadOnlySet<ModifierModel>> __result)
		{
			if (CustomMutuallyExclusive.Count == 0)
			{
				return __result;
			}
			return ((IEnumerable<HashSet<ModifierModel>>)CustomMutuallyExclusive.Aggregate(__result.Select((IReadOnlySet<ModifierModel> s) => s.ToHashSet()).ToList(), delegate(List<HashSet<ModifierModel>> groups, IReadOnlySet<ModifierModel> customGroup)
			{
				List<HashSet<ModifierModel>> list = groups.Where((HashSet<ModifierModel> g) => g.Overlaps(customGroup)).ToList();
				HashSet<ModifierModel> merged = customGroup.ToHashSet();
				list.ForEach(delegate(HashSet<ModifierModel> g)
				{
					groups.Remove(g);
					merged.UnionWith(g);
				});
				groups.Add(merged);
				return groups;
			})).Select((Func<HashSet<ModifierModel>, IReadOnlySet<ModifierModel>>)((HashSet<ModifierModel> g) => g)).ToList();
		}
	}
	public abstract class CustomMonsterModel : MonsterModel, ICustomModel, ISceneConversions
	{
		public virtual string? CustomVisualPath => null;

		public virtual string? CustomAttackSfx => null;

		public virtual string? CustomCastSfx => null;

		public virtual string? CustomDeathSfx => null;

		public CustomMonsterModel()
		{
			CustomContentDictionary.RegisterType(GetType());
		}

		public virtual NCreatureVisuals? CreateCustomVisuals()
		{
			return null;
		}

		public virtual CreatureAnimator? SetupCustomAnimationStates(MegaSprite controller)
		{
			return null;
		}

		public static CreatureAnimator SetupAnimationState(MegaSprite controller, string idleName, string? deadName = null, bool deadLoop = false, string? hitName = null, bool hitLoop = false, string? attackName = null, bool attackLoop = false, string? castName = null, bool castLoop = false)
		{
			AnimState animState = new AnimState(idleName, isLooping: true);
			AnimState state = ((deadName == null) ? animState : new AnimState(deadName, deadLoop));
			AnimState state2 = ((hitName == null) ? animState : new AnimState(hitName, hitLoop)
			{
				NextState = animState
			});
			AnimState state3 = ((attackName == null) ? animState : new AnimState(attackName, attackLoop)
			{
				NextState = animState
			});
			AnimState state4 = ((castName == null) ? animState : new AnimState(castName, castLoop)
			{
				NextState = animState
			});
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Idle", animState);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", state2);
			creatureAnimator.AddAnyState("Attack", state3);
			creatureAnimator.AddAnyState("Cast", state4);
			return creatureAnimator;
		}

		public void RegisterSceneConversions()
		{
			CustomVisualPath?.RegisterSceneForConversion<NCreatureVisuals>((Action<NCreatureVisuals>?)null);
		}
	}
