	[HarmonyPatch]
	internal static class CustomResourcePatches
	{
		internal static readonly List<ResourceHandler> RegisteredResources = new List<ResourceHandler>();

		[HarmonyPatch(typeof(PlayerCombatState), MethodType.Constructor, new Type[] { typeof(Player) })]
		[HarmonyPostfix]
		private static void Setup(PlayerCombatState __instance)
		{
			BaseLibMain.Logger.Debug($"Initializing custom resources ({RegisteredResources.Count}) at start of combat");
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.Prep(__instance);
			}
		}

		[HarmonyPatch(typeof(PlayerCombatState), "AfterCombatEnd")]
		[HarmonyPostfix]
		private static void Cleanup(PlayerCombatState __instance)
		{
			BaseLibMain.Logger.Debug($"Cleaning up custom resources ({RegisteredResources.Count}) at end of combat");
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.Cleanup(__instance);
			}
		}

		[HarmonyPatch(typeof(PlayerCombatState), "HasEnoughResourcesFor")]
		[HarmonyPostfix]
		private static void CheckAdditionalCosts(PlayerCombatState __instance, CardModel card, ref bool __result, ref UnplayableReason reason)
		{
			if (!__result)
			{
				return;
			}
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				UnplayableReason unplayableReason = registeredResource.ResourceCheck(__instance, card);
				if (unplayableReason != UnplayableReason.None)
				{
					reason = unplayableReason;
					__result = false;
					break;
				}
			}
		}

		[HarmonyPatch(typeof(CardModel), "SpendResources", MethodType.Async)]
		[HarmonyTranspiler]
		private static IEnumerable<CodeInstruction> AddSpendAdditionalCosts(ILGenerator generator, IEnumerable<CodeInstruction> instructions, MethodBase original)
		{
			return AsyncMethodCall.Create(generator, instructions, original, AccessTools.Method(typeof(CustomResourcePatches), "SpendAdditionalCosts"), null, original);
		}

		private static async Task SpendAdditionalCosts(CardModel __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				await registeredResource.Spend(__instance);
			}
		}

		[HarmonyPatch(typeof(CardPlay), "Card", MethodType.Setter)]
		[HarmonyPostfix]
		private static void RecordAdditionalCosts(CardPlay __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.RecordSpend(__instance);
			}
		}

		[HarmonyPatch(typeof(CardEnergyCost), "AfterCardPlayedCleanup")]
		[HarmonyPostfix]
		private static void CleanupAdditionalCosts(CardEnergyCost __instance)
		{
			CardModel card = __instance._card;
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.AfterCardPlayedCleanup(card);
			}
		}

		[HarmonyPatch(typeof(CardModel), "EndOfTurnCleanup")]
		[HarmonyPostfix]
		private static void CleanupEndOfTurn(CardModel __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.EndOfTurnCleanup(__instance);
			}
		}

		[HarmonyPatch(typeof(CardModel), "SetToFreeThisCombat")]
		[HarmonyPostfix]
		private static void SetToFreeThisCombat(CardModel __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.SetToFreeThisCombat(__instance);
			}
		}

		[HarmonyPatch(typeof(CardModel), "SetToFreeThisTurn")]
		[HarmonyPostfix]
		private static void SetToFreeThisTurn(CardModel __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.SetToFreeThisTurn(__instance);
			}
		}

		[HarmonyPatch(typeof(CardModel), "FinalizeUpgradeInternal")]
		[HarmonyPostfix]
		private static void FinalizeAdditionalResourceUpgrades(CardModel __instance)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.FinalizeUpgrade(__instance);
			}
		}

		[HarmonyPatch(typeof(CardModel), "DowngradeInternal")]
		[HarmonyTranspiler]
		private static List<CodeInstruction> DowngradeAdditionalResourcesTranspiler(IEnumerable<CodeInstruction> code)
		{
			return new InstructionPatcher(code).Match(new CallMatcher(typeof(CardEnergyCost).Method("ResetForDowngrade"))).Insert(new global::<>z__ReadOnlyArray<CodeInstruction>(new CodeInstruction[2]
			{
				CodeInstruction.LoadArgument(0),
				CodeInstruction.Call(typeof(CustomResourcePatches), "DowngradeAdditionalResources")
			}));
		}

		private static void DowngradeAdditionalResources(CardModel card)
		{
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.ResetForDowngrade(card);
			}
		}

		[HarmonyPatch(typeof(CardModel), "CostsEnergyOrStars")]
		[HarmonyPostfix]
		private static void OrAnotherResource(CardModel __instance, ref bool __result, bool includeGlobalModifiers)
		{
			if (__result)
			{
				return;
			}
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				if (registeredResource.CostsMoreThanZero(__instance, includeGlobalModifiers))
				{
					__result = true;
				}
			}
		}

		[HarmonyPatch(typeof(Hook), "AfterEnergyReset", MethodType.Async)]
		[HarmonyTranspiler]
		private static IEnumerable<CodeInstruction> AfterPlay(ILGenerator generator, IEnumerable<CodeInstruction> instructions, MethodBase original)
		{
			return AsyncMethodCall.Create(generator, instructions, original, AccessTools.Method(typeof(CustomResourcePatches), "BeforeEnergyResetHook"), original);
		}

		private static async Task BeforeEnergyResetHook(ICombatState combatState, Player player)
		{
			PlayerCombatState playerCombatState = player?.PlayerCombatState;
			if (playerCombatState == null)
			{
				return;
			}
			foreach (ResourceHandler registeredResource in RegisteredResources)
			{
				registeredResource.GetResource(playerCombatState).StartOfTurnReset(playerCombatState, combatState);
			}
		}
	}
	internal class ResourceHandler(string id, ICustomResourceVisualsHandler? visualsHandler, ICustomCostVisualsHandler? costVisualsHandler, Func<PlayerCombatState, CustomResource> getResource, Func<CardModel, ICustomResourceCost?> getCost, Action<PlayerCombatState> prep, Action<PlayerCombatState> cleanup, Func<PlayerCombatState, CardModel, UnplayableReason> resourceCheck, Func<CardModel, Task> spend, Action<CardPlay> recordSpend, Action<CardModel> afterCardPlayedCleanup, Action<CardModel> endOfTurnCleanup, Action<CardModel> setToFreeThisCombat, Action<CardModel> setToFreeThisTurn, Action<CardModel> finalizeUpgrade, Action<CardModel> resetForDowngrade, Func<CardModel, bool, bool> costsMoreThanZero) : IComparable<ResourceHandler>
	{
		public string Id { get; } = id;

		public ICustomResourceVisualsHandler? VisualsHandler { get; } = visualsHandler;

		public ICustomCostVisualsHandler? CostVisualsHandler { get; } = costVisualsHandler;

		public Func<PlayerCombatState, CustomResource> GetResource { get; } = getResource;

		public Func<CardModel, ICustomResourceCost?> GetCost { get; } = getCost;

		public Action<PlayerCombatState> Prep { get; } = prep;

		public Action<PlayerCombatState> Cleanup { get; } = cleanup;

		public Func<PlayerCombatState, CardModel, UnplayableReason> ResourceCheck { get; } = resourceCheck;

		public Func<CardModel, Task> Spend { get; } = spend;

		public Action<CardPlay> RecordSpend { get; } = recordSpend;

		public Action<CardModel> AfterCardPlayedCleanup { get; } = afterCardPlayedCleanup;

		public Action<CardModel> EndOfTurnCleanup { get; } = endOfTurnCleanup;

		public Action<CardModel> SetToFreeThisCombat { get; } = setToFreeThisCombat;

		public Action<CardModel> SetToFreeThisTurn { get; } = setToFreeThisTurn;

		public Action<CardModel> FinalizeUpgrade { get; } = finalizeUpgrade;

		public Action<CardModel> ResetForDowngrade { get; } = resetForDowngrade;

		public Func<CardModel, bool, bool> CostsMoreThanZero { get; } = costsMoreThanZero;

		public int CompareTo(ResourceHandler? other)
		{
			return string.Compare(Id, other?.Id, StringComparison.Ordinal);
		}
	}
	public static class CustomResources<T> where T : CustomResource, new()
	{
		private static bool _registered;

		private static NotNullSpireField<PlayerCombatState, T>? _resource;

		private static SpireField<CardModel, int>? _canonicalCost;

		private static SpireField<CardModel, CustomResourceCost<T>?>? _cost;

		private static SpireField<CardModel, int>? _lastSpend;

		private static SpireField<CardPlay, int>? _recordedSpend;

		private static SpireField<CardModel, int> CanonicalCostField => _canonicalCost ?? (_canonicalCost = new SpireField<CardModel, int>(() => -1).CopyOnClone());

		private static NotNullSpireField<PlayerCombatState, T> Resource => _resource ?? (_resource = new NotNullSpireField<PlayerCombatState, T>(delegate(PlayerCombatState playerCombatState)
		{
			BaseLibMain.Logger.Debug("Initializing resource " + typeof(T).Name + " for combat");
			T val = new T();
			val.PrepForCombat(playerCombatState);
			val.AmountChanged += CombatManager.Instance.StateTracker.OnPlayerCombatStateValueChanged;
			return val;
		}));

		private static SpireField<CardModel, CustomResourceCost<T>?> CostField => _cost ?? (_cost = new SpireField<CardModel, CustomResourceCost<T>>(() => (CustomResourceCost<T>?)null).CopyOnClone(delegate(CardModel source, CardModel dest, CustomResourceCost<T>? original)
		{
			CostField[dest] = original?.Clone(dest);
		}));

		private static SpireField<CardModel, int> LastSpend => _lastSpend ?? (_lastSpend = new SpireField<CardModel, int>(() => -1));

		private static SpireField<CardPlay, int> RecordedSpend => _recordedSpend ?? (_recordedSpend = new SpireField<CardPlay, int>(() => 0));

		internal static void Register(T resourceInstance)
		{
			if (!_registered)
			{
				_registered = true;
				ICustomResourceVisualsHandler visualsHandler = resourceInstance.ResourceVisualsHandler();
				ICustomCostVisualsHandler costVisualsHandler = resourceInstance.CostVisualsHandler();
				CustomResourcePatches.RegisteredResources.InsertSorted(new ResourceHandler(resourceInstance.Id, visualsHandler, costVisualsHandler, Get, Cost, PrepForCombat, CleanupAfterCombat, ResourceCheck, Spend, RecordSpend, AfterCardPlayedCleanup, EndOfTurnCleanup, SetToFreeThisCombat, SetToFreeThisTurn, FinalizeUpgrade, ResetForDowngrade, CostsMoreThanZero));
			}
		}

		private static void PrepForCombat(PlayerCombatState combatState)
		{
			Resource.Get(combatState);
		}

		private static void CleanupAfterCombat(PlayerCombatState combatState)
		{
			Resource.Get(combatState).AmountChanged -= CombatManager.Instance.StateTracker.OnPlayerCombatStateValueChanged;
		}

		private static UnplayableReason ResourceCheck(PlayerCombatState combatState, CardModel card)
		{
			return Cost(card)?.ResourceCheck(combatState, card) ?? UnplayableReason.None;
		}

		private static async Task Spend(CardModel card)
		{
			CustomResourceCost<T> customResourceCost = Cost(card);
			LastSpend[card] = -1;
			if (customResourceCost != null)
			{
				int spend = customResourceCost.GetAmountToSpend();
				if (await Resource.Get(card.Owner.PlayerCombatState).Spend<T>(card.CombatState, card, spend, customResourceCost.IsOptional(card.Owner)))
				{
					LastSpend[card] = spend;
				}
			}
		}

		private static void RecordSpend(CardPlay cardPlay)
		{
			RecordedSpend[cardPlay] = LastSpend[cardPlay.Card];
			BaseLibMain.Logger.Debug($"Recorded spend: {LastSpend[cardPlay.Card]}");
		}

		private static void AfterCardPlayedCleanup(CardModel card)
		{
			Cost(card)?.AfterCardPlayedCleanup();
		}

		private static void EndOfTurnCleanup(CardModel card)
		{
			CustomResourceCost<T>? customResourceCost = Cost(card);
			if (customResourceCost != null && customResourceCost.EndOfTurnCleanup())
			{
				card.InvokeEnergyCostChanged();
			}
		}

		private static void SetToFreeThisCombat(CardModel card)
		{
			CustomResourceCost<T> customResourceCost = Cost(card);
			if (customResourceCost != null && Resource.Get(card.Owner.PlayerCombatState).ApplySharedModification)
			{
				customResourceCost.SetThisCombat(0);
			}
		}

		private static void SetToFreeThisTurn(CardModel card)
		{
			CustomResourceCost<T> customResourceCost = Cost(card);
			if (customResourceCost != null && Resource.Get(card.Owner.PlayerCombatState).ApplySharedModification)
			{
				customResourceCost.SetThisTurnOrUntilPlayed(0);
			}
		}

		private static void FinalizeUpgrade(CardModel card)
		{
			Cost(card)?.FinalizeUpgrade();
		}

		private static void ResetForDowngrade(CardModel card)
		{
			Cost(card)?.ResetForDowngrade();
		}

		private static bool CostsMoreThanZero(CardModel card, bool includeGlobalModifiers)
		{
			CustomResourceCost<T> customResourceCost = Cost(card);
			if (customResourceCost == null || customResourceCost.CostsX)
			{
				return false;
			}
			return customResourceCost.GetWithModifiers(includeGlobalModifiers ? CostModifiers.All : CostModifiers.Local) > 0;
		}

		public static T Get(PlayerCombatState combatState)
		{
			return Resource[combatState];
		}

		public static bool TryGet(PlayerCombatState? combatState, [NotNullWhen(true)] out T? result)
		{
			result = null;
			if (combatState == null)
			{
				return false;
			}
			result = Resource[combatState];
			return true;
		}

		public static void SetCanonicalCost(CardModel card, int canonicalCost)
		{
			CanonicalCostField[card] = canonicalCost;
		}

		public static void SetXCost(CardModel card)
		{
			CanonicalCostField[card] = int.MinValue;
		}

		public static int CanonicalCost(CardModel card)
		{
			return CanonicalCostField[card];
		}

		public static CustomResourceCost<T>? Cost(CardModel card)
		{
			CustomResourceCost<T> customResourceCost = CostField[card];
			if (customResourceCost != null)
			{
				return customResourceCost;
			}
			int num = CanonicalCostField[card];
			if (num == -1)
			{
				return null;
			}
			bool flag = num == int.MinValue;
			return CostField[card] = new CustomResourceCost<T>(card, (!flag) ? num : 0, flag);
		}

		public static int AmountSpent(CardPlay play)
		{
			return RecordedSpend[play];
		}

		public static bool WasSpent(CardPlay play)
		{
			return RecordedSpend[play] >= 0;
		}
	}
