					{
						PowerType.Buff => PowerType.Debuff, 
						PowerType.Debuff => PowerType.Buff, 
						_ => PowerType.None, 
					};
				}
				return InternallyAppliedPower.Type;
			}
		}

		public override PowerStackType StackType => PowerStackType.Counter;

		public override bool AllowNegative => true;

		protected virtual bool InvertInternalPowerAmount => false;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new RepeatVar(0),
			new BoolVar("UntilEndOfOtherSideTurn", value: false)
		});

		public void AddDumbVariablesToPowerDescription(LocString description)
		{
			description.Add("TemporaryPowerTitle", InternallyAppliedPower.Title);
		}

		public void IgnoreNextInstance()
		{
			_shouldIgnoreNextInstance = true;
		}

		public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (InternallyAppliedPower is CustomTemporaryPowerModel)
			{
				BaseLibMain.Logger.Warn($"Don't put TemporaryPowerModels into a TemporaryPowerModel. Attempted to apply power '{InternallyAppliedPower.GetType().Name}' in power '{GetType().Name}'. Power will not be applied!");
			}
			else if (_shouldIgnoreNextInstance)
			{
				_shouldIgnoreNextInstance = false;
			}
			else
			{
				base.DynamicVars.Repeat.BaseValue = LastForXExtraTurns;
				base.DynamicVars["UntilEndOfOtherSideTurn"].BaseValue = Convert.ToDecimal(UntilEndOfOtherSideTurn);
				await ApplyPowerFunc(new ThrowingPlayerChoiceContext(), target, InvertInternalPowerAmount ? (-amount) : amount, applier, cardSource, arg6: true);
			}
		}

		public override async Task AfterPowerAmountChanged(PlayerChoiceContext context, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			CustomTemporaryPowerModel customTemporaryPowerModel = this;
			if (!(InternallyAppliedPower is CustomTemporaryPowerModel) && !(amount == (decimal)customTemporaryPowerModel.Amount) && power == customTemporaryPowerModel)
			{
				if (customTemporaryPowerModel._shouldIgnoreNextInstance)
				{
					customTemporaryPowerModel._shouldIgnoreNextInstance = false;
				}
				else
				{
					await ApplyPowerFunc(context, customTemporaryPowerModel.Owner, InvertInternalPowerAmount ? (-amount) : amount, applier, cardSource, arg6: true);
				}
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner) != UntilEndOfOtherSideTurn)
			{
				if (InternallyAppliedPower is CustomTemporaryPowerModel)
				{
					await PowerCmd.Remove(this);
					return;
				}
				if (base.DynamicVars.Repeat.BaseValue > 0m)
				{
					base.DynamicVars.Repeat.UpgradeValueBy(-1m);
					return;
				}
				Flash();
				await ApplyPowerFunc(choiceContext, base.Owner, InvertInternalPowerAmount ? base.Amount : (-base.Amount), base.Owner, null, arg6: true);
				await PowerCmd.Remove(this);
			}
		}
	}
