		public override LocString Title
		{
			get
			{
				AbstractModel originModel = OriginModel;
				if (!(originModel is CardModel cardModel))
				{
					if (!(originModel is PotionModel potionModel))
					{
						if (!(originModel is RelicModel relicModel))
						{
							if (!(originModel is PowerModel powerModel))
							{
								if (!(originModel is OrbModel orbModel))
								{
									if (!(originModel is CharacterModel characterModel))
									{
										if (!(originModel is MonsterModel monsterModel))
										{
											if (!(originModel is ActModel actModel))
											{
												if (!(originModel is EnchantmentModel enchantmentModel))
												{
													if (!(originModel is AfflictionModel afflictionModel))
													{
														if (!(originModel is EncounterModel encounterModel))
														{
															if (!(originModel is EventModel eventModel))
															{
																if (!(originModel is ModifierModel modifierModel))
																{
																	if (originModel is CardModifier cardModifier)
																	{
																		return cardModifier.Owner?.TitleLocString ?? new LocString("powers", "BASELIB-CUSTOM_TEMPORARY_POWER_MODEL.title");
																	}
																	BaseLibMain.Logger.Warn("Getting the 'Title' for the base model type of '" + OriginModel.GetType().Name + "' has not been implemented yet. Using default title.");
																	return new LocString("powers", "BASELIB-CUSTOM_TEMPORARY_POWER_MODEL.title");
																}
																return modifierModel.Title;
															}
															return eventModel.Title;
														}
														return encounterModel.Title;
													}
													return afflictionModel.Title;
												}
												return enchantmentModel.Title;
											}
											return actModel.Title;
										}
										return monsterModel.Title;
									}
									return characterModel.Title;
								}
								return orbModel.Title;
							}
							return powerModel.Title;
						}
						return relicModel.Title;
					}
					return potionModel.Title;
				}
				return cardModel.TitleLocString;
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				AbstractModel originModel = OriginModel;
				List<IHoverTip> list2;
				if (!(originModel is CardModel card))
				{
					if (!(originModel is PotionModel model))
					{
						if (!(originModel is RelicModel relic))
						{
							if (!(originModel is PowerModel model2))
							{
								if (!(originModel is ActModel) && !(originModel is EncounterModel) && !(originModel is EventModel))
								{
									if (!(originModel is EnchantmentModel enchantmentModel))
									{
										if (!(originModel is AfflictionModel afflictionModel))
										{
											if (!(originModel is ModifierModel modifierModel))
											{
												if (originModel is CardModifier cardModifier)
												{
													List<IHoverTip> list;
													if (cardModifier.Owner == null)
													{
														list = new List<IHoverTip>();
													}
													else
													{
														int num = 1;
														list = new List<IHoverTip>(num);
														CollectionsMarshal.SetCount(list, num);
														Span<IHoverTip> span = CollectionsMarshal.AsSpan(list);
														int index = 0;
														span[index] = HoverTipFactory.FromCard(cardModifier.Owner);
													}
													list2 = list;
												}
												else
												{
													BaseLibMain.Logger.Warn("Getting the Hover Tips for the base model type of '" + OriginModel.GetType().Name + "' has not been implemented yet.");
													list2 = new List<IHoverTip>();
												}
											}
											else
											{
												list2 = modifierModel.HoverTips.ToList();
											}
										}
										else
										{
											AfflictionModel obj = (AfflictionModel)afflictionModel.MutableClone();
											obj.Amount = base.Amount;
											list2 = obj.HoverTips.ToList();
										}
									}
									else
									{
										EnchantmentModel obj2 = (EnchantmentModel)enchantmentModel.MutableClone();
										obj2.Amount = base.Amount;
										obj2.RecalculateValues();
										list2 = obj2.HoverTips.ToList();
									}
								}
								else
								{
									list2 = new List<IHoverTip>();
								}
							}
							else
							{
								int index = 1;
								List<IHoverTip> list3 = new List<IHoverTip>(index);
								CollectionsMarshal.SetCount(list3, index);
								Span<IHoverTip> span2 = CollectionsMarshal.AsSpan(list3);
								int num = 0;
								span2[num] = HoverTipFactory.FromPower(model2);
								list2 = list3;
							}
						}
						else
						{
							list2 = HoverTipFactory.FromRelic(relic).ToList();
						}
					}
					else
					{
						int num = 1;
						List<IHoverTip> list4 = new List<IHoverTip>(num);
						CollectionsMarshal.SetCount(list4, num);
						Span<IHoverTip> span3 = CollectionsMarshal.AsSpan(list4);
						int index = 0;
						span3[index] = HoverTipFactory.FromPotion(model);
						list2 = list4;
					}
				}
				else
				{
					int index = 1;
					List<IHoverTip> list5 = new List<IHoverTip>(index);
					CollectionsMarshal.SetCount(list5, index);
					Span<IHoverTip> span4 = CollectionsMarshal.AsSpan(list5);
					int num = 0;
					span4[num] = HoverTipFactory.FromCard(card);
					list2 = list5;
				}
				list2.Add(HoverTipFactory.FromPower(InternallyAppliedPower));
				return list2;
			}
		}

